def _regular_entry(path: Path, *, root: Path = ROOT) -> dict[str, Any]:
    relative = path.relative_to(root).as_posix() if path.is_relative_to(root) else str(path)
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        before = os.fstat(fd)
        digest = hashlib.sha256()
        while True:
            chunk = os.read(fd, 8 << 20)
            if not chunk:
                break
            digest.update(chunk)
        after = os.fstat(fd)
    finally:
        os.close(fd)
    path_st = path.lstat()
    identity = (before.st_dev, before.st_ino, before.st_mode, before.st_uid,
                before.st_gid,
                before.st_nlink, before.st_size)
    if (identity != (after.st_dev, after.st_ino, after.st_mode, after.st_uid,
                     after.st_gid,
                     after.st_nlink, after.st_size)
            or (before.st_dev, before.st_ino) != (path_st.st_dev, path_st.st_ino)
            or not stat.S_ISREG(before.st_mode) or stat.S_ISLNK(path_st.st_mode)
            or before.st_uid != os.getuid() or before.st_gid != os.getgid()
            or before.st_nlink != 1):
        raise ValueError(f"candidate/closure file identity drift: {path}")
    return {
        "path": relative, "type": "regular", "mode": stat.S_IMODE(before.st_mode),
        "uid": before.st_uid, "gid": before.st_gid, "nlink": before.st_nlink,
        "size": before.st_size,
        "sha256": digest.hexdigest(), "verification_action": "content_rehash",
    }


def _path_present(path: Path) -> bool:
    return path.exists() or path.is_symlink()


def _write_all(fd: int, payload: bytes) -> None:
    """Write an exact payload or fail; os.write is permitted to short-write."""
    offset = 0
    while offset < len(payload):
        written = os.write(fd, payload[offset:])
        if written <= 0:
            raise OSError("zero-length write before payload completion")
        offset += written


def _regular_bytes(path: Path, *, mode: int, owner: int | None = None) -> bytes:
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        before = os.fstat(fd)
        chunks = []
        while True:
            chunk = os.read(fd, 8 << 20)
            if not chunk:
                break
            chunks.append(chunk)
        after = os.fstat(fd)
    finally:
        os.close(fd)
    path_st = path.lstat()
    expected_owner = os.getuid() if owner is None else owner
    if ((before.st_dev, before.st_ino, before.st_mode, before.st_uid, before.st_nlink,
         before.st_size, before.st_mtime_ns, before.st_ctime_ns) !=
        (after.st_dev, after.st_ino, after.st_mode, after.st_uid, after.st_nlink,
         after.st_size, after.st_mtime_ns, after.st_ctime_ns)
            or (before.st_dev, before.st_ino) != (path_st.st_dev, path_st.st_ino)
            or not stat.S_ISREG(before.st_mode) or stat.S_ISLNK(path_st.st_mode)
            or stat.S_IMODE(before.st_mode) != mode or before.st_uid != expected_owner
            or before.st_nlink != 1):
        raise ValueError(f"regular-file identity/mode/ownership drift: {path}")
    return b"".join(chunks)


def _read_root_json(root: Path, relative: str) -> Any:
    return base.strict_json_loads((root / relative).read_text(encoding="utf-8"))


def generic_config_projection(config: Mapping[str, Any]) -> dict[str, Any]:
    """Return the exact config schema accepted by the reviewed generic builders."""
    expected = set(GENERIC_CONFIG_KEYS) | set(SUCCESSOR_CONFIG_KEYS)
    if set(config) != expected:
        raise ValueError(f"successor config key mismatch: {sorted(set(config) ^ expected)}")
    return {key: config[key] for key in GENERIC_CONFIG_KEYS}


def generic_replay_bundle(bundle: Mapping[str, Any], generic_config_sha256: str) -> dict[str, Any]:
    expected = {"schema_version", "protocol_config_sha256", "replay_registry_sha256",
                "source_role", "source_revision", "partition", "observations"}
    if set(bundle) != expected:
        raise ValueError(f"successor replay-bundle key mismatch: {sorted(set(bundle) ^ expected)}")
    base.validate_sha256(generic_config_sha256, "generic protocol config SHA-256")
    return {**dict(bundle), "protocol_config_sha256": generic_config_sha256}


def _validate_m2_semantics(*, root: Path = ROOT) -> dict[str, Any]:
    prefix = "data/msae_independent_measurement_v3"
    task = _read_root_json(root, f"{prefix}/task_manifest.json")
    support = _read_root_json(root, f"{prefix}/support.json")
    templates = _read_root_json(root, f"{prefix}/prefix_templates.json")
    maps = _read_root_json(root, f"{prefix}/maps.json")
    matrix = _read_root_json(root, f"{prefix}/finite_pass_matrix.json")
    imports = _read_root_json(root, f"{prefix}/protocol_imports.json")
    if (task.get("schema_version") != "msae_v3_task_manifest_v1"
            or task.get("protocol_id") != PROTOCOL
            or task.get("roles") != list(base.ROLES) or task.get("tasks") != list(base.TASKS)
            or task.get("label_rows") != 1491748):
        raise ValueError("M2 task-manifest semantics drift")
    audit = task.get("amalgum_legacy_upos_repair", {}).get("audit", {})
    denominators = {name: [row.get("population_token_count"), row.get("correction_token_count")]
                    for name, row in audit.get("ledgers", {}).items()}
    if denominators != {"raw_selected": [290192, 36], "tokenizable": [286938, 20],
                        "retained_after_cap": [89600, 11]}:
        raise ValueError("M2 correction-ledger semantics drift")
    if (support.get("schema_version") != "msae_v3_support_v1"
            or support.get("status") != "eligible" or set(support.get("roles", {})) != set(base.ROLES)):
        raise ValueError("M2 support semantics drift")
    if any(set(support["roles"][role]) != set(base.TASKS)
           or any(support["roles"][role][task_name].get("status") != "eligible"
                  for task_name in base.TASKS) for role in base.ROLES):
        raise ValueError("M2 role/task support is incomplete")
    template_rows = templates.get("templates")
    if (templates.get("schema_version") != "msae_v3_prefix_templates_v1"
            or not isinstance(template_rows, list) or len(template_rows) != 4
            or [row.get("literal") for row in template_rows] != list(base.PREFIXES)
            or len({row.get("length") for row in template_rows}) != 4):
        raise ValueError("M2 prefix-template semantics drift")
    entries = maps.get("map_entries")
    if (maps.get("schema_version") != "msae_v3_bootstrap_maps_v1"
            or maps.get("draws_per_role_task") != 500 or not isinstance(entries, list)
            or len(entries) != len(base.ROLES) * len(base.TASKS) * 500):
        raise ValueError("M2 map registry dimensions drift")
    keys = {(row.get("role"), row.get("task"), row.get("draw")) for row in entries}
    expected_keys = {(role, task_name, draw) for role in base.ROLES
                     for task_name in base.TASKS for draw in range(500)}
    if keys != expected_keys or len(keys) != len(entries):
        raise ValueError("M2 map registry keys are incomplete or duplicated")
    finite = collections.Counter((row["role"], row["task"]) for row in entries
                                 if row.get("finite") is True and row.get("reasons") == [])
    if any(row.get("finite") not in {True, False}
           or base.HEX_RE.fullmatch(str(row.get("map_sha256"))) is None for row in entries):
        raise ValueError("M2 map entry type/digest drift")
    expected_matrix = {role: {task_name: finite[(role, task_name)] for task_name in base.TASKS}
                       for role in base.ROLES}
    if (matrix.get("schema_version") != "msae_v3_finite_pass_matrix_v1"
            or matrix.get("status") != "eligible" or matrix.get("minimum_finite_draws") != 490
            or matrix.get("finite_draw_counts") != expected_matrix
            or any(count != 500 for values in expected_matrix.values() for count in values.values())
            or matrix.get("map_payload_sha256") != base.sha_file(root / prefix / "maps.json")):
        raise ValueError("M2 finite-pass matrix does not close over maps")
    if imports.get("schema_version") != "msae_v3_protocol_imports_v1":
        raise ValueError("M2 protocol-import semantics drift")
    return {"label_rows": 1491748, "role_task_cells": 68, "map_entries": len(entries),
            "finite_draws_per_cell": 500, "support_status": "eligible",
            "finite_pass_status": "eligible", "correction_denominators": denominators}


@contextlib.contextmanager
def _later_data_projection() -> Iterable[None]:
    original = base._phase_data_names
    def names(phase: str) -> set[str]:
        result = original(phase)
        if phase in {"M1", "M2"}:
            result |= {name for name in base.V3_DATA_PHASE_FILES["M4"]
                       if (V3_DATA / name).exists()}
        return result
    base._phase_data_names = names
    try:
        yield
    finally:
        base._phase_data_names = original


def _m2_completion_payload() -> dict[str, Any]:
    with _later_data_projection():
        continuation.verify_m1_completion(M1_REVIEWED_COMPLETION_SHA256, allow_m2_recovery=True)
        base.verify_baseline_projection("M2")
    entries = [_regular_entry(V3_DATA / name) for name in base.V3_DATA_PHASE_FILES["M2"]]
    return {"schema_version": "msae_v3_m2_completion_manifest_v1", "protocol_id": PROTOCOL,
            "reviewed_m1_completion_sha256": M1_REVIEWED_COMPLETION_SHA256,
            "entries": entries, "entry_count": len(entries),
            "entries_sha256": base.sha_bytes(base.canonical_bytes(entries)),
            "success_semantics": _validate_m2_semantics(),
            "status": "m2_support_and_maps_eligible_ready_for_independent_review_pin"}


def build_m2_completion() -> dict[str, Any]:
    raise RuntimeError("gen3 cannot construct or replace the immutable M2 completion")


def verify_m2_completion(reviewed_sha256: str) -> dict[str, Any]:
    # Verifier ownership remains with the exact immutable gen2 runtime that
    # created and reviewed this completion. Gen3 may only consume its result.
    return predecessor_runtime.verify_m2_completion(reviewed_sha256)


def checkpoint_registry(*, root: Path = ROOT) -> list[dict[str, Any]]:
    specs = [
        ("g4", 42, "inc1e2", "final_step249244_tok1000000016.pt", "replicate"),
        ("g5", 43, "inc1e2", "final_step249244_tok1000000016.pt", "replicate"),
        ("g6", 44, "inc1e2", "final_step249675_tok1000000042.pt", "replicate"),
        ("g7", 42, "inc0", "final_step249244_tok1000000016.pt", "matched_negative_control"),
    ]
    rows: list[dict[str, Any]] = []
    for checkpoint_id, seed, suffix, filename, role in specs:
        run_id = f"k2_wave2_fast_{checkpoint_id}_L3_s{seed}_{suffix}"
        relative_root = (Path("pilot_runs/20260601_132158_k2_msae_wave2_fastdata_stream/outputs") /
                         run_id)
        checkpoint = root / relative_root / "checkpoints" / filename
        summary = root / relative_root / "train_summary.json"
        metrics = root / relative_root / "train_metrics.jsonl"
        payload = base.strict_json_loads(summary.read_text(encoding="utf-8"))
        if payload.get("seed") != seed or payload.get("layer_index") != 3:
            raise ValueError(f"checkpoint summary mismatch: {checkpoint_id}")
        rows.append({
            "checkpoint_id": checkpoint_id, "role": role, "seed": seed,
            "training_run_id": run_id,
            "checkpoint_path": (relative_root / "checkpoints" / filename).as_posix(),
            "checkpoint_size": checkpoint.stat().st_size,
            "checkpoint_sha256": base.sha_file(checkpoint),
            "summary_path": (relative_root / "train_summary.json").as_posix(),
            "summary_sha256": base.sha_file(summary),
            "metrics_path": (relative_root / "train_metrics.jsonl").as_posix(),
            "metrics_sha256": base.sha_file(metrics),
            "tokens_seen": payload["tokens_seen"], "lambda_inc": payload["lambda_inc"],
            "training_git_state": payload["git_commit_hash"],
        })
    if ([row["checkpoint_id"] for row in rows] != ["g4", "g5", "g6", "g7"]
            or [row["role"] for row in rows] != ["replicate", "replicate", "replicate", "matched_negative_control"]
            or len({row["seed"] for row in rows[:3]}) != 3
            or len({row["checkpoint_sha256"] for row in rows[:3]}) != 3
            or any(base.HEX_RE.fullmatch(row["checkpoint_sha256"]) is None for row in rows)):
        raise ValueError("checkpoint lineage registry does not meet the frozen design")
    if rows[3]["seed"] != rows[0]["seed"] or rows[3]["lambda_inc"] == rows[0]["lambda_inc"]:
        raise ValueError("g7 is not the frozen matched negative control")
    return rows


def _expected_endpoint_keys() -> set[tuple[Any, ...]]:
    """Independently enumerate the frozen endpoint product.

    This deliberately returns typed tuples rather than endpoint IDs so a bug in
    string formatting cannot make construction and validation agree.
    """
    keys: set[tuple[Any, ...]] = set()
    localization_metrics = ("recovery", "leakage", "selectivity")
    for role, checkpoints, components in (
        ("C1", ("raw",), ("raw_full", "simple_family_projection",
                          "simple_family_complement", "simple_family_residual")),
        ("C2", ("g4", "g5", "g6", "g7"),
         ("assigned", "nonassigned", "joint", "complement", "residual")),
    ):
        for checkpoint in checkpoints:
            for family, tasks in FAMILIES.items():
                for task_name in tasks:
                    for component in components:
                        for metric in localization_metrics:
                            keys.add(("localization", role, checkpoint, family,
                                      task_name, component, metric, 3))
    for family, tasks in FAMILIES.items():
        for task_name in tasks:
            for metric in localization_metrics:
                keys.add(("functional_reproducibility", "C2", ("g4", "g5", "g6"),
                          "g7_descriptive_only", family, "task", task_name, metric))
        for metric in localization_metrics:
            keys.add(("functional_reproducibility", "C2", ("g4", "g5", "g6"),
                      "g7_descriptive_only", family, "family_summary", None, metric))
    for role, checkpoints, components in (
        ("C1", ("raw",), ("raw_full", "simple_family_projection",
                            "simple_family_complement", "simple_family_residual")),
        ("C2", ("g4", "g5", "g6", "g7"),
         ("assigned", "nonassigned", "joint", "complement", "residual")),
    ):
        for checkpoint in checkpoints:
            for component in components:
                for task_name in TIER2:
                    for metric in ("recovery", "retention", "leakage"):
                        keys.add(("collateral", role, checkpoint, component, task_name, metric))
    for checkpoint in ("g4", "g5", "g6", "g7"):
        for transform in TRANSFORMS:
            for control in CONTROLS:
                keys.add(("counterfactual", "C2", checkpoint, transform, control))
    for role in base.ROLES:
        for baseline in BASELINES:
            keys.add(("baseline", role, baseline))
    return keys


def _endpoint_key(row: Mapping[str, Any]) -> tuple[Any, ...]:
    category = row.get("category")
    if category == "localization":
        return (category, row.get("role"), row.get("checkpoint"), row.get("family"),
                row.get("task"), row.get("component"), row.get("metric"), row.get("layer"))
    if category == "functional_reproducibility":
        checkpoints = row.get("checkpoints")
        return (category, row.get("role"), tuple(checkpoints) if isinstance(checkpoints, list) else None,
                row.get("control"), row.get("family"), row.get("summary_level"),
                row.get("task"), row.get("metric"))
    if category == "collateral":
        return (category, row.get("role"), row.get("checkpoint"), row.get("component"),
                row.get("task"), row.get("metric"))
    if category == "counterfactual":
        return (category, row.get("role"), row.get("checkpoint"), row.get("transform"), row.get("control"))
    if category == "baseline":
        return (category, row.get("role"), row.get("baseline"))
    raise ValueError(f"unknown endpoint category: {category!r}")


def validate_endpoint_registry(value: Mapping[str, Any]) -> dict[str, Any]:
    entries = value.get("entries")
    if not isinstance(entries, list):
        raise ValueError("endpoint entries are not an array")
    keys = [_endpoint_key(row) for row in entries]
    expected = _expected_endpoint_keys()
    if len(keys) != len(set(keys)) or set(keys) != expected:
        missing = expected - set(keys)
        extra = set(keys) - expected
        raise ValueError(f"endpoint product mismatch: missing={len(missing)} extra={len(extra)}")
    ids = [row.get("endpoint_id") for row in entries]
    if any(not isinstance(item, str) or not item for item in ids) or len(ids) != len(set(ids)):
        raise ValueError("endpoint IDs are missing or duplicated")
    def expected_id(key: tuple[Any, ...]) -> str:
        category = key[0]
        if category == "localization":
            _, role, checkpoint, family, task, component, metric, layer = key
            return f"{role}.{checkpoint}.{family}.{task}.{component}.{metric}.L{layer}"
        if category == "functional_reproducibility":
            _, _, checkpoints, _, family, level, task, metric = key
            unit = task if level == "task" else "family_summary"
            return f"{'_'.join(checkpoints)}.{family}.{unit}.{metric}.spread"
        if category == "collateral":
            _, role, checkpoint, component, task, metric = key
            return f"{role}.{checkpoint}.{component}.{task}.{metric}.L3"
        if category == "counterfactual":
            _, role, checkpoint, transform, control = key
            return f"{role}.{checkpoint}.{transform}.{control}.L3"
        _, role, baseline = key
        return f"{role}.{baseline}.registered"
    if any(row["endpoint_id"] != expected_id(key) for row, key in zip(entries, keys)):
        raise ValueError("endpoint ID is not the canonical typed-key encoding")
    for row in entries:
        required = (["maximum_spread", "uncertainty", "status"]
                    if row["category"] == "functional_reproducibility"
                    else ["estimate", "uncertainty", "status"]
                    if row["category"] == "collateral" else None)
        if required is not None and row.get("required_output_fields") != required:
            raise ValueError("endpoint required-output schema mismatch")
    counts = collections.Counter(row["category"] for row in entries)
    expected_counts = collections.Counter(key[0] for key in expected)
    if (value.get("schema_version") != "msae_v3_endpoint_registry_v2"
            or value.get("protocol_id") != PROTOCOL
            or value.get("endpoint_count") != len(expected)
            or value.get("category_counts") != dict(expected_counts)
            or value.get("endpoint_id_set_sha256") !=
               base.sha_bytes(base.canonical_bytes(sorted(ids)))):
        raise ValueError("endpoint registry summary mismatch")
    if (value.get("families") != {key: list(rows) for key, rows in FAMILIES.items()}
            or value.get("tier2_tasks") != list(TIER2)
            or value.get("counterfactual_transforms") != list(TRANSFORMS)
            or value.get("counterfactual_controls") != list(CONTROLS)
            or value.get("baselines") != list(BASELINES)
            or value.get("g7_interpretation") != "matched_negative_control_not_replicate"
            or value.get("C1_scope") != "raw_simple_G1_operands_only"
            or value.get("C2_scope") != "G2_and_descriptive_control"):
        raise ValueError("endpoint registry metadata mismatch")
    return dict(value)


def endpoint_registry() -> dict[str, Any]:
    entries: list[dict[str, Any]] = []
    for role in ("C1", "C2"):
        checkpoints = ("raw",) if role == "C1" else ("g4", "g5", "g6", "g7")
        components = ("raw_full", "simple_family_projection", "simple_family_complement", "simple_family_residual") if role == "C1" else ("assigned", "nonassigned", "joint", "complement", "residual")
        for checkpoint in checkpoints:
            for family, tasks in FAMILIES.items():
                for task_name in tasks:
                    for component in components:
                        for metric in ("recovery", "leakage", "selectivity"):
                            entries.append({"category": "localization", "role": role,
                                            "checkpoint": checkpoint, "family": family,
                                            "task": task_name, "component": component,
                                            "metric": metric, "layer": 3,
                                            "endpoint_id": f"{role}.{checkpoint}.{family}.{task_name}.{component}.{metric}.L3"})
    for family, tasks in FAMILIES.items():
        for task_name in tasks:
            for metric in ("recovery", "leakage", "selectivity"):
                entries.append({"category": "functional_reproducibility", "role": "C2",
                                "checkpoints": ["g4", "g5", "g6"], "control": "g7_descriptive_only",
                                "family": family, "summary_level": "task", "task": task_name,
                                "metric": metric,
                                "required_output_fields": ["maximum_spread", "uncertainty", "status"],
                                "endpoint_id": f"g4_g5_g6.{family}.{task_name}.{metric}.spread"})
        for metric in ("recovery", "leakage", "selectivity"):
            entries.append({"category": "functional_reproducibility", "role": "C2",
                            "checkpoints": ["g4", "g5", "g6"], "control": "g7_descriptive_only",
                            "family": family, "summary_level": "family_summary", "task": None,
                            "metric": metric,
                            "required_output_fields": ["maximum_spread", "uncertainty", "status"],
                            "endpoint_id": f"g4_g5_g6.{family}.family_summary.{metric}.spread"})
    for role in ("C1", "C2"):
        checkpoints = ("raw",) if role == "C1" else ("g4", "g5", "g6", "g7")
        components = (("raw_full", "simple_family_projection", "simple_family_complement",
                       "simple_family_residual") if role == "C1"
                      else ("assigned", "nonassigned", "joint", "complement", "residual"))
        for checkpoint in checkpoints:
            for component in components:
                for task_name in TIER2:
                    for metric in ("recovery", "retention", "leakage"):
                        entries.append({"category": "collateral", "role": role,
                                        "checkpoint": checkpoint, "component": component,
                                        "task": task_name, "metric": metric,
                                        "required_output_fields": ["estimate", "uncertainty", "status"],
                                        "endpoint_id": f"{role}.{checkpoint}.{component}.{task_name}.{metric}.L3"})
    for checkpoint in ("g4", "g5", "g6", "g7"):
        for transform in TRANSFORMS:
            for control in CONTROLS:
                entries.append({"category": "counterfactual", "role": "C2",
                                "checkpoint": checkpoint, "transform": transform, "control": control,
                                "endpoint_id": f"C2.{checkpoint}.{transform}.{control}.L3"})
    for role in base.ROLES:
        for baseline in BASELINES:
            entries.append({"category": "baseline", "role": role, "baseline": baseline,
                            "endpoint_id": f"{role}.{baseline}.registered"})
    ids = [row["endpoint_id"] for row in entries]
    if len(ids) != len(set(ids)):
        raise ValueError("duplicate endpoint IDs")
    counts = collections.Counter(row["category"] for row in entries)
    value = {"schema_version": "msae_v3_endpoint_registry_v2", "protocol_id": PROTOCOL,
            "entries": entries, "endpoint_count": len(entries), "category_counts": dict(counts),
            "endpoint_id_set_sha256": base.sha_bytes(base.canonical_bytes(sorted(ids))),
            "families": {key: list(value) for key, value in FAMILIES.items()},
            "tier2_tasks": list(TIER2), "counterfactual_transforms": list(TRANSFORMS),
            "counterfactual_controls": list(CONTROLS), "baselines": list(BASELINES),
            "g7_interpretation": "matched_negative_control_not_replicate",
            "C1_scope": "raw_simple_G1_operands_only", "C2_scope": "G2_and_descriptive_control"}
    validate_endpoint_registry(value)
    return value


def _canonical_review(
    path: Path,
    supplied_sha256: str,
    *,
    scope: str,
    expected_digests: Mapping[str, str],
) -> dict[str, Any]:
    """Validate one create-once review and its exact machine control lines."""
    base.validate_sha256(supplied_sha256, f"{scope} review SHA-256")
    raw = _regular_bytes(path, mode=0o644)
    if base.sha_bytes(raw) != supplied_sha256 or not raw.endswith(b"\n") or b"\r" in raw:
        raise ValueError(f"{scope} review digest/newline drift")
    text = raw.decode("utf-8", errors="strict")
    if text.encode("utf-8") != raw:
        raise ValueError(f"{scope} review is not canonical UTF-8")
    lines = text.splitlines()
    stripped = [line.strip() for line in lines]
    for raw_line, stripped_line in zip(lines, stripped):
        control_like = (re.match(r"(?:VERDICT|REVIEW_SCOPE)\b", stripped_line,
                                 re.ASCII) is not None
                        or re.match(r"[A-Z][A-Z0-9_]*_SHA256\b", stripped_line,
                                    re.ASCII) is not None)
        if control_like and raw_line != stripped_line:
            raise ValueError(f"{scope} review has indented/padded control lines")
    malformed_review_controls = [line for line in lines
        if re.match(r"(?:VERDICT|REVIEW_SCOPE)\b", line, re.ASCII)
        and line not in {"VERDICT: SHIP", f"REVIEW_SCOPE: {scope}"}]
    if malformed_review_controls:
        raise ValueError(f"{scope} review has malformed/conflicting controls")
    verdicts = [line for line in lines if line.startswith("VERDICT:")]
    scopes = [line for line in lines if line.startswith("REVIEW_SCOPE:")]
    if verdicts != ["VERDICT: SHIP"] or scopes != [f"REVIEW_SCOPE: {scope}"]:
        raise ValueError(f"{scope} review verdict/scope is not uniquely SHIP")
    digest_rows: dict[str, str] = {}
    malformed_digest_controls = [line for line in lines
        if re.match(r"[A-Z][A-Z0-9_]*_SHA256\b", line, re.ASCII)
        and re.fullmatch(r"[A-Z][A-Z0-9_]*_SHA256: [0-9a-f]{64}", line,
                         re.ASCII) is None]
    if malformed_digest_controls:
        raise ValueError(f"{scope} review has malformed digest controls")
    digest_lines = [line for line in lines
                    if re.fullmatch(r"[A-Z][A-Z0-9_]*_SHA256: [0-9a-f]{64}",
                                    line, re.ASCII)]
    for line in digest_lines:
        match = re.fullmatch(r"([A-Z][A-Z0-9_]*)_SHA256: ([0-9a-f]{64})", line,
                             re.ASCII)
        if match is None or match.group(1) in digest_rows:
            raise ValueError(f"{scope} review has malformed/duplicate digest controls")
        digest_rows[match.group(1)] = match.group(2)
    if digest_rows != dict(expected_digests):
        raise ValueError(f"{scope} review digest controls mismatch: {digest_rows!r}")
    expected_control_lines = [
        "VERDICT: SHIP", f"REVIEW_SCOPE: {scope}",
        *(f"{key}_SHA256: {value}" for key, value in expected_digests.items()),
    ]
    observed_control_lines = [line for line in lines if (
        re.fullmatch(r"VERDICT: SHIP", line, re.ASCII)
        or re.fullmatch(rf"REVIEW_SCOPE: {re.escape(scope)}", line, re.ASCII)
        or re.fullmatch(r"[A-Z][A-Z0-9_]*_SHA256: [0-9a-f]{64}",
                        line, re.ASCII))]
    if observed_control_lines != expected_control_lines:
        raise ValueError(f"{scope} review control order drift")
    return {
        "path": path.relative_to(ROOT).as_posix(),
        "sha256": supplied_sha256,
        "scope": scope,
        "digests": digest_rows,
        "entry": _regular_entry(path),
    }


def _plan_review_binding(supplied_sha256: str) -> dict[str, Any]:
    if base.sha_file(PLAN_PATH) != FROZEN_PLAN_SHA256:
        raise ValueError("frozen gen9 plan bytes drifted")
    if supplied_sha256 != FROZEN_PLAN_REVIEW_SHA256:
        raise ValueError("setup does not name the reviewed frozen plan transcript")
    return _canonical_review(
        PLAN_REVIEW,
        supplied_sha256,
        scope="gen9_plan",
        expected_digests={
            "GEN6_PLAN": FAILED_GEN6_PLAN_SHA256,
            "GEN6_PLAN_REVIEW": FAILED_GEN6_PLAN_REVIEW_SHA256,
            "GEN6_FAILURE_REVIEW": FAILED_GEN6_FAILURE_REVIEW_SHA256,
            "GEN7_PLAN": FROZEN_PLAN_SHA256,
        },
    )


def _current_gen9_entries() -> dict[str, dict[str, Any]]:
    paths = {
        "GEN7_PLAN": PLAN_PATH, "GEN7_PLAN_REVIEW": PLAN_REVIEW,
        "GEN7_CONTROLLER": continuation.CONTROLLER_PATH, "GEN7_RUNTIME": RUNTIME,
        "GEN7_RUNNER": RUNNER, "GEN7_LAUNCHER": LAUNCHER,
        "GEN7_TMUX_TEST_SUPERVISOR": TMUX_TEST_SUPERVISOR,
        "GEN7_RFC": RUNTIME_RFC, "GEN7_TESTS": RUNTIME_TEST,
    }
    return {name: _regular_entry(path) for name, path in paths.items()}


def _current_gen9_implementation_entries() -> dict[str, dict[str, Any]]:
    entries = _current_gen9_entries()
    return {key: entries[key] for key in (
        "GEN7_CONTROLLER", "GEN7_RUNTIME", "GEN7_RUNNER", "GEN7_LAUNCHER",
        "GEN7_TMUX_TEST_SUPERVISOR", "GEN7_RFC", "GEN7_TESTS")}


def _review_check_subject(paths: Sequence[Path]) -> str:
    rows = []
    for path in paths:
        rows.append({
            "path": (path.relative_to(ROOT).as_posix()
                     if path.is_relative_to(ROOT) else str(path)),
            "sha256": base.sha_file(path),
        })
    return base.sha_bytes(base.canonical_bytes({
        "schema_version": "msae_v3_gen9_check_subject_v1", "entries": rows}))


def _pre_capability_check_rows() -> list[dict[str, Any]]:
    python = str(ROOT / ".venv-atlas/bin/python")
    env_prefix = [
        "/usr/bin/env", "-i", "PATH=/usr/bin:/bin",
        "HOME=/thayerfs/home/f004ndc", "LANG=C.UTF-8", "LC_ALL=C.UTF-8",
    ]
    pytest_environment = {
        "PATH": "/usr/bin:/bin", "HOME": "/thayerfs/home/f004ndc",
        "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8",
        "PYTEST_DISABLE_PLUGIN_AUTOLOAD": "1",
    }
    pytest_prefix = [*env_prefix, "PYTEST_DISABLE_PLUGIN_AUTOLOAD=1",
                     python, "-B", "-I", "-m", "pytest", "-q",
                     "-p", "no:cacheprovider"]
    specs: list[tuple[str, list[str], list[Path]]] = [
        ("predecessor_v1", ["tests/test_msae_independent_measurement_v1.py"],
         [ROOT / "tests/test_msae_independent_measurement_v1.py"]),
        ("predecessor_v2", ["tests/test_msae_independent_measurement_v2.py"],
         [ROOT / "tests/test_msae_independent_measurement_v2.py"]),
        ("predecessor_v3", ["tests/test_msae_independent_measurement_v3.py"],
         [ROOT / "tests/test_msae_independent_measurement_v3.py"]),
        ("predecessor_post_m1",
         ["tests/test_msae_independent_measurement_v3_post_m1.py"],
         [ROOT / "tests/test_msae_independent_measurement_v3_post_m1.py"]),
        ("predecessor_post_m2_runtime", [
            "tests/test_msae_independent_measurement_v3_post_m2_runtime.py",
            "-k", "not failed_handoff_extinction_kills_real_processes_and_socket"],
         [ROOT / "tests/test_msae_independent_measurement_v3_post_m2_runtime.py"]),
        ("predecessor_remediation_v1",
         ["tests/test_msae_measurement_remediation_v1.py"],
         [ROOT / "tests/test_msae_measurement_remediation_v1.py"]),
        ("predecessor_gen4", [
            "tests/test_msae_independent_measurement_v3_post_m4_gen4.py",
            "-k", "not failed_handoff_extinction_kills_real_processes_and_socket"],
         [ROOT / "tests/test_msae_independent_measurement_v3_post_m4_gen4.py"]),
        ("gen9_cpu", [
            "tests/test_msae_independent_measurement_v3_post_m9_gen9.py",
            "-k", "not failed_handoff_extinction_kills_real_processes_and_socket"],
         [RUNTIME_TEST, RUNTIME, continuation.CONTROLLER_PATH]),
        ("gen9_publisher", [
            "tests/test_msae_independent_measurement_v3_post_m9_gen9.py::"
            "test_nfs_publisher_fault_matrix",
            "tests/test_msae_independent_measurement_v3_post_m9_gen9.py::"
            "test_local_mount_rejection_precedes_protocol_mutation"],
         [RUNTIME_TEST, RUNTIME, continuation.CONTROLLER_PATH]),
    ]
    rows = [{
        "schema_version": "msae_v3_gen9_pre_capability_check_v1",
        "id": check_id, "argv": [*pytest_prefix, *suffix],
        "cwd": str(ROOT), "environment": pytest_environment,
        "subject_sha256": _review_check_subject(subjects),
        "exit_code": 0, "summary": "pass",
    } for check_id, suffix, subjects in specs]
    # Keep the exact plan/review/seven-file order explicit for the real-process
    # subject; no mapping iteration or inferred glob can change it.
    real_paths = [
        PLAN_PATH, PLAN_REVIEW, continuation.CONTROLLER_PATH, RUNTIME, RUNNER,
        LAUNCHER, TMUX_TEST_SUPERVISOR, RUNTIME_RFC, RUNTIME_TEST,
    ]
    rows.append({
        "schema_version": "msae_v3_gen9_pre_capability_check_v1",
        "id": "gen9_real_tmux", "argv": [
            *env_prefix, python, "-S", "-B", "-I",
            "scripts/run_msae_independent_measurement_v3_post_m2_gen9_tmux_test.py"],
        "cwd": str(ROOT),
        "environment": {"PATH": "/usr/bin:/bin",
                        "HOME": "/thayerfs/home/f004ndc",
                        "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8"},
        "subject_sha256": _review_check_subject(real_paths),
        "exit_code": 0, "summary": "pass",
    })
    return rows


