def _renameat2_noreplace_probe(source: Path, destination: Path) -> int:
    libc = ctypes.CDLL(None, use_errno=True)
    function = getattr(libc, "renameat2", None)
    if function is None:
        return errno.ENOSYS
    function.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int,
                         ctypes.c_char_p, ctypes.c_uint]
    function.restype = ctypes.c_int
    if function(-100, os.fsencode(source), -100, os.fsencode(destination), 1) == 0:
        return 0
    return ctypes.get_errno()


def _tmp_parent_binding() -> dict[str, Any]:
    directory = Path("/tmp")
    fd = os.open(directory, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        before = os.fstat(fd)
        current = directory.lstat()
        if (not stat.S_ISDIR(before.st_mode) or stat.S_ISLNK(current.st_mode)
                or (before.st_dev, before.st_ino) != (current.st_dev, current.st_ino)
                or before.st_uid != 0 or stat.S_IMODE(before.st_mode) != 0o1777):
            raise ValueError("/tmp held-parent identity drift")
        mount = _mount_identity(directory)
        after = os.fstat(fd)
        if (before.st_dev, before.st_ino, before.st_mode, before.st_uid) != (
                after.st_dev, after.st_ino, after.st_mode, after.st_uid):
            raise ValueError("/tmp changed while binding it")
        return {
            "path": "/tmp", "device": before.st_dev, "inode": before.st_ino,
            "uid": before.st_uid, "gid": before.st_gid,
            "mode": stat.S_IMODE(before.st_mode), "nlink": before.st_nlink,
            "mount": mount,
        }
    finally:
        os.close(fd)


def _tmp_parent_projection_binding() -> dict[str, Any]:
    binding = _tmp_parent_binding()
    return {"path": binding["path"], "device": binding["device"],
            "inode": binding["inode"], "uid": binding["uid"],
            "gid": binding["gid"], "mode": binding["mode"],
            "mountinfo_sha256": binding["mount"]["mountinfo_sha256"]}


def _broker_family_projection_subject(broker_path: Path) -> dict[str, Any]:
    projection = _short_socket_family_projection(families=("m9b_",))
    if projection:
        raise ValueError("broker-family projection is not empty")
    return {
        "schema_version": "msae_v3_gen9_broker_family_projection_v1",
        "tmp_parent_binding": _tmp_parent_projection_binding(),
        "exact_broker_path": str(broker_path), "entries": [],
    }


def _unlink_bound_tmp_socket(path: Path, expected: Mapping[str, Any]) -> None:
    if path.parent != Path("/tmp") or set(expected) != {
            "device", "inode", "uid", "gid", "mode", "nlink"}:
        raise ValueError("bound short-socket unlink subject drift")
    directory_fd = os.open("/tmp", os.O_RDONLY | os.O_DIRECTORY |
                           os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        directory_before = os.fstat(directory_fd)
        path_parent = Path("/tmp").lstat()
        if (directory_before.st_dev, directory_before.st_ino) != (
                path_parent.st_dev, path_parent.st_ino):
            raise ValueError("short-socket parent substitution")
        current = os.stat(path.name, dir_fd=directory_fd, follow_symlinks=False)
        observed = {"device": current.st_dev, "inode": current.st_ino,
                    "uid": current.st_uid, "gid": current.st_gid,
                    "mode": stat.S_IMODE(current.st_mode), "nlink": current.st_nlink}
        if observed != dict(expected) or not stat.S_ISSOCK(current.st_mode):
            raise ValueError("short-socket identity drift before unlink")
        os.unlink(path.name, dir_fd=directory_fd)
        os.fsync(directory_fd)
        try:
            os.stat(path.name, dir_fd=directory_fd, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise RuntimeError("short-socket path survived unlink")
        directory_after = os.fstat(directory_fd)
        if (directory_before.st_dev, directory_before.st_ino,
                directory_before.st_uid, directory_before.st_mode) != (
                directory_after.st_dev, directory_after.st_ino,
                directory_after.st_uid, directory_after.st_mode):
            raise ValueError("short-socket parent drift during unlink")
    finally:
        os.close(directory_fd)


def _short_socket_family_projection(*, allowed: Iterable[str] = (),
                                    families: Sequence[str] = ("m9t_", "m9b_", "m9p_"),
                                    require_allowed_present: bool = True) -> list[dict[str, Any]]:
    allowed_names = set(allowed)
    rows: list[dict[str, Any]] = []
    fd = os.open("/tmp", os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        for entry in os.scandir(fd):
            if not any(entry.name.startswith(prefix) for prefix in families):
                continue
            st = entry.stat(follow_symlinks=False)
            if entry.name not in allowed_names:
                raise ValueError(f"undeclared short-socket-family entry: {entry.name}")
            if (not stat.S_ISSOCK(st.st_mode) or stat.S_ISLNK(st.st_mode)
                    or st.st_uid != os.getuid() or st.st_gid != os.getgid()
                    or stat.S_IMODE(st.st_mode) != 0o700 or st.st_nlink != 1):
                raise ValueError(f"registered short-socket identity drift: {entry.name}")
            rows.append({
                "name": entry.name, "device": st.st_dev, "inode": st.st_ino,
                "uid": st.st_uid, "gid": st.st_gid,
                "mode": stat.S_IMODE(st.st_mode), "nlink": st.st_nlink,
                "type": "socket" if stat.S_ISSOCK(st.st_mode) else "other",
            })
    finally:
        os.close(fd)
    if require_allowed_present and {row["name"] for row in rows} != allowed_names:
        raise ValueError("registered short socket is absent from family projection")
    return sorted(rows, key=lambda row: row["name"])


GEN7_SHORT_PREFIXES = (
    "m9t_", "m9b_", "m9p_", "m9x_", "m9a_", "m9c_", "m9s_",
)


def _all_gen9_short_family_absence() -> dict[str, list[str]]:
    """Close production and containment short families under one held /tmp FD."""
    result = {prefix: [] for prefix in GEN7_SHORT_PREFIXES}
    fd = os.open("/tmp", os.O_RDONLY | os.O_DIRECTORY |
                 os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        for entry in os.scandir(fd):
            for prefix in GEN7_SHORT_PREFIXES:
                if entry.name.startswith(prefix):
                    result[prefix].append(entry.name)
    finally:
        os.close(fd)
    for names in result.values():
        names.sort()
    if any(result.values()):
        raise ValueError(f"gen9 short-family namespace is not empty: {result}")
    return result


def _generation_siblings(parent: Path, prefix: str) -> list[str]:
    if not _path_present(parent):
        return []
    st = parent.lstat()
    if not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode):
        raise ValueError(f"gen9 namespace parent identity drift: {parent}")
    return sorted(entry.name for entry in os.scandir(parent)
                  if entry.name.startswith(prefix))


def _pre_capability_namespace_gate(*, allow_capability_root: bool) -> dict[str, Any]:
    """Validate every current namespace before the capability one-way door."""
    _validate_gen3_review_namespace("pre_capability")
    generation_prefix = "msae_independent_measurement_v3_post_m2_gen9"
    sibling_specs = (
        (ACTIVE_CONFIG.parent, generation_prefix, set()),
        (ACTIVE_PROV.parent, generation_prefix, set()),
        (ACTIVE_M4_DATA.parent, generation_prefix, set()),
        (ACTIVE_RUN_ROOT.parent, "20260821_" + generation_prefix, set()),
        (CAPABILITY_ANALYSIS_ROOT.parent, generation_prefix,
         {CAPABILITY_ANALYSIS_ROOT.name} if allow_capability_root else set()),
        (ACTIVE_PRIVATE_KEY.parent,
         "independent_measurement_v3_post_m2_gen9", set()),
        (ACTIVE_STATE.parent,
         "independent_measurement_v3_post_m2_gen9", set()),
    )
    sibling_rows: list[dict[str, Any]] = []
    for parent, prefix, expected in sibling_specs:
        observed = set(_generation_siblings(parent, prefix))
        if observed != expected:
            raise ValueError(
                f"pre-capability generation namespace drift at {parent}: "
                f"missing={expected - observed}, extra={observed - expected}")
        sibling_rows.append({"parent": str(parent), "prefix": prefix,
                             "children": sorted(observed)})
    absent_paths = (
        ACTIVE_CONFIG, ACTIVE_PROV, ACTIVE_M4_DATA, ACTIVE_PRIVATE_KEY,
        ACTIVE_STATE, ACTIVE_RUN_ROOT, SETUP_KEY_TRANSACTION,
        M4_PRIMARY, M4_REBUILD, CAPABILITY_PROBE_ROOT,
        NFS_PUBLISHER_TEST_ROOT, LOCAL_REJECTION_TEST_ROOT,
    )
    for path in absent_paths:
        if _path_present(path):
            raise ValueError(f"pre-capability downstream namespace exists: {path}")
    derived_patterns = (
        "msae_independent_measurement_v3_post_m2_gen9_*.prescore.check.json",
        "msae_independent_measurement_v3_post_m2_gen9_*.prescore.trace.log",
        "msae_independent_measurement_v3_post_m2_gen9_*.sock",
    )
    derived_rows = []
    for pattern in derived_patterns:
        matches = sorted(path.name for path in Path("/tmp").glob(pattern))
        if matches:
            raise ValueError(
                f"pre-capability derived namespace exists: {pattern}: {matches}")
        derived_rows.append({"pattern": f"/tmp/{pattern}", "matches": []})
    return {
        "schema_version": "msae_v3_gen9_pre_capability_namespace_v1",
        "allow_capability_root": allow_capability_root,
        "absent_paths": [str(path) for path in absent_paths],
        "generation_siblings": sibling_rows,
        "derived_patterns": derived_rows,
        "short_families": _all_gen9_short_family_absence(),
    }


