def _observe_gen5_socket_failure(label: str, path_text: str) -> dict[str, Any]:
    path = Path(path_text)
    initially_absent = not _path_present(path)
    listener = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    caught: BaseException | None = None
    try:
        listener.bind(path_text)
    except BaseException as error:
        caught = error
    finally:
        listener.close()
    finally_absent = not _path_present(path)
    if _path_present(path):
        raise ValueError(f"overlength {label} socket unexpectedly created an object")
    passed = (initially_absent and finally_absent and isinstance(caught, OSError)
              and caught.errno is None and str(caught) == "AF_UNIX path too long")
    return {
        "id": f"gen5_{label}_path_rejection", "outcome": "pass" if passed else "fail",
        "reason_codes": [] if passed else ["overlength_socket_rejection_mismatch"],
        "path": path_text, "encoded_length": len(path_text.encode("utf-8")),
        "exception_type": type(caught).__name__ if caught is not None else None,
        "exception_message": str(caught) if caught is not None else None,
        "errno": caught.errno if isinstance(caught, OSError) else None,
        "absent_before": initially_absent, "absent_after": finally_absent,
        "listener_created": caught is None,
    }


def _observe_gen9_short_socket(label: str, path_text: str) -> dict[str, Any]:
    path = Path(path_text)
    basename = path.name
    before = _short_socket_family_projection()
    previous_umask = os.umask(0o077)
    listener = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    client: socket.socket | None = None
    accepted: socket.socket | None = None
    live: dict[str, Any] | None = None
    error: BaseException | None = None
    try:
        listener.bind(path_text)
        listener.listen(1)
        current = path.lstat()
        if (not stat.S_ISSOCK(current.st_mode) or current.st_uid != os.getuid()
                or current.st_gid != os.getgid() or current.st_nlink != 1
                or stat.S_IMODE(current.st_mode) != 0o700):
            raise ValueError("short socket live identity mismatch")
        live = {
            "device": current.st_dev, "inode": current.st_ino,
            "uid": current.st_uid, "gid": current.st_gid,
            "mode": stat.S_IMODE(current.st_mode), "nlink": current.st_nlink,
        }
        _short_socket_family_projection(allowed=[basename])
        client = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        client.settimeout(2); listener.settimeout(2)
        client.connect(path_text)
        accepted, _ = listener.accept()
    except BaseException as caught:
        error = caught
    finally:
        if accepted is not None: accepted.close()
        if client is not None: client.close()
        listener.close()
        os.umask(previous_umask)
        if _path_present(path):
            if live is not None:
                now = path.lstat()
                if (now.st_dev, now.st_ino) != (live["device"], live["inode"]):
                    raise ValueError("short socket substituted before cleanup")
                _unlink_bound_tmp_socket(path, live)
            else:
                raise ValueError("refuse to unlink an unbound short socket")
    after = _short_socket_family_projection()
    passed = (error is None and live is not None and not before and not after
              and len(path_text.encode("utf-8")) == 78)
    return {
        "id": f"gen9_{label}_short_socket", "outcome": "pass" if passed else "fail",
        "reason_codes": [] if passed else ["short_socket_round_trip_mismatch"],
        "path": path_text, "encoded_length": len(path_text.encode("utf-8")),
        "before_family": before, "live_identity": live, "after_family": after,
        "exception_type": type(error).__name__ if error is not None else None,
        "exception_message": str(error) if error is not None else None,
    }


def _observe_gen4_nfs_capability() -> dict[str, Any]:
    source = CAPABILITY_PROBE_ROOT / "gen9_staging.json"
    destination = CAPABILITY_PROBE_ROOT / "gen9_destination.json"
    transcript = ""
    result: dict[str, Any] = {
        "id": "gen4_nfs_renameat2_reproduction", "outcome": "fail",
        "reason_codes": ["nfs_probe_not_completed"], "probe_root": str(CAPABILITY_PROBE_ROOT),
    }
    created_root = False
    try:
        if _path_present(CAPABILITY_PROBE_ROOT):
            raise ValueError("capability probe root is not initially absent")
        CAPABILITY_PROBE_ROOT.mkdir(mode=0o700)
        os.chmod(CAPABILITY_PROBE_ROOT, 0o700)
        base._fsync_directory(CAPABILITY_PROBE_ROOT.parent)
        created_root = True
        raw = base.canonical_bytes({"schema_version": "msae_v3_gen9_nfs_probe_v1"})
        fd = os.open(source, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        try:
            os.fchmod(fd, 0o600); _write_all(fd, raw); os.fsync(fd)
        finally:
            os.close(fd)
        base._fsync_directory(CAPABILITY_PROBE_ROOT)
        before_st = source.lstat()
        before = {"source": _lstat_binding(source), "destination_absent": not _path_present(destination)}
        observed_errno = _renameat2_noreplace_probe(source, destination)
        after_st = source.lstat()
        after = {"source": _lstat_binding(source), "destination_absent": not _path_present(destination)}
        mount = _mount_identity(CAPABILITY_PROBE_ROOT)
        transcript = ("renameat2(RENAME_NOREPLACE)\n"
                      f"source={source.name}\ndestination={destination.name}\n"
                      f"return=-1\nerrno={observed_errno} {errno.errorcode.get(observed_errno, 'UNKNOWN')}\n")
        passed = (observed_errno == errno.EINVAL and not _path_present(destination)
                  and _regular_bytes(source, mode=0o600) == raw
                  and (before_st.st_dev, before_st.st_ino, before_st.st_size) ==
                      (after_st.st_dev, after_st.st_ino, after_st.st_size)
                  and mount.get("filesystem_magic") == "0x6969"
                  and mount.get("mountinfo", {}).get("filesystem_type") in {"nfs", "nfs4"})
        result = {
            "id": "gen4_nfs_renameat2_reproduction",
            "outcome": "pass" if passed else "fail",
            "reason_codes": [] if passed else ["expected_einval_not_reproduced"],
            "probe_root": str(CAPABILITY_PROBE_ROOT), "filesystem": mount,
            "source": {"basename": source.name, "mode": 0o600},
            "destination": {"basename": destination.name, "mode": 0o600},
            "before": before, "after": after, "errno": observed_errno,
            "error_name": errno.errorcode.get(observed_errno),
            "transcript_utf8": transcript,
            "transcript_sha256": base.sha_bytes(transcript.encode("utf-8")),
        }
    except BaseException as error:
        result = {**result, "exception_type": type(error).__name__,
                  "exception_message": str(error)}
    finally:
        if created_root:
            if _path_present(destination):
                # A successful rename is an observed negative capability result,
                # but the exact object is still ours and must be removed.
                destination.unlink(); base._fsync_directory(CAPABILITY_PROBE_ROOT)
            if _path_present(source):
                source.unlink(); base._fsync_directory(CAPABILITY_PROBE_ROOT)
            if any(os.scandir(CAPABILITY_PROBE_ROOT)):
                raise ValueError("NFS capability probe cleanup left an extra child")
            CAPABILITY_PROBE_ROOT.rmdir(); base._fsync_directory(CAPABILITY_PROBE_ROOT.parent)
    if _path_present(CAPABILITY_PROBE_ROOT):
        raise ValueError("NFS capability probe root survived observation")
    return result


def _validate_capability_report(value: Mapping[str, Any]) -> None:
    required = {
        "schema_version", "protocol_id", "writer_generation", "argv", "cwd",
        "started_utc", "ended_utc", "plan_entry", "plan_review_entry",
        "pre_capability_review_entry", "implementation_entries",
        "typed_substitution_evidence",
        "failed_gen4_entries", "failed_gen5_entries", "failed_gen6_entries",
        "tmp_parent_binding",
        "checks", "overall_pass", "probe_root", "protocol_path_used",
        "model_gpu_tmux", "sealed_payload_content_reads",
    }
    if (set(value) != required
            or value.get("schema_version") != "msae_v3_gen9_capability_reproduction_v1"
            or value.get("protocol_id") != PROTOCOL
            or value.get("writer_generation") != GENERATION
            or value.get("cwd") != str(ROOT)
            or value.get("probe_root") != str(CAPABILITY_PROBE_ROOT)
            or value.get("protocol_path_used") is not False
            or value.get("model_gpu_tmux") is not False
            or value.get("sealed_payload_content_reads") != 0):
        raise ValueError("gen9 capability report semantic drift")
    timestamp_pattern = r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z"
    if (re.fullmatch(timestamp_pattern, str(value.get("started_utc")), re.ASCII) is None
            or re.fullmatch(timestamp_pattern, str(value.get("ended_utc")), re.ASCII) is None
            or str(value["ended_utc"]) < str(value["started_utc"])):
        raise ValueError("gen9 capability UTC timestamp drift")
    if value.get("plan_entry") != _regular_entry(PLAN_PATH):
        raise ValueError("gen9 capability plan binding drift")
    if value.get("plan_review_entry") != _regular_entry(PLAN_REVIEW):
        raise ValueError("gen9 capability plan-review binding drift")
    pre = value.get("pre_capability_review_entry")
    if not isinstance(pre, dict):
        raise ValueError("gen9 capability pre-review binding absent")
    _pre_capability_review_binding(str(pre.get("sha256")))
    if pre != _regular_entry(PRE_CAPABILITY_REVIEW):
        raise ValueError("gen9 capability pre-review entry drift")
    if value.get("implementation_entries") != _current_gen9_implementation_entries():
        raise ValueError("gen9 capability implementation subject drift")
    if value.get("typed_substitution_evidence") != gen6_to_gen9_substitution_evidence():
        raise ValueError("gen9 capability typed substitution evidence drift")
    if value.get("failed_gen4_entries") != _failed_gen4_entries():
        raise ValueError("gen9 capability failed-gen4 subject drift")
    if value.get("failed_gen5_entries") != _failed_gen5_entries():
        raise ValueError("gen9 capability failed-gen5 subject drift")
    if value.get("failed_gen6_entries") != _failed_gen6_entries():
        raise ValueError("gen9 capability failed-gen6 subject drift")
    expected_argv = [
        ".venv-atlas/bin/python", "-S", "-B", "-I",
        "scripts/msae_independent_measurement_v3_post_m2_gen9.py",
        "probe-gen9-capability", "--pre-capability-review-sha256",
        str(pre["sha256"]), "--output", CAPABILITY_REPORT.relative_to(ROOT).as_posix(),
    ]
    if value.get("argv") != expected_argv:
        raise ValueError("gen9 capability argv drift")
    if value.get("tmp_parent_binding") != _tmp_parent_binding():
        raise ValueError("gen9 capability /tmp parent binding drift")
    templates5, templates6 = _gen5_socket_templates(), _gen9_socket_templates()
    checks = value.get("checks")
    if not isinstance(checks, list) or len(checks) != 3:
        raise ValueError("gen9 capability check cardinality drift")
    expected_ids = ["gen4_nfs_renameat2_reproduction",
                    "gen5_overlength_socket_rejections",
                    "gen9_short_socket_round_trips"]
    if [row.get("id") for row in checks if isinstance(row, dict)] != expected_ids:
        raise ValueError("gen9 capability check identity/order drift")
    for group, expected_paths, expected_observation_ids in (
        (checks[1], templates5,
         ["gen5_tmux_path_rejection", "gen5_broker_path_rejection"]),
        (checks[2], templates6,
         ["gen9_tmux_short_socket", "gen9_broker_short_socket",
          "gen9_pane_short_socket"]),
    ):
        if set(group) != {"id", "outcome", "reason_codes", "observations"}:
            raise ValueError("gen9 capability grouped-check schema drift")
        observations = group.get("observations")
        if (not isinstance(observations, list)
                or len(observations) != len(expected_observation_ids)
                or [row.get("id") for row in observations if isinstance(row, dict)]
                != expected_observation_ids
                or [row.get("path") for row in observations]
                != [expected_paths[name] for name in expected_paths]):
            raise ValueError("gen9 capability grouped observation drift")
        expected_group_pass = all(row.get("outcome") == "pass" for row in observations)
        if ((group.get("outcome") == "pass") is not expected_group_pass
                or group.get("reason_codes") != ([] if expected_group_pass else
                                                  ["one_or_more_observations_failed"])):
            raise ValueError("gen9 capability grouped outcome drift")
    gen5_observations = checks[1]["observations"]
    gen9_observations = checks[2]["observations"]
    if (gen5_observations[0].get("encoded_length") != 119
            or gen5_observations[1].get("encoded_length") != 129):
        raise ValueError("gen5 frozen socket length drift")
    if any(row.get("encoded_length") != 78 for row in gen9_observations):
        raise ValueError("gen9 short socket length drift")
    if (gen5_observations[0].get("path") != templates5["tmux"]
            or gen5_observations[1].get("path") != templates5["broker"]):
        raise ValueError("gen5 socket template drift")
    if [row.get("path") for row in gen9_observations] != list(templates6.values()):
        raise ValueError("gen9 short socket template drift")
    expected_pass = all(row.get("outcome") == "pass" for row in checks)
    if value.get("overall_pass") is not expected_pass:
        raise ValueError("gen9 capability overall outcome drift")
    if _path_present(CAPABILITY_PROBE_ROOT):
        raise ValueError("gen9 capability namespace is not clean")
    _all_gen9_short_family_absence()


def _perform_gen9_capability_probe(started: int, pre_review_sha256: str) -> dict[str, Any]:
    plan_review = _plan_review_binding(FROZEN_PLAN_REVIEW_SHA256)
    pre_review = _pre_capability_review_binding(pre_review_sha256)
    def grouped(check_id: str, observations: list[dict[str, Any]]) -> dict[str, Any]:
        passed = all(row.get("outcome") == "pass" for row in observations)
        return {
            "id": check_id, "outcome": "pass" if passed else "fail",
            "reason_codes": [] if passed else ["one_or_more_observations_failed"],
            "observations": observations,
        }

    checks = [
        _observe_gen4_nfs_capability(),
        grouped("gen5_overlength_socket_rejections", [
            _observe_gen5_socket_failure("tmux", _gen5_socket_templates()["tmux"]),
            _observe_gen5_socket_failure("broker", _gen5_socket_templates()["broker"]),
        ]),
        grouped("gen9_short_socket_round_trips", [
            _observe_gen9_short_socket("tmux", _gen9_socket_templates()["tmux"]),
            _observe_gen9_short_socket("broker", _gen9_socket_templates()["broker"]),
            _observe_gen9_short_socket("pane", _gen9_socket_templates()["pane"]),
        ]),
    ]
    ended = int(time.time())
    utc = lambda value: time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(value))
    value = {
        "schema_version": "msae_v3_gen9_capability_reproduction_v1",
        "protocol_id": PROTOCOL, "writer_generation": GENERATION,
        "argv": [".venv-atlas/bin/python", "-S", "-B", "-I",
                 "scripts/msae_independent_measurement_v3_post_m2_gen9.py",
                 "probe-gen9-capability", "--pre-capability-review-sha256",
                 pre_review_sha256, "--output", CAPABILITY_REPORT.relative_to(ROOT).as_posix()],
        "cwd": str(ROOT), "started_utc": utc(started), "ended_utc": utc(ended),
        "plan_entry": _regular_entry(PLAN_PATH),
        "plan_review_entry": plan_review["entry"],
        "pre_capability_review_entry": pre_review["entry"],
        "implementation_entries": _current_gen9_implementation_entries(),
        "typed_substitution_evidence": gen6_to_gen9_substitution_evidence(),
        "failed_gen4_entries": _failed_gen4_entries(),
        "failed_gen5_entries": _failed_gen5_entries(),
        "failed_gen6_entries": _failed_gen6_entries(),
        "tmp_parent_binding": _tmp_parent_binding(), "checks": checks,
        "overall_pass": all(row.get("outcome") == "pass" for row in checks),
        "probe_root": str(CAPABILITY_PROBE_ROOT), "protocol_path_used": False,
        "model_gpu_tmux": False, "sealed_payload_content_reads": 0,
    }
    _validate_capability_report(value)
    return value


def probe_gen9_capability(output: Path, pre_review_sha256: str) -> dict[str, Any]:
    if Path(output) != CAPABILITY_REPORT:
        raise ValueError("capability report output path drift")
    _plan_review_binding(FROZEN_PLAN_REVIEW_SHA256)
    pre_review = _pre_capability_review_binding(pre_review_sha256)
    _failed_gen4_entries(); _failed_gen5_entries(); _failed_gen6_entries()
    _pre_capability_namespace_gate(
        allow_capability_root=_path_present(CAPABILITY_ANALYSIS_ROOT))
    if _path_present(CAPABILITY_REPORT) and not _path_present(CAPABILITY_TRANSACTION):
        _exact_directory_entries(CAPABILITY_ANALYSIS_ROOT, {CAPABILITY_REPORT.name}, mode=0o700)
        raw = _regular_bytes(CAPABILITY_REPORT, mode=0o644)
        value = base.strict_json_loads(raw.decode("utf-8"))
        if raw != base.canonical_bytes(value):
            raise ValueError("capability report canonical bytes drift")
        _validate_capability_report(value)
        return value
    if not _path_present(CAPABILITY_ANALYSIS_ROOT):
        if not _path_present(CAPABILITY_ANALYSIS_ROOT.parent):
            _ensure_secure_dir(CAPABILITY_ANALYSIS_ROOT.parent)
        _ensure_secure_dir(CAPABILITY_ANALYSIS_ROOT)
    allowed = {CAPABILITY_TRANSACTION.name} | ({CAPABILITY_REPORT.name} if _path_present(CAPABILITY_REPORT) else set())
    _exact_directory_entries(CAPABILITY_ANALYSIS_ROOT, allowed, mode=0o700)
    if not _path_present(CAPABILITY_TRANSACTION):
        _ensure_secure_dir(CAPABILITY_TRANSACTION)
    observed = {entry.name for entry in os.scandir(CAPABILITY_TRANSACTION)}
    permitted = {"transaction.json", ".transaction.json.bootstrap", "report.payload",
                 *(f".transaction.json.attempt-{i}" for i in range(1,4)),
                 *(f".{CAPABILITY_REPORT.name}.attempt-{i}" for i in range(1,4))}
    if not observed <= permitted:
        raise ValueError("capability transaction has an undeclared child")
    _exact_directory_entries(CAPABILITY_TRANSACTION, observed, mode=0o700)
    descriptor_path = CAPABILITY_TRANSACTION / "transaction.json"
    bootstrap_path = CAPABILITY_TRANSACTION / ".transaction.json.bootstrap"
    if (not _path_present(descriptor_path) and not _path_present(bootstrap_path) and observed):
        raise ValueError("capability transaction lost descriptor authority")
    if _path_present(descriptor_path) or _path_present(bootstrap_path):
        authority_path = descriptor_path if _path_present(descriptor_path) else bootstrap_path
        descriptor_raw = _regular_bytes(authority_path, mode=0o600)
        descriptor = base.strict_json_loads(descriptor_raw.decode("utf-8"))
        if descriptor_raw != base.canonical_bytes(descriptor):
            raise ValueError("capability transaction descriptor drift")
        sealed = descriptor.get("sealed_random_payloads", {}).get("report_b64")
        if not isinstance(sealed, str):
            raise ValueError("capability transaction sealed report missing")
        report_raw = base64.b64decode(sealed, validate=True)
        report = base.strict_json_loads(report_raw.decode("utf-8"))
        _validate_capability_report(report)
    else:
        report = _perform_gen9_capability_probe(int(time.time()), pre_review_sha256)
        report_raw = base.canonical_bytes(report)
        row0 = _publication_row(0, CAPABILITY_TRANSACTION, "report.payload",
                                CAPABILITY_ANALYSIS_ROOT, CAPABILITY_REPORT.name,
                                report_raw, 0o644, "gen9_capability_report")
        authority = base.sha_bytes(base.canonical_bytes({
            "plan_review_sha256": FROZEN_PLAN_REVIEW_SHA256,
            "pre_capability_review_sha256": pre_review_sha256,
            "implementation_entries": _current_gen9_implementation_entries(),
        }))
        descriptor = _link_transaction_payload(
            kind="capability", authority_sha256=authority, publications=[row0],
            maximum_seconds=300,
            sealed_random_payloads={"report_b64": base64.b64encode(report_raw).decode("ascii")})
    row = _publication_row(0, CAPABILITY_TRANSACTION, "report.payload",
                           CAPABILITY_ANALYSIS_ROOT, CAPABILITY_REPORT.name,
                           report_raw, 0o644, "gen9_capability_report")
    authority = base.sha_bytes(base.canonical_bytes({
        "plan_review_sha256": FROZEN_PLAN_REVIEW_SHA256,
        "pre_capability_review_sha256": pre_review_sha256,
        "implementation_entries": _current_gen9_implementation_entries(),
    }))
    _validate_link_transaction_descriptor(descriptor, kind="capability",
        authority_sha256=authority, publications=[row], maximum_seconds=300)
    if descriptor["sealed_random_payloads"] != {
            "report_b64": base64.b64encode(report_raw).decode("ascii")}:
        raise ValueError("capability transaction sealed report drift")
    _pre_capability_namespace_gate(allow_capability_root=True)
    _bootstrap_link_transaction(CAPABILITY_TRANSACTION, descriptor)
    _link_publication(descriptor, row, report_raw, descriptor_path=descriptor_path)
    _exact_directory_entries(CAPABILITY_ANALYSIS_ROOT,
        {CAPABILITY_REPORT.name, CAPABILITY_TRANSACTION.name}, mode=0o700)
    _exact_directory_entries(CAPABILITY_TRANSACTION, {descriptor_path.name}, mode=0o700)
    report_identity_fd = os.open(
        CAPABILITY_REPORT, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        report_stat_before = os.fstat(report_identity_fd)
        if _regular_bytes(CAPABILITY_REPORT, mode=0o644) != report_raw:
            raise ValueError("capability report changed before authority cleanup")
        report_stat_after = CAPABILITY_REPORT.lstat()
        if ((report_stat_before.st_dev, report_stat_before.st_ino,
             report_stat_before.st_mode, report_stat_before.st_uid,
             report_stat_before.st_nlink, report_stat_before.st_size) !=
            (report_stat_after.st_dev, report_stat_after.st_ino,
             report_stat_after.st_mode, report_stat_after.st_uid,
             report_stat_after.st_nlink, report_stat_after.st_size)):
            raise ValueError("capability report changed before authority cleanup")
    finally:
        os.close(report_identity_fd)
    descriptor_identity_fd = os.open(
        descriptor_path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        descriptor_stat_before = os.fstat(descriptor_identity_fd)
        if _regular_bytes(descriptor_path, mode=0o600) != base.canonical_bytes(descriptor):
            raise ValueError("capability descriptor changed before authority cleanup")
        descriptor_stat_after = descriptor_path.lstat()
        if ((descriptor_stat_before.st_dev, descriptor_stat_before.st_ino,
             descriptor_stat_before.st_mode, descriptor_stat_before.st_uid,
             descriptor_stat_before.st_nlink, descriptor_stat_before.st_size) !=
            (descriptor_stat_after.st_dev, descriptor_stat_after.st_ino,
             descriptor_stat_after.st_mode, descriptor_stat_after.st_uid,
             descriptor_stat_after.st_nlink, descriptor_stat_after.st_size)):
            raise ValueError("capability descriptor changed before authority cleanup")
    finally:
        os.close(descriptor_identity_fd)
    _pre_capability_namespace_gate(allow_capability_root=True)
    descriptor_path.unlink(); base._fsync_directory(CAPABILITY_TRANSACTION)
    if any(os.scandir(CAPABILITY_TRANSACTION)):
        raise ValueError("capability transaction cleanup drift")
    CAPABILITY_TRANSACTION.rmdir(); base._fsync_directory(CAPABILITY_ANALYSIS_ROOT)
    _validate_capability_report(report)
    return report

def _failed_gen3_entries() -> dict[str, dict[str, Any]]:
    paths = {
        "FAILED_GEN3_PLAN": FAILED_GEN3_PLAN,
        "FAILED_GEN3_PLAN_REVIEW": FAILED_GEN3_PLAN_REVIEW,
        "FAILED_GEN3_CONTROLLER": ROOT / "scripts/msae_independent_measurement_v3_post_m2_gen3.py",
        "FAILED_GEN3_RUNTIME": ROOT / "scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py",
        "FAILED_GEN3_RUNNER": ROOT / "scripts/run_msae_independent_calibration_v3_gen3.py",
        "FAILED_GEN3_LAUNCHER": ROOT / "scripts/launch_msae_independent_calibration_v3_gen3.sh",
        "FAILED_GEN3_RFC": ROOT / "docs/rfc-msae-independent-measurement-v3-post-m4-gen3.md",
        "FAILED_GEN3_TESTS": ROOT / "tests/test_msae_independent_measurement_v3_post_m4_gen3.py",
        "FAILED_GEN3_IMPLEMENTATION_REVIEW": FAILED_GEN3_IMPLEMENTATION_REVIEW,
    }
    entries = {name: _regular_entry(path) for name, path in paths.items()}
    expected = {
        "FAILED_GEN3_PLAN": FAILED_GEN3_PLAN_SHA256,
        "FAILED_GEN3_PLAN_REVIEW": FAILED_GEN3_PLAN_REVIEW_SHA256,
        "FAILED_GEN3_CONTROLLER": "734e52a4d5836b3084a887c3eb681d6842750ed471b817cf4c5b201260866cd5",
        "FAILED_GEN3_RUNTIME": "1fe6146984ba1faac59d95063cc6468e5be477f340cf17a43a66905f87a15d0f",
        "FAILED_GEN3_RUNNER": "d243b62dc081d32a59491837c40356b138b26e08e36eb294d2fb6ba0ac8073d6",
        "FAILED_GEN3_LAUNCHER": "6a036d17fac6fa60884c54c7d9f98bc45f2d9f2194d2b3beca1d85fa58b91ba1",
        "FAILED_GEN3_RFC": "3d879bf957b859e25feacb26fa25a20a0abba850e502c50a893b2b3408d118df",
        "FAILED_GEN3_TESTS": "04c32b11d7206927f2c4b33471f2c86d4eb47e954d4101d40d15f2c4094d4c2d",
        "FAILED_GEN3_IMPLEMENTATION_REVIEW": FAILED_GEN3_IMPLEMENTATION_REVIEW_SHA256,
    }
    observed = {name: entry["sha256"] for name, entry in entries.items()}
    if observed != expected:
        raise ValueError(f"immutable failed-gen3 entry drift: {observed!r}")
    return entries


def _verify_historical_preflight_readonly() -> dict[str, Any]:
    raw = _regular_bytes(PREFLIGHT_FAILURE_PATH, mode=0o644)
    if base.sha_bytes(raw) != HISTORICAL_PREFLIGHT_SHA256:
        raise ValueError("historical preflight digest drift")
    value = base.strict_json_loads(raw.decode("utf-8"))
    if raw != base.canonical_bytes(value):
        raise ValueError("historical preflight canonical bytes drift")
    expected_top = {
        "schema_version", "protocol_id", "generation", "status",
        "reviewed_m2_completion_sha256", "config_entry", "commitment_entry",
        "public_key_entry", "private_key_lstat", "bound_runtime_sha256",
        "failure", "stage_a", "authorization_signature", "model_gpu_tmux",
        "successor_generation",
    }
    if (set(value) != expected_top
            or value.get("generation") != "post_m2_gen1_failed_preflight"
            or value.get("successor_generation") != "post_m2_gen2"
            or value.get("stage_a") != "not_run"
            or value.get("authorization_signature") != "not_created"
            or value.get("model_gpu_tmux") != "not_run"):
        raise ValueError("historical preflight semantics drift")
    for key, expected_path, expected_sha in (
        ("config_entry", V3_CONFIG / "protocol.json", FAILED_M3_CONFIG_SHA256),
        ("commitment_entry", V3_CONFIG / "authorization_commitment.json", FAILED_M3_COMMITMENT_SHA256),
        ("public_key_entry", V3_CONFIG / "ed25519_public.pem", FAILED_M3_PUBLIC_SHA256),
    ):
        entry = value[key]
        current = _regular_entry(expected_path)
        historical_projection = {key: current[key] for key in (
            "path", "type", "mode", "size", "sha256", "verification_action")}
        if (entry.get("path") != expected_path.relative_to(ROOT).as_posix()
                or entry.get("sha256") != expected_sha
                or historical_projection != entry):
            raise ValueError(f"historical preflight {key} drift")
    private = value["private_key_lstat"]
    private_path = Path(private["path"])
    st = private_path.lstat()
    observed = {"path": str(private_path), "device": st.st_dev, "inode": st.st_ino,
                "uid": st.st_uid, "mode": stat.S_IMODE(st.st_mode),
                "size": st.st_size, "nlink": st.st_nlink, "content_read": False}
    if private != observed:
        raise ValueError("historical preflight private-key lstat drift")
    return value


def _gen3_control_flow_reproduction() -> dict[str, Any]:
    runtime_path = ROOT / "scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py"
    source = runtime_path.read_text(encoding="utf-8")
    tree = ast.parse(source, filename=str(runtime_path))
    generation = None
    function = None
    for node in tree.body:
        if isinstance(node, ast.Assign) and any(
                isinstance(target, ast.Name) and target.id == "GENERATION"
                for target in node.targets):
            if isinstance(node.value, ast.Constant):
                generation = node.value.value
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == "preserve_m3_preflight":
            function = node
    if generation != "post_m2_gen3" or function is None:
        raise ValueError("failed-gen3 control-flow source drift")
    raise_lines: list[int] = []
    write_lines: list[int] = []
    for node in ast.walk(function):
        if isinstance(node, ast.Raise) and isinstance(node.exc, ast.Call):
            args = node.exc.args
            if args and isinstance(args[0], ast.Constant) and args[0].value == "failed-preflight manifest drift":
                raise_lines.append(node.lineno)
        if (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                and node.func.attr in {"write_once", "install_json"}):
            write_lines.append(node.lineno)
    if raise_lines != [3315] or write_lines != [3317] or raise_lines[0] >= write_lines[0]:
        raise ValueError("failed-gen3 dominating-raise proof drift")
    preflight = _verify_historical_preflight_readonly()
