def _typed_json_leaf_differences(
    left: Any, right: Any, pointer: str = "",
) -> list[dict[str, Any]]:
    """Return exact JSON-leaf differences with RFC-6901-style pointers."""
    if type(left) is not type(right):
        return [{"pointer": pointer or "/", "live": left, "candidate": right}]
    if isinstance(left, dict):
        differences: list[dict[str, Any]] = []
        keys = sorted(set(left) | set(right), key=lambda value: str(value).encode("utf-8"))
        for key in keys:
            escaped = str(key).replace("~", "~0").replace("/", "~1")
            child = f"{pointer}/{escaped}"
            if key not in left or key not in right:
                differences.append({"pointer": child, "live": left.get(key),
                                    "candidate": right.get(key)})
            else:
                differences.extend(_typed_json_leaf_differences(left[key], right[key], child))
        return differences
    if isinstance(left, list):
        differences = []
        for index in range(max(len(left), len(right))):
            child = f"{pointer}/{index}"
            if index >= len(left) or index >= len(right):
                differences.append({"pointer": child,
                                    "live": left[index] if index < len(left) else None,
                                    "candidate": right[index] if index < len(right) else None})
            else:
                differences.extend(
                    _typed_json_leaf_differences(left[index], right[index], child))
        return differences
    return [] if left == right else [
        {"pointer": pointer or "/", "live": left, "candidate": right}]


def _validate_gen2_terminal_namespace(*, require_failure: bool) -> None:
    """Close every gen2 child set without opening any quarantined payload."""
    _exact_directory_entries(predecessor_runtime.ACTIVE_CONFIG, {
        "protocol.json", "authorization_commitment.json", "ed25519_public.pem",
        "cpu_no_model_public_entry_trace.json",
    })
    _exact_directory_entries(
        predecessor_runtime.ACTIVE_PROV,
        {"m4_failure.json"} if require_failure else set())
    _exact_directory_entries(predecessor_runtime.ACTIVE_STATE, {"nonces"})
    _exact_directory_entries(predecessor_runtime.ACTIVE_NONCE_DIR, set())
    _exact_directory_entries(V3_DATA, {
        name for phase in ("M0", "M1", "M2")
        for name in base.V3_DATA_PHASE_FILES[phase]})
    for path in (predecessor_runtime.ACTIVE_CONFIG,
                 predecessor_runtime.ACTIVE_PROV,
                 predecessor_runtime.ACTIVE_STATE,
                 predecessor_runtime.ACTIVE_NONCE_DIR):
        st = path.lstat()
        if (stat.S_IMODE(st.st_mode) != 0o700 or st.st_uid != os.getuid()
                or not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode)):
            raise ValueError(f"failed gen2 secure-directory drift: {path}")


def _rebuild_generic_config_at_synthetic_root(
    candidate_root: Path, checkpoints: list[dict[str, Any]],
) -> dict[str, Any]:
    """Execute immutable generic-builder bytes with typed read-only path mapping."""
    builder_path = ROOT / "scripts/msae_independent_measurement_v3.py"
    _regular_entry(builder_path)
    module_name = f"_msae_gen2_failure_rooted_{os.getpid()}_{id(candidate_root)}"
    spec = continuation.source_only_module_spec(module_name, builder_path)
    if spec is None or spec.loader is None:
        raise ValueError("cannot load immutable generic builder for failure reproduction")
    rooted_builder = importlib.util.module_from_spec(spec)
    captured: list[dict[str, Any]] = []

    def live_alias(path: Path) -> Path:
        return (ROOT / path.relative_to(candidate_root)
                if path.is_relative_to(candidate_root) else path)

    try:
        sys.modules[module_name] = rooted_builder
        spec.loader.exec_module(rooted_builder)
        rooted_builder.ROOT = candidate_root
        rooted_builder.V3_CONFIG = candidate_root / "configs/msae_independent_measurement_v3"
        rooted_builder.__file__ = str(
            candidate_root / "scripts/msae_independent_measurement_v3.py")
        rooted_builder.read_json = lambda path: base.read_json(live_alias(Path(path)))
        rooted_builder.sha_file = lambda path: base.sha_file(live_alias(Path(path)))
        rooted_builder.install_json = lambda path, value: captured.append(value)
        value = rooted_builder.build_protocol_config(checkpoints)
    finally:
        sys.modules.pop(module_name, None)
    if len(captured) != 1 or captured[0] != value:
        raise AssertionError("synthetic-root generic config interception failed")
    return value


def _rebuild_gen2_config_at_synthetic_root(
    candidate_root: Path, checkpoints: list[dict[str, Any]],
) -> dict[str, Any]:
    """Execute immutable generic + gen2 adapter code with no candidate-tree write."""
    rooted_generic = _rebuild_generic_config_at_synthetic_root(
        candidate_root, checkpoints)
    original_builder = base.build_protocol_config
    original_entry = predecessor_runtime._regular_entry

    def intercepted_builder(bound_checkpoints: list[dict[str, Any]]) -> dict[str, Any]:
        if bound_checkpoints != checkpoints:
            raise ValueError("synthetic gen2 checkpoint input drift")
        base.install_json(base.V3_CONFIG / "protocol.json", rooted_generic)
        return rooted_generic

    def rooted_entry(path: Path, *, root: Path) -> dict[str, Any]:
        if root != candidate_root or not path.is_relative_to(candidate_root):
            raise ValueError("synthetic gen2 adapter attempted a non-rooted local entry")
        live_path = ROOT / path.relative_to(candidate_root)
        return original_entry(live_path, root=ROOT)

    try:
        base.build_protocol_config = intercepted_builder
        predecessor_runtime._regular_entry = rooted_entry
        return predecessor_runtime._protocol_config_payload(
            checkpoints, M2_REVIEWED_COMPLETION_SHA256, root=candidate_root)
    finally:
        base.build_protocol_config = original_builder
        predecessor_runtime._regular_entry = original_entry


