def _implementation_review_binding(
    supplied_sha256: str,
    predicted_failed_gen6: Mapping[str, Any],
    pre_capability_review_sha256: str,
) -> dict[str, Any]:
    failed_gen6 = _failed_gen6_entries()
    current = _current_gen9_entries()
    capability = base.read_json(CAPABILITY_REPORT)
    _validate_capability_report(capability)
    if capability.get("overall_pass") is not True:
        raise ValueError("negative gen9 capability report cannot authorize implementation review")
    _pre_capability_review_binding(pre_capability_review_sha256)
    expected = {
        "M1_COMPLETION": M1_REVIEWED_COMPLETION_SHA256,
        "M2_COMPLETION": M2_REVIEWED_COMPLETION_SHA256,
        "GEN6_PLAN": failed_gen6["plan"]["sha256"],
        "GEN6_PLAN_REVIEW": failed_gen6["plan_review"]["sha256"],
        "GEN6_FAILURE_REVIEW": FAILED_GEN6_FAILURE_REVIEW_SHA256,
        "GEN6_CONTROLLER": failed_gen6["controller"]["sha256"],
        "GEN6_RUNTIME": failed_gen6["runtime"]["sha256"],
        "GEN6_RUNNER": failed_gen6["runner"]["sha256"],
        "GEN6_LAUNCHER": failed_gen6["launcher"]["sha256"],
        "GEN6_TMUX_TEST_SUPERVISOR": failed_gen6["tmux_test_supervisor"]["sha256"],
        "GEN6_RFC": failed_gen6["rfc"]["sha256"],
        "GEN6_TESTS": failed_gen6["tests"]["sha256"],
        "GEN7_CAPABILITY_REPRODUCTION": base.sha_file(CAPABILITY_REPORT),
        "PREDICTED_GEN7_FAILED_GEN6": base.sha_bytes(
            base.canonical_bytes(dict(predicted_failed_gen6))),
        "GEN7_PLAN": FROZEN_PLAN_SHA256,
        "GEN7_PLAN_REVIEW": FROZEN_PLAN_REVIEW_SHA256,
        "GEN7_PRE_CAPABILITY_REVIEW": pre_capability_review_sha256,
        **{name: entry["sha256"] for name, entry in current.items()
           if name not in {"GEN7_PLAN", "GEN7_PLAN_REVIEW"}},
    }
    review = _canonical_review(
        IMPLEMENTATION_REVIEW,
        supplied_sha256,
        scope="gen9_implementation",
        expected_digests=expected,
    )
    raw = _regular_bytes(IMPLEMENTATION_REVIEW, mode=0o644)
    if raw.decode("utf-8").splitlines().count(
            "SEALED_PAYLOAD_CONTENT_READS: 0") != 1:
        raise ValueError("implementation review sealed-read control drift")
    return review


def _environment_derivation(*, candidate_root: Path) -> dict[str, Any]:
    external_python = (ROOT / ".venv-atlas/bin/python").resolve(strict=True)
    st = external_python.stat()
    generic_payload = {
        "python": str(external_python), "deterministic": True, "tf32": False,
        "model_revision": base.SNAPSHOT.name, "dtype": "float16",
        "cache_dtype": "float32",
    }
    return {
        "schema_version": "msae_v3_gen3_environment_derivation_v1",
        "canonical_external_python_realpath": str(external_python),
        "canonical_external_python_size": st.st_size,
        "canonical_external_python_mode": stat.S_IMODE(st.st_mode),
        "canonical_external_python_sha256": base.sha_file(external_python),
        "python_startup_sha256": base.sha_bytes(base.canonical_bytes(_python_startup_payload())),
        "deterministic_algorithms": True, "allow_tf32": False,
        "model_revision": base.SNAPSHOT.name, "model_dtype": "float16",
        "cache_dtype": "float32",
        "canonical_environment_sha256": base.sha_bytes(base.canonical_bytes(generic_payload)),
    }


def _rooted_generic_environment_sha256(candidate_root: Path) -> str:
    return base.sha_bytes(base.canonical_bytes({
        "python": str((candidate_root / ".venv-atlas/bin/python").resolve()),
        "deterministic": True, "tf32": False,
        "model_revision": base.SNAPSHOT.name, "dtype": "float16",
        "cache_dtype": "float32",
    }))


def _rooted_generic_protocol_config(
    candidate_root: Path, checkpoints: list[dict[str, Any]],
) -> dict[str, Any]:
    """Load and execute the generic protocol builder from one candidate tree."""
    builder_path = candidate_root / "scripts/msae_independent_measurement_v3.py"
    st = builder_path.lstat()
    if (not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode)
            or st.st_uid != os.getuid() or st.st_nlink != 1):
        raise ValueError(f"rooted protocol-builder identity drift: {builder_path}")
    module_name = f"_msae_independent_measurement_v3_rooted_{os.getpid()}_{id(candidate_root)}"
    spec = continuation.source_only_module_spec(module_name, builder_path)
    if spec is None or spec.loader is None:
        raise ValueError("cannot load rooted generic protocol builder")
    rooted_builder = importlib.util.module_from_spec(spec)
    captured: list[dict[str, Any]] = []
    try:
        sys.modules[module_name] = rooted_builder
        spec.loader.exec_module(rooted_builder)
        rooted_builder.install_json = lambda path, value: captured.append(value)
        value = rooted_builder.build_protocol_config(checkpoints)
    finally:
        sys.modules.pop(module_name, None)
    if len(captured) != 1 or captured[0] != value:
        raise AssertionError("rooted protocol config interception failed")
    return value


def _protocol_config_payload(
    checkpoints: list[dict[str, Any]],
    reviewed_m2_sha256: str,
    *,
    plan_review_sha256: str,
    pre_capability_review_sha256: str,
    implementation_review_sha256: str,
    setup_subject_sha256: str | None = None,
    root: Path = ROOT,
) -> dict[str, Any]:
    base_config = _rooted_generic_protocol_config(root, checkpoints)
    derivation = _environment_derivation(candidate_root=root)
    candidate_gen2_runner_sha = base.sha_file(
        root / "scripts/run_msae_independent_calibration_v3.py")
    candidate_gen3_runner_sha = base.sha_file(root / RUNNER.relative_to(ROOT))
    strata = base_config.get("replay", {}).get("strata")
    if (not isinstance(strata, list)
            or [row.get("stratum_id") if isinstance(row, Mapping) else None
                for row in strata] != list(EXPECTED_REPLAY_STRATUM_IDS)):
        raise ValueError("generic replay stratum dimensions drift")
    adapted_strata = []
    for index, original_stratum in enumerate(strata):
        if (not isinstance(original_stratum, dict)
                or original_stratum.get("code_sha256") != candidate_gen2_runner_sha
                or original_stratum.get("environment_sha256") !=
                   _rooted_generic_environment_sha256(root)):
            raise ValueError(f"generic stratum substitution precondition drift: {index}")
        adapted = dict(original_stratum)
        adapted["code_sha256"] = candidate_gen3_runner_sha
        adapted["environment_sha256"] = derivation["canonical_environment_sha256"]
        if ({key: value for key, value in adapted.items()
             if key not in {"code_sha256", "environment_sha256"}} !=
                {key: value for key, value in original_stratum.items()
                 if key not in {"code_sha256", "environment_sha256"}}):
            raise AssertionError("gen3 typed adapter changed an undeclared stratum field")
        adapted_strata.append(adapted)
    base_config = dict(base_config)
    base_config["replay"] = dict(base_config["replay"])
    base_config["replay"]["strata"] = adapted_strata
    registry = endpoint_registry()
    by_category: dict[str, list[str]] = collections.defaultdict(list)
    for row in registry["entries"]:
        by_category[row["category"]].append(row["endpoint_id"])
    config = dict(base_config)
    if setup_subject_sha256 is None:
        rooted_manifest = root / SETUP_MANIFEST.relative_to(ROOT)
        if rooted_manifest.is_file() and not rooted_manifest.is_symlink():
            setup_subject_sha256 = base.read_json(rooted_manifest)["setup_subject_sha256"]
        else:
            # Reversible CPU-only pre-M3 probes compare roots before a key or
            # setup subject exists. Production setup always supplies the real
            # subject and every post-M3 reconstruction reads the manifest.
            setup_subject_sha256 = base.sha_bytes(base.canonical_bytes({
                "schema_version": "msae_v3_gen9_pre_m3_setup_subject_probe_v1",
                "generation": GENERATION,
            }))
    base.validate_sha256(setup_subject_sha256, "setup subject SHA-256")
    config["post_m2_runtime"] = {
        "generation": GENERATION,
        "reviewed_m2_completion_sha256": reviewed_m2_sha256,
        "operator_instruction_sha256": base.sha_bytes(OPERATOR_INSTRUCTION.encode("utf-8")),
        "runtime_entry": _regular_entry(root / RUNTIME.relative_to(ROOT), root=root),
        "runner_entry": _regular_entry(root / RUNNER.relative_to(ROOT), root=root),
        "launcher_entry": _regular_entry(root / LAUNCHER.relative_to(ROOT), root=root),
        "runtime_rfc_entry": _regular_entry(root / RUNTIME_RFC.relative_to(ROOT), root=root),
        "runtime_test_entry": _regular_entry(root / RUNTIME_TEST.relative_to(ROOT), root=root),
        "model_snapshot_path": str(base.SNAPSHOT), "model_snapshot_revision": base.SNAPSHOT.name,
        "active_config_root": str(ACTIVE_CONFIG.relative_to(ROOT)),
        "active_provenance_root": str(ACTIVE_PROV.relative_to(ROOT)),
        "active_run_root": ACTIVE_RUN_REL,
        "environment_derivation": derivation,
        "review_gates": {
            "plan_sha256": FROZEN_PLAN_SHA256,
            "plan_entry": _regular_entry(root / PLAN_PATH.relative_to(ROOT), root=root),
            "plan_review_entry": _regular_entry(root / PLAN_REVIEW.relative_to(ROOT), root=root),
            "plan_review_sha256": plan_review_sha256,
            "pre_capability_review_entry": _regular_entry(
                root / PRE_CAPABILITY_REVIEW.relative_to(ROOT), root=root),
            "pre_capability_review_sha256": pre_capability_review_sha256,
            "implementation_review_entry": _regular_entry(
                root / IMPLEMENTATION_REVIEW.relative_to(ROOT), root=root),
            "implementation_review_sha256": implementation_review_sha256,
        },
        "setup_subject_sha256": setup_subject_sha256,
        "implementation_review_authority_sha256": implementation_review_sha256,
    }
    config["checkpoint_registry"] = checkpoints
    config["endpoint_registry_payload_sha256"] = base.sha_bytes(base.canonical_bytes(registry))
    config["stages"] = dict(config["stages"])
    config["stages"]["C"] = {"purpose": "decision_review_candidate",
                               "required_by_category": {key: sorted(value) for key, value in by_category.items()},
                               "optional": []}
    replay = config["replay"]
    if any(row["source_role"] != replay["source_role"]
           or row["source_revision"] != replay["source_revision"]
           or row["partition"] != replay["partition"] for row in replay["strata"]):
        raise ValueError("global replay source/partition does not bind every stratum")
    for row in replay["strata"]:
        if (row["code_sha256"] != candidate_gen3_runner_sha
                or row["environment_sha256"] != derivation["canonical_environment_sha256"]):
            raise ValueError("gen3 replay code/environment adapter did not close")
    return config


def _validate_private_key_lstat_binding(
    path: Path, expected: Mapping[str, Any],
) -> os.stat_result:
    """Validate a committed private-key identity without reading key bytes."""
    st = path.lstat()
    if (not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode)
            or expected.get("path") != str(path)
            or (st.st_dev, st.st_ino, st.st_uid, st.st_gid, st.st_nlink,
                stat.S_IMODE(st.st_mode), st.st_size, st.st_mtime_ns, st.st_ctime_ns) !=
               (expected.get("device"), expected.get("inode"), expected.get("uid"),
                expected.get("gid"), expected.get("nlink"), expected.get("mode"), expected.get("size"),
                expected.get("mtime_ns"), expected.get("ctime_ns"))):
        raise ValueError("private key binding drift")
    return st


def _verify_existing_authorization_state(
    *, verify_private_content: bool = False,
) -> dict[str, Any]:
    from cryptography.hazmat.primitives import serialization
    config_st = ACTIVE_CONFIG.lstat()
    if (not stat.S_ISDIR(config_st.st_mode) or stat.S_ISLNK(config_st.st_mode)
            or stat.S_IMODE(config_st.st_mode) != 0o700
            or config_st.st_uid != os.getuid() or config_st.st_gid != os.getgid()):
        raise ValueError("active config directory identity/mode/ownership drift")
    commitment_raw = _regular_bytes(ACTIVE_CONFIG / "authorization_commitment.json", mode=0o644)
    commitment = base.strict_json_loads(commitment_raw.decode("utf-8"))
    if commitment_raw != base.canonical_bytes(commitment):
        raise ValueError("authorization commitment is not canonical")
    commitment_keys = {
        "schema_version", "protocol_id", "generation", "operator_instruction",
        "operator_instruction_sha256", "public_key_path", "public_key_sha256",
        "public_key_fingerprint", "private_key_binding", "algorithm",
        "envelope_schema", "allowed_scope", "maximum_lifetime_seconds",
        "nonce_directory", "gpu_lock_directory", "review_gates",
        "setup_subject_sha256", "contains_execution_authorization",
    }
    if (set(commitment) != commitment_keys
            or commitment.get("schema_version") != "msae_v3_authorization_commitment_v3"
            or commitment.get("protocol_id") != PROTOCOL
            or commitment.get("generation") != GENERATION
            or commitment.get("operator_instruction") != OPERATOR_INSTRUCTION
            or commitment.get("operator_instruction_sha256") != base.sha_bytes(OPERATOR_INSTRUCTION.encode("utf-8"))
            or commitment.get("public_key_path") !=
               str((ACTIVE_CONFIG / "ed25519_public.pem").relative_to(ROOT))
            or commitment.get("public_key_fingerprint") != commitment.get("public_key_sha256")
            or commitment.get("algorithm") != "Ed25519"
            or commitment.get("envelope_schema") != "msae_v3_signed_authorization_v2"
            or commitment.get("contains_execution_authorization") is not False
            or commitment.get("allowed_scope") != "calibration_replay_only"
            or commitment.get("maximum_lifetime_seconds") != 86400):
        raise ValueError("authorization commitment semantics drift")
    base.validate_sha256(commitment.get("setup_subject_sha256"), "setup subject SHA-256")
    review_gates = commitment.get("review_gates")
    expected_review_gates = _trace_review_gates(
        ROOT, FROZEN_PLAN_REVIEW_SHA256, base.sha_file(PRE_CAPABILITY_REVIEW),
        base.sha_file(IMPLEMENTATION_REVIEW))
    if review_gates != expected_review_gates:
        raise ValueError("authorization commitment review-gate binding drift")
    expected = commitment["private_key_binding"]
    if (not isinstance(expected, dict)
            or set(expected) != {"path", "device", "inode", "uid", "mode", "nlink",
                                 "size", "mtime_ns", "ctime_ns", "public_key_match"}
            or expected.get("public_key_match") is not True):
        raise ValueError("private key binding schema drift")
    _validate_private_key_lstat_binding(ACTIVE_PRIVATE_KEY, expected)
    public_bytes = _regular_bytes(ACTIVE_CONFIG / "ed25519_public.pem", mode=0o644)
    if base.sha_bytes(public_bytes) != commitment["public_key_sha256"]:
        raise ValueError("public key digest drift")
    if verify_private_content:
        private_raw = _regular_bytes(ACTIVE_PRIVATE_KEY, mode=0o600)
        private = serialization.load_pem_private_key(private_raw, password=None)
        derived = private.public_key().public_bytes(
            serialization.Encoding.PEM,
            serialization.PublicFormat.SubjectPublicKeyInfo)
        if derived != public_bytes:
            raise ValueError("private/public key mismatch")
    nonce = base._directory_binding(ACTIVE_NONCE_DIR)
    gpu = base._directory_binding(base.GPU_LOCK_DIR)
    if nonce != commitment.get("nonce_directory") or gpu != commitment.get("gpu_lock_directory"):
        raise ValueError("authorization state directory binding drift")
    return commitment


def preserve_m3_preflight() -> dict[str, Any]:
    """Read-only exact verifier for the immutable historical preflight."""
    return _verify_historical_preflight_readonly()


def _atomic_publish(
    path: Path, raw: bytes, mode: int, *, allow_unbound_partial: bool = False,
) -> None:
    """Publish a reversible scratch artifact with link/unlink no-replace.

    Authoritative gen9 setup, M4-install, and signing objects use the
    descriptor-bound :func:`_link_publication` state machine below.  This
    smaller helper remains only for disposable candidate-tree and test
    artifacts; importantly, it no longer relies on ``renameat2``, which the
    target NFS server rejects with ``EINVAL``.
    """
    partial = path.with_name(f".{path.name}.partial")
    if _path_present(path):
        if _path_present(partial):
            raise ValueError(f"final and partial publication coexist: {path}")
        if _regular_bytes(path, mode=mode) != raw:
            raise ValueError(f"published file drift: {path}")
        return
    if _path_present(partial):
        st = partial.lstat()
        if (not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode)
                or st.st_uid != os.getuid() or st.st_nlink != 1
                or stat.S_IMODE(st.st_mode) != mode):
            raise ValueError(f"unsafe publication partial: {partial}")
        observed = partial.read_bytes()
        if not allow_unbound_partial and raw[:len(observed)] != observed:
            raise ValueError(f"publication partial is not an exact prefix: {partial}")
        partial.unlink()
        base._fsync_directory(partial.parent)
    fd = os.open(partial, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, mode)
    try:
        os.fchmod(fd, mode)
        view = memoryview(raw)
        while view:
            written = os.write(fd, view)
            if written <= 0:
                raise OSError("short atomic-publication write")
            view = view[written:]
        os.fsync(fd)
    finally:
        os.close(fd)
    parent_fd = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY |
                        os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        os.link(partial.name, path.name, src_dir_fd=parent_fd,
                dst_dir_fd=parent_fd, follow_symlinks=False)
        os.fsync(parent_fd)
        pair_left = os.stat(partial.name, dir_fd=parent_fd,
                            follow_symlinks=False)
        pair_right = os.stat(path.name, dir_fd=parent_fd,
                             follow_symlinks=False)
        if ((pair_left.st_dev, pair_left.st_ino, pair_left.st_nlink) !=
                (pair_right.st_dev, pair_right.st_ino, 2)):
            raise AssertionError(f"scratch publication link pair drift: {path}")
        os.unlink(partial.name, dir_fd=parent_fd)
        os.fsync(parent_fd)
    finally:
        os.close(parent_fd)
    if _regular_bytes(path, mode=mode) != raw:
        raise AssertionError(f"atomic publication verification failed: {path}")


class RecoverableLinkInterruption(RuntimeError):
    """One descriptor-authorized link attempt ended in exact source-only state."""


class _FsId(ctypes.Structure):
    _fields_ = [("value", ctypes.c_int * 2)]


class _StatFs(ctypes.Structure):
    _fields_ = [
        ("f_type", ctypes.c_long), ("f_bsize", ctypes.c_long),
        ("f_blocks", ctypes.c_ulong), ("f_bfree", ctypes.c_ulong),
        ("f_bavail", ctypes.c_ulong), ("f_files", ctypes.c_ulong),
        ("f_ffree", ctypes.c_ulong), ("f_fsid", _FsId),
        ("f_namelen", ctypes.c_long), ("f_frsize", ctypes.c_long),
        ("f_flags", ctypes.c_long), ("f_spare", ctypes.c_long * 4),
    ]


NFS_SUPER_MAGIC = 0x6969
GEN6_LINK_TRANSACTION_SCHEMA = "msae_v3_gen9_link_transaction_v1"


def _mountinfo_unescape(value: str) -> str:
    return re.sub(r"\\([0-7]{3})", lambda match: chr(int(match.group(1), 8)), value)


def _mount_identity(path: Path) -> dict[str, Any]:
    """Return the exact mountinfo/fstatfs identity for an existing directory."""
    directory = Path(path)
    fd = os.open(directory, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        st = os.fstat(fd)
        path_st = directory.lstat()
        expected_uid = 0 if directory == Path("/tmp") else os.getuid()
        if (not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(path_st.st_mode)
                or (st.st_dev, st.st_ino) != (path_st.st_dev, path_st.st_ino)
                or st.st_uid != expected_uid):
            raise ValueError(f"unsafe mount-identity directory: {directory}")
        value = _StatFs()
        libc = ctypes.CDLL(None, use_errno=True)
        fstatfs = libc.fstatfs
        fstatfs.argtypes = [ctypes.c_int, ctypes.POINTER(_StatFs)]
        fstatfs.restype = ctypes.c_int
        if fstatfs(fd, ctypes.byref(value)) != 0:
            error = ctypes.get_errno()
            raise OSError(error, os.strerror(error), str(directory))
    finally:
        os.close(fd)
    resolved = directory.resolve(strict=True)
    candidates: list[tuple[int, dict[str, Any]]] = []
    for raw_line in Path("/proc/self/mountinfo").read_text(encoding="utf-8").splitlines():
        left, separator, right = raw_line.partition(" - ")
        if not separator:
            raise ValueError("malformed /proc/self/mountinfo row")
        before = left.split(); after = right.split()
        if len(before) < 6 or len(after) != 3:
            raise ValueError("malformed /proc/self/mountinfo fields")
        mount_point = Path(_mountinfo_unescape(before[4]))
        try:
            resolved.relative_to(mount_point)
        except ValueError:
            continue
        row = {
            "mount_id": int(before[0]), "parent_id": int(before[1]),
            "major_minor": before[2], "root": _mountinfo_unescape(before[3]),
            "mount_point": str(mount_point), "mount_options": before[5],
            "optional_fields": before[6:], "filesystem_type": after[0],
            "mount_source": _mountinfo_unescape(after[1]),
            "super_options": after[2],
        }
        candidates.append((len(str(mount_point)), row))
    if not candidates:
        raise ValueError(f"no mountinfo row for {directory}")
    row = max(candidates, key=lambda item: item[0])[1]
    fsid = [int(value.f_fsid.value[0]), int(value.f_fsid.value[1])]
    result = {
        "schema_version": "msae_v3_gen9_mount_identity_v1",
        "mountinfo": row,
        "mountinfo_sha256": base.sha_bytes(base.canonical_bytes(row)),
        "filesystem_magic": f"0x{int(value.f_type) & ((1 << 64) - 1):x}",
        "filesystem_fsid": fsid,
        "directory_device": st.st_dev,
    }
    return result


def _require_bound_nfs_mount(path: Path, expected: Mapping[str, Any]) -> dict[str, Any]:
    observed = _mount_identity(path)
    if (observed != dict(expected)
            or observed.get("filesystem_magic") != "0x6969"
            or observed.get("mountinfo", {}).get("filesystem_type") not in {"nfs", "nfs4"}):
        raise ValueError(f"registered NFS mount identity drift: {path}")
    return observed


def _write_file_at(directory_fd: int, basename: str, raw: bytes, mode: int) -> None:
    if (not basename or basename in {".", ".."} or "/" in basename
            or "\\" in basename):
        raise ValueError("publication basename is not a single component")
    fd = os.open(basename, os.O_WRONLY | os.O_CREAT | os.O_EXCL |
                 os.O_NOFOLLOW | os.O_CLOEXEC, mode, dir_fd=directory_fd)
    try:
        os.fchmod(fd, mode)
        view = memoryview(raw)
        while view:
            written = os.write(fd, view)
            if written <= 0:
                raise OSError("zero-length publication write")
            view = view[written:]
        os.fsync(fd)
    finally:
        os.close(fd)
    os.fsync(directory_fd)


def _file_at_bytes(directory_fd: int, basename: str, *, mode: int,
                   nlink: int) -> tuple[bytes, os.stat_result]:
    fd = os.open(basename, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC,
                 dir_fd=directory_fd)
    try:
        before = os.fstat(fd)
        if (not stat.S_ISREG(before.st_mode) or before.st_uid != os.getuid()
                or stat.S_IMODE(before.st_mode) != mode or before.st_nlink != nlink):
            raise ValueError(f"publication file identity drift: {basename}")
        chunks: list[bytes] = []
        while True:
            chunk = os.read(fd, 1024 * 1024)
            if not chunk: break
            chunks.append(chunk)
        after = os.fstat(fd)
        path_st = os.stat(basename, dir_fd=directory_fd, follow_symlinks=False)
        identity = lambda item: (item.st_dev, item.st_ino, item.st_mode, item.st_uid,
                                 item.st_nlink, item.st_size, item.st_mtime_ns,
                                 item.st_ctime_ns)
        if identity(before) != identity(after) or identity(after) != identity(path_st):
            raise ValueError(f"publication file changed during read: {basename}")
        return b"".join(chunks), after
    finally:
        os.close(fd)


def _file_at_bytes_after_unlink(directory_fd: int, basename: str, *,
                                mode: int,
                                expected_identity: tuple[int, int]
                                ) -> tuple[bytes, os.stat_result]:
    """Wait for NFS to expose the registered one-link terminal state."""
    deadline = time.monotonic() + 3
    while True:
        observed = os.stat(basename, dir_fd=directory_fd, follow_symlinks=False)
        if (not stat.S_ISREG(observed.st_mode) or observed.st_uid != os.getuid()
                or stat.S_IMODE(observed.st_mode) != mode
                or observed.st_nlink not in {1, 2}
                or (observed.st_dev, observed.st_ino) != expected_identity):
            raise ValueError(f"publication post-unlink identity drift: {basename}")
        if observed.st_nlink == 1:
            raw, terminal = _file_at_bytes(
                directory_fd, basename, mode=mode, nlink=1)
            if (terminal.st_dev, terminal.st_ino) != expected_identity:
                raise ValueError(
                    f"publication post-unlink inode changed: {basename}")
            return raw, terminal
        if time.monotonic() >= deadline:
            raise ValueError(
                f"publication post-unlink link count did not settle: {basename}")
        time.sleep(0.01)


def _name_state(directory_fd: int, basename: str) -> os.stat_result | None:
    try:
        return os.stat(basename, dir_fd=directory_fd, follow_symlinks=False)
    except FileNotFoundError:
        return None


def _linkat(source_fd: int, source: str, destination_fd: int, destination: str) -> None:
    libc = ctypes.CDLL(None, use_errno=True)
    linkat = libc.linkat
    linkat.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int,
                       ctypes.c_char_p, ctypes.c_int]
    linkat.restype = ctypes.c_int
    if linkat(source_fd, os.fsencode(source), destination_fd,
              os.fsencode(destination), 0) != 0:
        error = ctypes.get_errno()
        raise OSError(error, os.strerror(error), destination)


def _validate_publication_row(row: Mapping[str, Any], *, raw: bytes) -> None:
    common = {"ordinal", "source_parent", "source_basename",
              "destination_parent", "destination_basename", "mode", "uid",
              "payload_kind", "authority_kind"}
    authority_kind = row.get("authority_kind")
    required = (common | {"payload_sha256", "payload_size"}
                if authority_kind == "fixed_sha256" else
                common | {"builder_id", "builder_input_sha256", "output_schema",
                          "allowed_fields"})
    if (set(row) != required or not isinstance(row.get("ordinal"), int)
            or row.get("uid") != os.getuid()
            or row.get("mode") not in {0o600, 0o644}):
        raise ValueError("publication row authority drift")
    if authority_kind == "fixed_sha256":
        if (row.get("payload_sha256") != base.sha_bytes(raw)
                or row.get("payload_size") != len(raw)):
            raise ValueError("fixed publication payload drift")
    elif authority_kind == "derived_builder":
        base.validate_sha256(str(row.get("builder_input_sha256")),
                             "derived publication input SHA-256")
        value = base.strict_json_loads(raw.decode("utf-8"))
        if (not isinstance(row.get("builder_id"), str)
                or value.get("schema_version") != row.get("output_schema")
                or sorted(value) != sorted(row.get("allowed_fields", []))
                or raw != base.canonical_bytes(value)):
            raise ValueError("derived publication payload/schema drift")
    else:
        raise ValueError("publication authority kind drift")
    for key in ("source_basename", "destination_basename"):
        value = row.get(key)
        if (not isinstance(value, str) or not value or value in {".", ".."}
                or "/" in value or "\\" in value):
            raise ValueError("publication row basename drift")


def _link_publication(
    descriptor: Mapping[str, Any], row: Mapping[str, Any], raw: bytes, *,
    descriptor_path: Path | None,
    link_function: Any = None,
    derived_reproducer: Any = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Advance one descriptor-bound publication by at most one link attempt."""
    _validate_publication_row(row, raw=raw)
    if row.get("authority_kind") == "derived_builder":
        if not callable(derived_reproducer):
            raise ValueError("derived publication lacks an independent reproducer")
        reproduced = derived_reproducer()
        if (not isinstance(reproduced, bytes) or reproduced != raw):
            raise ValueError("derived publication builder reproduction drift")
    elif derived_reproducer is not None:
        raise ValueError("fixed publication unexpectedly supplied a reproducer")
    if descriptor.get("schema_version") != GEN6_LINK_TRANSACTION_SCHEMA:
        raise ValueError("link transaction schema drift")
    publications = descriptor.get("publications")
    if (not isinstance(publications, list)
            or int(row["ordinal"]) >= len(publications)
            or publications[int(row["ordinal"])] != dict(row)):
        raise ValueError("publication row is not descriptor-bound")
    descriptor_before: os.stat_result | None = None
    descriptor_expected_raw: bytes | None = None
    if descriptor_path is not None:
        descriptor_raw = _regular_bytes(descriptor_path, mode=0o600)
        if descriptor_raw != base.canonical_bytes(dict(descriptor)):
            raise ValueError("link transaction descriptor bytes drift")
        descriptor_before = descriptor_path.lstat()
        descriptor_expected_raw = descriptor_raw
    source_parent = Path(str(row["source_parent"]))
    destination_parent = Path(str(row["destination_parent"]))
    bound_mount = descriptor.get("mount_identity")
    if not isinstance(bound_mount, dict):
        raise ValueError("link transaction mount binding missing")
    _require_bound_nfs_mount(source_parent, bound_mount)
    _require_bound_nfs_mount(destination_parent, bound_mount)
    source_fd = os.open(source_parent, os.O_RDONLY | os.O_DIRECTORY |
                        os.O_NOFOLLOW | os.O_CLOEXEC)
    destination_fd = os.open(destination_parent, os.O_RDONLY | os.O_DIRECTORY |
                             os.O_NOFOLLOW | os.O_CLOEXEC)
    source_parent_before = os.fstat(source_fd)
    destination_parent_before = os.fstat(destination_fd)
    source_path_before = source_parent.lstat()
    destination_path_before = destination_parent.lstat()
    for label, held, by_path in (
        ("source", source_parent_before, source_path_before),
        ("destination", destination_parent_before, destination_path_before),
    ):
        if (not stat.S_ISDIR(held.st_mode) or stat.S_ISLNK(by_path.st_mode)
                or (held.st_dev, held.st_ino) != (by_path.st_dev, by_path.st_ino)
                or held.st_uid != os.getuid()
                or stat.S_IMODE(held.st_mode) != 0o700):
            os.close(destination_fd); os.close(source_fd)
            raise ValueError(f"publication {label} parent identity drift")
    if source_parent_before.st_dev != destination_parent_before.st_dev:
        os.close(destination_fd); os.close(source_fd)
        raise ValueError("publication parents are not on the same filesystem")
    source = str(row["source_basename"]); destination = str(row["destination_basename"])
    marker_prefix = f".{destination}.attempt-"
    try:
        source_state = _name_state(source_fd, source)
        destination_state = _name_state(destination_fd, destination)
        marker_names = []
        for entry in os.scandir(source_fd):
            if entry.name.startswith(marker_prefix):
                marker_names.append(entry.name)
        expected_markers = [f"{marker_prefix}{index}" for index in range(1, len(marker_names) + 1)]
        if sorted(marker_names) != expected_markers or len(marker_names) > 3:
            raise ValueError("publication attempt-marker prefix drift")
        for marker in marker_names:
            marker_st = os.stat(marker, dir_fd=source_fd, follow_symlinks=False)
            marker_fd = os.open(
                marker, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW |
                os.O_CLOEXEC, dir_fd=source_fd)
            try:
                marker_held = os.fstat(marker_fd)
                if (not stat.S_ISDIR(marker_st.st_mode)
                        or marker_st.st_uid != os.getuid()
                        or stat.S_IMODE(marker_st.st_mode) != 0o700
                        or (marker_st.st_dev, marker_st.st_ino) !=
                           (marker_held.st_dev, marker_held.st_ino)
                        or any(os.scandir(marker_fd))):
                    raise ValueError("publication attempt-marker identity drift")
            finally:
                os.close(marker_fd)

        if destination_state is not None and source_state is None:
            # After a crash immediately following source unlink, NFS can
            # transiently report the surviving destination with nlink=2.
            # Accept only that registered transition and wait for the exact
            # one-link terminal identity before interpreting bytes.
            observed, _ = _file_at_bytes_after_unlink(
                destination_fd, destination, mode=int(row["mode"]),
                expected_identity=(destination_state.st_dev,
                                   destination_state.st_ino))
            if observed != raw:
                raise ValueError("publication destination-only bytes drift")
            outcome = "destination_only"
        elif destination_state is not None and source_state is not None:
            source_raw, source_st = _file_at_bytes(source_fd, source,
                                                   mode=int(row["mode"]), nlink=2)
            destination_raw, destination_st = _file_at_bytes(
                destination_fd, destination, mode=int(row["mode"]), nlink=2)
            if (source_raw != raw or destination_raw != raw
                    or (source_st.st_dev, source_st.st_ino) !=
                       (destination_st.st_dev, destination_st.st_ino)):
                raise ValueError("publication exact-pair drift")
            os.fsync(destination_fd)
            os.unlink(source, dir_fd=source_fd); os.fsync(source_fd)
            final_raw, _ = _file_at_bytes_after_unlink(
                destination_fd, destination, mode=int(row["mode"]),
                expected_identity=(destination_st.st_dev,
                                   destination_st.st_ino))
            if final_raw != raw:
                raise ValueError("publication pair cleanup drift")
            outcome = "exact_pair_completed"
        else:
            if source_state is None:
                if marker_names:
                    raise ValueError("publication source/destination data loss after attempt")
                _write_file_at(source_fd, source, raw, int(row["mode"]))
            else:
                source_raw, _ = _file_at_bytes(source_fd, source,
                                               mode=int(row["mode"]), nlink=1)
                if source_raw != raw:
                    raise ValueError("publication source-only bytes drift")
            instant = time.time() if now is None else now
            if instant > float(descriptor["recovery_deadline_unix"]):
                raise ValueError("link transaction deadline expired before new attempt")
            if len(marker_names) >= int(descriptor["maximum_link_attempts"]):
                raise ValueError("link transaction attempt budget exhausted")
            marker = f"{marker_prefix}{len(marker_names) + 1}"
            os.mkdir(marker, mode=0o700, dir_fd=source_fd)
            marker_fd = os.open(marker, os.O_RDONLY | os.O_DIRECTORY |
                                os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=source_fd)
            try:
                os.fchmod(marker_fd, 0o700); os.fsync(marker_fd)
            finally:
                os.close(marker_fd)
            os.fsync(source_fd)
            expected_markers.append(marker)
            if derived_reproducer is not None:
                reproduced = derived_reproducer()
                if (not isinstance(reproduced, bytes) or reproduced != raw):
                    raise ValueError(
                        "derived publication pre-link reproduction drift")
            try:
                (link_function or _linkat)(source_fd, source, destination_fd, destination)
            except OSError as exc:
                # NFS can return an error after completing the link.  Resolve
                # only from held-descriptor namespace state.
                destination_after = _name_state(destination_fd, destination)
                if destination_after is None:
                    source_raw, _ = _file_at_bytes(source_fd, source,
                                                   mode=int(row["mode"]), nlink=1)
                    if source_raw != raw:
                        raise ValueError("publication uncertain source drift") from exc
                    raise RecoverableLinkInterruption(
                        f"registered link attempt retained exact source-only state: {exc}") from exc
            # Success or uncertain success converges through exact-pair logic.
            source_raw, source_st = _file_at_bytes(source_fd, source,
                                                   mode=int(row["mode"]), nlink=2)
            destination_raw, destination_st = _file_at_bytes(
                destination_fd, destination, mode=int(row["mode"]), nlink=2)
            if (source_raw != raw or destination_raw != raw
                    or (source_st.st_dev, source_st.st_ino) !=
                       (destination_st.st_dev, destination_st.st_ino)):
                raise ValueError("publication post-link pair drift")
            os.fsync(destination_fd)
            os.unlink(source, dir_fd=source_fd); os.fsync(source_fd)
            final_raw, _ = _file_at_bytes_after_unlink(
                destination_fd, destination, mode=int(row["mode"]),
                expected_identity=(destination_st.st_dev,
                                   destination_st.st_ino))
            if final_raw != raw:
                raise ValueError("publication final bytes drift")
            outcome = "linked"
        for marker in reversed(expected_markers):
            os.rmdir(marker, dir_fd=source_fd); os.fsync(source_fd)
        return {"status": "published", "outcome": outcome,
                "attempt_markers_consumed": len(expected_markers)}
    finally:
        try:
            source_parent_after = os.fstat(source_fd)
            destination_parent_after = os.fstat(destination_fd)
            source_path_after = source_parent.lstat()
            destination_path_after = destination_parent.lstat()
            for label, before, after, by_path in (
                ("source", source_parent_before, source_parent_after,
                 source_path_after),
                ("destination", destination_parent_before,
                 destination_parent_after, destination_path_after),
            ):
                if ((before.st_dev, before.st_ino, before.st_uid,
                     stat.S_IMODE(before.st_mode)) !=
                    (after.st_dev, after.st_ino, after.st_uid,
                     stat.S_IMODE(after.st_mode))
                        or (after.st_dev, after.st_ino) !=
                           (by_path.st_dev, by_path.st_ino)
                        or stat.S_ISLNK(by_path.st_mode)):
                    raise ValueError(
                        f"publication {label} parent changed during operation")
            _require_bound_nfs_mount(source_parent, bound_mount)
            _require_bound_nfs_mount(destination_parent, bound_mount)
            if (descriptor_path is not None and descriptor_before is not None
                    and descriptor_expected_raw is not None):
                if (_regular_bytes(descriptor_path, mode=0o600) !=
                        descriptor_expected_raw):
                    raise ValueError("publication descriptor bytes changed")
                descriptor_after = descriptor_path.lstat()
                identity = lambda item: (
                    item.st_dev, item.st_ino, item.st_mode, item.st_uid,
                    item.st_nlink, item.st_size, item.st_mtime_ns,
                    item.st_ctime_ns)
                if identity(descriptor_before) != identity(descriptor_after):
                    raise ValueError(
                        "publication descriptor identity changed during operation")
        finally:
            os.close(destination_fd); os.close(source_fd)


def _link_transaction_payload(
    *, kind: str, authority_sha256: str, publications: Sequence[Mapping[str, Any]],
    maximum_seconds: int, sealed_random_payloads: Mapping[str, str] | None = None,
    created_unix: int | None = None,
) -> dict[str, Any]:
    base.validate_sha256(authority_sha256, "link transaction authority SHA-256")
    if kind not in {"capability", "setup", "m4", "sign"}:
        raise ValueError("link transaction kind drift")
    created = int(time.time()) if created_unix is None else int(created_unix)
    rows = [dict(row) for row in publications]
    if [row.get("ordinal") for row in rows] != list(range(len(rows))):
        raise ValueError("link transaction publication ordinal drift")
    mount = _mount_identity(ROOT)
    if mount["filesystem_magic"] != "0x6969":
        raise ValueError("gen9 production transactions require NFS_SUPER_MAGIC=0x6969")
    return {
        "schema_version": GEN6_LINK_TRANSACTION_SCHEMA,
        "protocol_id": PROTOCOL, "generation": GENERATION,
        "transaction_kind": kind, "authority_sha256": authority_sha256,
        "publications": rows, "mount_identity": mount,
        "mountinfo_sha256": mount["mountinfo_sha256"],
        "filesystem_magic": "0x6969", "filesystem_fsid": mount["filesystem_fsid"],
        "created_unix": created, "recovery_deadline_unix": created + maximum_seconds,
        "maximum_link_attempts": 3,
        "sealed_random_payloads": dict(sealed_random_payloads or {}),
    }


def _validate_link_transaction_descriptor(
    descriptor: Mapping[str, Any], *, kind: str, authority_sha256: str,
    publications: Sequence[Mapping[str, Any]], maximum_seconds: int,
) -> None:
    """Revalidate the complete common descriptor authority on every recovery."""
    keys = {
        "schema_version", "protocol_id", "generation", "transaction_kind",
        "authority_sha256", "publications", "mount_identity",
        "mountinfo_sha256", "filesystem_magic", "filesystem_fsid",
        "created_unix", "recovery_deadline_unix", "maximum_link_attempts",
        "sealed_random_payloads",
    }
    base.validate_sha256(authority_sha256,
                         "link transaction authority SHA-256")
    mount = _mount_identity(ROOT)
    if (set(descriptor) != keys
            or descriptor.get("schema_version") != GEN6_LINK_TRANSACTION_SCHEMA
            or descriptor.get("protocol_id") != PROTOCOL
            or descriptor.get("generation") != GENERATION
            or descriptor.get("transaction_kind") != kind
            or descriptor.get("authority_sha256") != authority_sha256
            or descriptor.get("publications") != [dict(row) for row in publications]
            or descriptor.get("mount_identity") != mount
            or descriptor.get("mountinfo_sha256") != mount["mountinfo_sha256"]
            or descriptor.get("filesystem_magic") != "0x6969"
            or descriptor.get("filesystem_fsid") != mount["filesystem_fsid"]
            or not isinstance(descriptor.get("created_unix"), int)
            or isinstance(descriptor.get("created_unix"), bool)
            or descriptor.get("recovery_deadline_unix") !=
               descriptor["created_unix"] + maximum_seconds
            or descriptor.get("maximum_link_attempts") != 3
            or not isinstance(descriptor.get("sealed_random_payloads"), dict)):
        raise ValueError(f"{kind} link transaction descriptor authority drift")


def _publication_row(ordinal: int, source_parent: Path, source_basename: str,
                     destination_parent: Path, destination_basename: str,
                     raw: bytes, mode: int, payload_kind: str) -> dict[str, Any]:
    return {
        "ordinal": ordinal, "source_parent": str(source_parent),
        "source_basename": source_basename,
        "destination_parent": str(destination_parent),
        "destination_basename": destination_basename, "mode": mode,
        "uid": os.getuid(), "payload_kind": payload_kind,
        "authority_kind": "fixed_sha256", "payload_sha256": base.sha_bytes(raw),
        "payload_size": len(raw),
    }


def _derived_publication_row(
    ordinal: int, source_parent: Path, source_basename: str,
    destination_parent: Path, destination_basename: str, mode: int,
    payload_kind: str, *, builder_id: str, builder_input_sha256: str,
    output_schema: str, allowed_fields: Sequence[str],
) -> dict[str, Any]:
    base.validate_sha256(builder_input_sha256, "derived publication input SHA-256")
    return {
        "ordinal": ordinal, "source_parent": str(source_parent),
        "source_basename": source_basename,
        "destination_parent": str(destination_parent),
        "destination_basename": destination_basename, "mode": mode,
        "uid": os.getuid(), "payload_kind": payload_kind,
        "authority_kind": "derived_builder", "builder_id": builder_id,
        "builder_input_sha256": builder_input_sha256,
        "output_schema": output_schema, "allowed_fields": list(allowed_fields),
    }


def _bootstrap_link_transaction(root: Path, descriptor: Mapping[str, Any]) -> None:
    raw = base.canonical_bytes(dict(descriptor))
    bootstrap = root / ".transaction.json.bootstrap"
    final = root / "transaction.json"
    row = _publication_row(0, root, bootstrap.name, root, final.name,
                           raw, 0o600, "transaction_descriptor")
    bootstrap_authority = {**dict(descriptor), "publications": [row]}
    if _path_present(final):
        # Re-enter even from destination-only state so an attempt marker left
        # after source unlink is validated and consumed.  Do not pre-read the
        # final with the one-link helper: a legal crash may expose the exact
        # two-link source/final pair, which the publisher must finish first.
        _link_publication(bootstrap_authority, row, raw, descriptor_path=None)
        if _regular_bytes(final, mode=0o600) != raw:
            raise ValueError("link transaction final descriptor drift")
        return
    if not _path_present(bootstrap):
        directory_fd = os.open(root, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        try: _write_file_at(directory_fd, bootstrap.name, raw, 0o600)
        finally: os.close(directory_fd)
    _link_publication(bootstrap_authority, row, raw, descriptor_path=None)


def _ensure_secure_dir(path: Path) -> None:
    if path.exists():
        base._secure_directory(path, create=False)
    else:
        path.mkdir(mode=0o700, parents=False)
        os.chmod(path, 0o700)
        base._fsync_directory(path)
        base._fsync_directory(path.parent)
        base._secure_directory(path, create=False)


