def _overlay(relative: str, root: Path | None) -> Path:
    path = (root if root is not None else ROOT) / relative
    if not path.exists():
        raise FileNotFoundError(f"candidate-root input is absent: {relative}")
    return path


def _validate_completion_copy(root: Path, relative: str, expected_sha256: str,
                              expected_names: Sequence[str]) -> dict[str, Any]:
    path = root / relative
    if base.sha_file(path) != expected_sha256:
        raise ValueError(f"reviewed completion digest mismatch: {relative}")
    value = _read_root_json(root, relative)
    entries = value.get("entries")
    if not isinstance(entries, list) or len(entries) != len(expected_names):
        raise ValueError(f"completion entry dimensions drift: {relative}")
    expected_paths = {f"data/msae_independent_measurement_v3/{name}" for name in expected_names}
    if {row.get("path") for row in entries} != expected_paths:
        raise ValueError(f"completion entry path set drift: {relative}")
    for row in entries:
        target = root / row["path"]
        st = target.lstat()
        if (row.get("type") != "regular" or not stat.S_ISREG(st.st_mode)
                or stat.S_ISLNK(st.st_mode) or st.st_size != row.get("size")
                or stat.S_IMODE(st.st_mode) != row.get("mode")
                or base.sha_file(target) != row.get("sha256")):
            raise ValueError(f"completion-bound artifact drift: {row.get('path')}")
    if (value.get("entry_count") != len(entries)
            or value.get("entries_sha256") != base.sha_bytes(base.canonical_bytes(entries))):
        raise ValueError(f"completion entry summary drift: {relative}")
    return value


def _validate_m1_semantics(*, root: Path = ROOT) -> dict[str, Any]:
    prefix = "data/msae_independent_measurement_v3"
    overlap = _read_root_json(root, f"{prefix}/history_overlap.json")
    aliases = _read_root_json(root, f"{prefix}/source_alias_manifest.json")
    fixtures = _read_root_json(root, f"{prefix}/overlap_fixtures.json")
    crosswalk = _read_root_json(root, f"{prefix}/v1_row_crosswalk.json")
    if (overlap.get("schema_version") != "msae_v3_history_overlap_v1"
            or overlap.get("status") != "eligible"
            or overlap.get("blocking_collision_count") != 0
            or overlap.get("blocking_collisions") != []
            or overlap.get("idf_universe_documents") != 24008
            or overlap.get("sealed_payload_content_reads") != 0):
        raise ValueError("M1 overlap semantic gate drift")
    quarantine = overlap.get("quarantine_audit", {})
    if (quarantine.get("content_reads") != 0
            or quarantine.get("blocked_content_open_attempt_count") != 0
            or quarantine.get("before_lstat") != quarantine.get("after_scan_lstat")):
        raise ValueError("M1 quarantine attestation drift")
    if (aliases.get("schema_version") != "msae_v3_source_alias_manifest_v1"
            or aliases.get("selected_count") != 350 or len(aliases.get("entries", [])) != 350):
        raise ValueError("M1 source-alias semantics drift")
    if (fixtures.get("status") != "eligible" or fixtures.get("fixture_count") != 40
            or len(fixtures.get("fixtures", [])) != 40):
        raise ValueError("M1 fixture semantics drift")
    with (root / prefix / "history_census.json").open("rb") as handle:
        census_prefix = handle.read(4096)
    required_census_prefixes = (b'"candidate_pairs":8297', b'"historical_documents":23658',
                                b'"idf_universe_documents":24008')
    if any(item not in census_prefix for item in required_census_prefixes):
        raise ValueError("M1 history census semantics drift")
    rows = crosswalk.get("rows")
    if (crosswalk.get("legacy_status") != "ineligible" or crosswalk.get("legacy_row_count") != 206
            or not isinstance(rows, list) or len(rows) != 206):
        raise ValueError("M1 legacy crosswalk semantics drift")
    return {"overlap_status": "eligible", "blocking_collision_count": 0,
            "historical_documents": 23658, "idf_universe_documents": 24008,
            "source_alias_selected_count": 350, "fixture_count": 40,
            "fixture_status": "eligible", "candidate_pairs": 8297,
            "legacy_crosswalk_rows": 206, "legacy_crosswalk_status": "ineligible",
            "sealed_payload_content_reads": 0}


def _validate_tree_authorization(root: Path) -> dict[str, Any]:
    config_root = root / ACTIVE_CONFIG.relative_to(ROOT)
    config_st = config_root.lstat()
    if (not stat.S_ISDIR(config_st.st_mode) or stat.S_ISLNK(config_st.st_mode)
            or stat.S_IMODE(config_st.st_mode) != 0o700 or config_st.st_uid != os.getuid()):
        raise ValueError("candidate-tree active config directory drift")
    commitment_raw = _regular_bytes(config_root / "authorization_commitment.json", mode=0o644)
    commitment = base.strict_json_loads(commitment_raw.decode("utf-8"))
    if commitment_raw != base.canonical_bytes(commitment):
        raise ValueError("candidate-tree authorization commitment is noncanonical")
    public = _regular_bytes(config_root / "ed25519_public.pem", mode=0o644)
    if (commitment.get("schema_version") != "msae_v3_authorization_commitment_v2"
            or commitment.get("generation") != GENERATION
            or commitment.get("operator_instruction") != OPERATOR_INSTRUCTION
            or commitment.get("operator_instruction_sha256") !=
               base.sha_bytes(OPERATOR_INSTRUCTION.encode("utf-8"))
            or commitment.get("contains_execution_authorization") is not False
            or commitment.get("allowed_scope") != "calibration_replay_only"
            or commitment.get("public_key_sha256") != base.sha_bytes(public)):
        raise ValueError("candidate-tree authorization commitment drift")
    config = _read_root_json(
        root, str((ACTIVE_CONFIG / "protocol.json").relative_to(ROOT)))
    review_gates = config.get("post_m2_runtime", {}).get("review_gates")
    if commitment.get("review_gates") != review_gates:
        raise ValueError("candidate-tree config/commitment review binding mismatch")
    expected_review_gates = _trace_review_gates(
        root, str(review_gates.get("plan_review_sha256", "")),
        str(review_gates.get("pre_capability_review_sha256", "")),
        str(review_gates.get("implementation_review_sha256", "")))
    if review_gates != expected_review_gates:
        raise ValueError("candidate-tree review gate entries drift")
    expected_private = commitment["private_key_binding"]
    try:
        _validate_private_key_lstat_binding(ACTIVE_PRIVATE_KEY, expected_private)
    except ValueError as exc:
        raise ValueError("candidate-tree external private-key binding drift") from exc
    for key, observed in (("nonce_directory", base._directory_binding(ACTIVE_NONCE_DIR)),
                          ("gpu_lock_directory", base._directory_binding(base.GPU_LOCK_DIR))):
        if any(observed[field] != commitment[key][field]
               for field in ("path", "realpath", "device", "inode", "uid", "mode", "nlink")):
            raise ValueError(f"candidate-tree external {key} binding drift")
    return commitment


def _rooted_generic_build_stage_a(root: Path, raw_config: bytes, config_sha: str,
                                  evidence: Mapping[str, Mapping[str, Any]]) -> dict[str, Any]:
    """Execute the generic Stage-A builder and dependency from one candidate tree.

    The generic builder verifies its dependency via its own ``__file__`` and the
    imported dependency's origin.  Loading both copies explicitly prevents a
    module already cached from the live repository from defeating M4's two-tree
    isolation.
    """
    scripts = root / "scripts"
    dependency_path = scripts / "msae_measurement_v2.py"
    builder_path = scripts / "msae_measurement_remediation_v1.py"
    for path in (dependency_path, builder_path):
        st = path.lstat()
        if (not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode)
                or st.st_uid != os.getuid() or st.st_nlink != 1):
            raise ValueError(f"rooted Stage-A module identity drift: {path}")
    previous_dependency = sys.modules.get("msae_measurement_v2")
    module_name = f"_msae_measurement_remediation_rooted_{os.getpid()}_{id(root)}"
    try:
        dependency_spec = continuation.source_only_module_spec(
            "msae_measurement_v2", dependency_path)
        if dependency_spec is None or dependency_spec.loader is None:
            raise ValueError("cannot load rooted generic Stage-A dependency")
        dependency = importlib.util.module_from_spec(dependency_spec)
        sys.modules["msae_measurement_v2"] = dependency
        dependency_spec.loader.exec_module(dependency)
        builder_spec = continuation.source_only_module_spec(module_name, builder_path)
        if builder_spec is None or builder_spec.loader is None:
            raise ValueError("cannot load rooted generic Stage-A builder")
        builder = importlib.util.module_from_spec(builder_spec)
        sys.modules[module_name] = builder
        builder_spec.loader.exec_module(builder)
        return builder.build_stage_a(raw_config, config_sha, evidence)
    finally:
        continuation.sanitize_local_module_search_path(scripts)
        sys.modules.pop(module_name, None)
        if previous_dependency is None:
            sys.modules.pop("msae_measurement_v2", None)
        else:
            sys.modules["msae_measurement_v2"] = previous_dependency


def stage_a_payload(*, overlay_root: Path | None = None) -> dict[str, Any]:
    root = overlay_root if overlay_root is not None else ROOT
    config_path = root / ACTIVE_CONFIG.relative_to(ROOT) / "protocol.json"
    config_raw = config_path.read_bytes()
    config_sha = base.sha_bytes(config_raw)
    config = base.strict_json_loads(config_raw.decode("utf-8"))
    generic_config = generic_config_projection(config)
    generic_config_raw = base.canonical_bytes(generic_config)
    generic_config_sha = base.sha_bytes(generic_config_raw)
    reviewed_m2 = config["post_m2_runtime"]["reviewed_m2_completion_sha256"]
    if reviewed_m2 != M2_REVIEWED_COMPLETION_SHA256:
        raise ValueError("Stage A is not bound to the reviewed M2 completion pin")
    m1_completion = _validate_completion_copy(
        root, "reports/provenance/msae_independent_measurement_v3/m1_completion_manifest.json",
        M1_REVIEWED_COMPLETION_SHA256, base.V3_DATA_PHASE_FILES["M1"])
    m2_completion = _validate_completion_copy(
        root, "reports/provenance/msae_independent_measurement_v3/m2_completion_manifest.json",
        reviewed_m2, base.V3_DATA_PHASE_FILES["M2"])
    m1_semantics = _validate_m1_semantics(root=root)
    m2_semantics = _validate_m2_semantics(root=root)
    if m1_completion.get("success_semantics") != m1_semantics:
        raise ValueError("M1 completion semantics do not close")
    if m2_completion.get("success_semantics") != m2_semantics:
        raise ValueError("M2 completion semantics do not close")
    checkpoints = checkpoint_registry(root=root)
    config_review = config.get("post_m2_runtime", {}).get("review_gates", {})
    expected_config = _protocol_config_payload(
        checkpoints, reviewed_m2,
        plan_review_sha256=str(config_review.get("plan_review_sha256", "")),
        pre_capability_review_sha256=str(
            config_review.get("pre_capability_review_sha256", "")),
        implementation_review_sha256=str(
            config_review.get("implementation_review_sha256", "")),
        root=root)
    if config != expected_config or config_raw != base.canonical_bytes(config):
        raise ValueError("active protocol config does not reproduce")
    _validate_tree_authorization(root)
    registry = base.read_json(_overlay("data/msae_independent_measurement_v3_post_m2_gen9/endpoint_registry.json", overlay_root))
    expected_registry = endpoint_registry()
    validate_endpoint_registry(registry)
    if registry != expected_registry:
        raise ValueError("endpoint registry semantic mismatch")
    closure = base.read_json(_overlay("data/msae_independent_measurement_v3_post_m2_gen9/dependency_closure.json", overlay_root))
    if closure != closure_payload(checkpoints, root=root):
        raise ValueError("dependency closure semantic mismatch")
    environment = base.read_json(_overlay("data/msae_independent_measurement_v3_post_m2_gen9/environment_allowlist.json", overlay_root))
    if environment != environment_payload(closure, root=root):
        raise ValueError("environment allowlist semantic mismatch")
    required = config["stages"]["A"]["required"]
    exact_required = ["candidate_confirmation_source", "immutable_source_revision",
                      "independent_grouping_provenance", "label_support_audit",
                      "construct_inventory", "counterfactual_template_specification",
                      "tolerance_ladder_frozen", "dependency_attestation"]
    if required != exact_required or config["stages"]["A"].get("optional") != []:
        raise ValueError("Stage-A endpoint registry is not exact")
    artifacts = {
        "candidate_confirmation_source": root / "data/msae_independent_measurement_v3/history_overlap.json",
        "immutable_source_revision": root / "data/msae_independent_measurement_v3/source_alias_manifest.json",
        "independent_grouping_provenance": root / "data/msae_independent_measurement_v3/v1_row_crosswalk.json",
        "label_support_audit": root / "data/msae_independent_measurement_v3/support.json",
        "construct_inventory": _overlay("data/msae_independent_measurement_v3_post_m2_gen9/endpoint_registry.json", overlay_root),
        "counterfactual_template_specification": root / "data/msae_independent_measurement_v3/prefix_templates.json",
        "tolerance_ladder_frozen": config_path,
        "dependency_attestation": _overlay("data/msae_independent_measurement_v3_post_m2_gen9/dependency_closure.json", overlay_root),
    }
    def canonical_artifact_path(path: Path) -> str:
        if not path.is_relative_to(root):
            raise ValueError(f"Stage-A artifact escapes candidate root: {path}")
        return path.relative_to(root).as_posix()

    evidence = {name: {"schema_version": "msae_endpoint_evidence_v1",
                       "protocol_config_sha256": generic_config_sha, "endpoint_name": name,
                       "category": "stage_a", "status": "eligible", "reasons": [],
                       "evidence_artifact_sha256": base.sha_file(path),
                       "observed_value": {"artifact_path": canonical_artifact_path(path),
                                          "artifact_sha256": base.sha_file(path)}}
                for name, path in artifacts.items() if name != "dependency_attestation"}
    generic = _rooted_generic_build_stage_a(root, generic_config_raw,
                                            generic_config_sha, evidence)
    typed = {relative: base.sha_file(_overlay(relative, overlay_root))
             for relative in _typed_artifact_paths()}
    scientific = {"m1_completion_sha256": M1_REVIEWED_COMPLETION_SHA256,
                  "m2_completion_sha256": reviewed_m2,
                  "gen4_terminal_sha256": base.sha_file(
                      root / FAILED_GEN4_RECORD.relative_to(ROOT)),
                  "gen3_terminal_sha256": base.sha_file(
                      root / FAILED_GEN3_RECORD.relative_to(ROOT)),
                  "gen2_failure_sha256": base.sha_file(
                      root / FAILED_GEN2_RECORD.relative_to(ROOT)),
                  "gen9_setup_manifest_sha256": base.sha_file(
                      root / SETUP_MANIFEST.relative_to(ROOT)),
                  "gen9_implementation_review_sha256": base.sha_file(
                      root / IMPLEMENTATION_REVIEW.relative_to(ROOT)),
                  "gen9_post_m3_review_sha256": base.sha_file(
                      root / POST_M3_REVIEW.relative_to(ROOT)),
                  "endpoint_registry_payload_sha256": base.sha_bytes(base.canonical_bytes(registry)),
                  "checkpoint_registry_payload_sha256": base.sha_bytes(base.canonical_bytes(checkpoints)),
                  "closure_payload_sha256": base.sha_bytes(base.canonical_bytes(closure)),
                  "environment_payload_sha256": base.sha_bytes(base.canonical_bytes(environment)),
                  "generic_protocol_config_sha256": generic_config_sha,
                  "m1_semantics": m1_semantics, "m2_semantics": m2_semantics,
                  "authorization_commitment_sha256": base.sha_file(
                      root / ACTIVE_CONFIG.relative_to(ROOT) / "authorization_commitment.json")}
    ready = bool(generic.get("stage_ready") is True)
    return {"schema_version": "msae_exposed_source_stage_a_v4", "protocol_id": PROTOCOL,
            "claim_scope": "exposed_source_technical_measurement_replication",
            "confirmation_partition_status": "replacement_required_not_run",
            "protocol_config_sha256": config_sha, "typed_artifact_sha256": typed,
            "typed_artifact_set_sha256": base.sha_bytes(base.canonical_bytes(typed)),
            "scientific_gate_attestations": scientific, "base_stage_a": generic,
            "stage_ready": ready, "blockers": [] if ready else ["base_contract"]}


def validate_stage_a() -> dict[str, Any]:
    path = ACTIVE_PROV / "stage_a.json"
    observed = base.read_json(path)
    expected = stage_a_payload()
    if observed != expected or path.read_bytes() != base.canonical_bytes(observed):
        raise ValueError("post-M2 Stage A does not reproduce")
    if observed.get("stage_ready") is not True:
        raise ValueError("Stage A is not ready")
    return observed


M4_NEW = ("data/msae_independent_measurement_v3_post_m2_gen9/dependency_closure.json",
          "data/msae_independent_measurement_v3_post_m2_gen9/endpoint_registry.json",
          "data/msae_independent_measurement_v3_post_m2_gen9/environment_allowlist.json",
          "reports/provenance/msae_independent_measurement_v3_post_m2_gen9/stage_a.json",
          "reports/provenance/msae_independent_measurement_v3_post_m2_gen9/status.json",
          "reports/provenance/msae_independent_measurement_v3_post_m2_gen9/prescore_candidate_manifest.json")


def _candidate_relatives(*, include_m4: bool, root: Path = ROOT,
                         checkpoints: Sequence[Mapping[str, Any]] | None = None) -> list[str]:
    bound_checkpoints = checkpoint_registry(root=root) if checkpoints is None else list(checkpoints)
    paths = _closure_local_relative_names(bound_checkpoints, root=root)
    if include_m4:
        paths = [*paths, *M4_NEW[:-1]]
    if len(paths) != len(set(paths)):
        raise AssertionError("duplicate candidate relative")
    return sorted(paths, key=lambda value: value.encode("utf-8"))


def _sparse_copy(source: Path, destination: Path, mode: int) -> None:
    source_fd = os.open(source, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    destination_fd = os.open(destination, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                             mode)
    try:
        size = os.fstat(source_fd).st_size
        os.ftruncate(destination_fd, size)
        offset = 0
        while offset < size:
            try:
                data = os.lseek(source_fd, offset, os.SEEK_DATA)
            except OSError as error:
                if error.errno == errno.ENXIO:  # the remainder is a hole.
                    break
                raise
            hole = os.lseek(source_fd, data, os.SEEK_HOLE)
            position = data
            while position < hole:
                os.lseek(source_fd, position, os.SEEK_SET)
                chunk = os.read(source_fd, min(8 << 20, hole - position))
                if not chunk:
                    raise IOError(f"short sparse-copy read: {source}")
                os.lseek(destination_fd, position, os.SEEK_SET)
                written = 0
                while written < len(chunk):
                    count = os.write(destination_fd, chunk[written:])
                    if count <= 0:
                        raise IOError(f"short sparse-copy write: {destination}")
                    written += count
                position += len(chunk)
            offset = hole
        os.fchmod(destination_fd, mode)
        os.fsync(destination_fd)
    finally:
        os.close(source_fd)
        os.close(destination_fd)


def _m4_input_relatives() -> list[str]:
    checkpoints = checkpoint_registry()
    return sorted(set(_candidate_relatives(include_m4=False, root=ROOT, checkpoints=checkpoints)) |
                  set(_closure_local_relatives(checkpoints, root=ROOT)),
                  key=lambda value: value.encode("utf-8"))


M4_BUILD_DESCRIPTOR_NAME = ".build_descriptor.json"


def _m4_build_descriptor(
    *, role: str, post_m3_review_sha256: str,
    input_snapshot_sha256: str, candidate_paths: Sequence[str],
) -> dict[str, Any]:
    if role not in {"primary", "rebuild"}:
        raise ValueError(f"invalid M4 tree role: {role}")
    base.validate_sha256(post_m3_review_sha256, "post-M3 review SHA-256")
    base.validate_sha256(input_snapshot_sha256, "M4 input snapshot SHA-256")
    paths = list(candidate_paths)
    if paths != sorted(set(paths), key=lambda value: value.encode("utf-8")):
        raise ValueError("M4 build descriptor candidate paths are not canonical")
    return {
        "schema_version": "msae_v3_gen9_m4_build_descriptor_v1",
        "protocol_id": PROTOCOL,
        "generation": GENERATION,
        "tree_role": role,
        "post_m3_review_sha256": post_m3_review_sha256,
        "input_snapshot_sha256": input_snapshot_sha256,
        "candidate_paths": paths,
        "candidate_path_set_sha256": base.sha_bytes(base.canonical_bytes(paths)),
    }


def _copy_complete_candidate_tree(
    root: Path, *, build_descriptor: Mapping[str, Any],
) -> None:
    os.mkdir(root, 0o700)
    os.chmod(root, 0o700)
    base._fsync_directory(root)
    base._fsync_directory(root.parent)
    _atomic_publish(
        root / M4_BUILD_DESCRIPTOR_NAME,
        base.canonical_bytes(dict(build_descriptor)), 0o600)
    def ensure_parent(relative: str) -> None:
        current = root
        source_current = ROOT
        for component in Path(relative).parent.parts:
            current = current / component
            source_current = source_current / component
            source_dir_st = source_current.lstat()
            if not stat.S_ISDIR(source_dir_st.st_mode) or stat.S_ISLNK(source_dir_st.st_mode):
                raise ValueError(f"candidate source ancestor is not a directory: {source_current}")
            if not current.exists():
                current.mkdir(mode=stat.S_IMODE(source_dir_st.st_mode))
                os.chmod(current, stat.S_IMODE(source_dir_st.st_mode))
            else:
                current_st = current.lstat()
                if (not stat.S_ISDIR(current_st.st_mode) or stat.S_ISLNK(current_st.st_mode)
                        or stat.S_IMODE(current_st.st_mode) != stat.S_IMODE(source_dir_st.st_mode)):
                    raise ValueError(f"candidate-tree ancestor drift: {current}")

    for relative in _m4_input_relatives():
        source = ROOT / relative
        destination = root / relative
        st = source.lstat()
        if not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode):
            raise ValueError(f"non-regular candidate source: {relative}")
        ensure_parent(relative)
        _sparse_copy(source, destination, stat.S_IMODE(st.st_mode))
    # M4 output files do not exist yet, but their live parent directories do.
    # Seed those ancestors so the two trees and installed projection bind the
    # same directory modes (not mkdir/umask defaults).
    for relative in M4_NEW:
        ensure_parent(relative)


def _full_tree_manifest(root: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    root_st = root.lstat()
    rows.append({"path": ".", "type": "directory", "mode": stat.S_IMODE(root_st.st_mode),
                 "uid": root_st.st_uid, "gid": root_st.st_gid,
                 "nlink": root_st.st_nlink})
    for path in sorted(root.rglob("*"), key=lambda item: item.relative_to(root).as_posix().encode("utf-8")):
        st = path.lstat()
        relative = path.relative_to(root).as_posix()
        # The two reviewed scratch trees intentionally bind different roles in
        # their durable descriptors.  Compare the complete candidate contents,
        # while validating the descriptors separately at their exact paths.
        if relative == M4_BUILD_DESCRIPTOR_NAME:
            continue
        if stat.S_ISDIR(st.st_mode) and not stat.S_ISLNK(st.st_mode):
            rows.append({"path": relative, "type": "directory", "mode": stat.S_IMODE(st.st_mode),
                         "uid": st.st_uid, "gid": st.st_gid,
                         "nlink": st.st_nlink})
        elif stat.S_ISREG(st.st_mode) and not stat.S_ISLNK(st.st_mode):
            rows.append({"path": relative, "type": "regular", "mode": stat.S_IMODE(st.st_mode),
                         "uid": st.st_uid, "gid": st.st_gid, "nlink": st.st_nlink,
                         "size": st.st_size, "sha256": base.sha_file(path)})
        else:
            raise ValueError(f"non-regular object in complete M4 tree: {relative}")
    return rows


def _tree_entries(root: Path, relatives: Sequence[str]) -> list[dict[str, Any]]:
    entries = []
    for relative in relatives:
        entry = _regular_entry(root / relative, root=root)
        entry["path"] = relative
        entries.append(entry)
    return entries


def _candidate_directory_relatives(relatives: Iterable[str]) -> list[str]:
    result: set[str] = set()
    for relative in relatives:
        parent = Path(relative).parent
        while parent != Path("."):
            result.add(parent.as_posix())
            parent = parent.parent
    return sorted(result, key=lambda value: value.encode("utf-8"))


def _directory_entries(root: Path, relatives: Iterable[str]) -> list[dict[str, Any]]:
    rows = []
    for relative in _candidate_directory_relatives(relatives):
        path = root / relative
        st = path.lstat()
        if not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode):
            raise ValueError(f"candidate ancestor is not a real directory: {path}")
        rows.append({"path": relative, "type": "directory", "mode": stat.S_IMODE(st.st_mode),
                     "uid": st.st_uid, "gid": st.st_gid,
                     "nlink": st.st_nlink})
    return rows


def _git_status() -> list[str]:
    raw = subprocess.check_output(["/usr/bin/git", "status", "--porcelain=v2", "--untracked-files=all"],
                                  cwd=ROOT, text=True)
    return raw.splitlines()


def _status_path(line: str) -> str:
    if line.startswith("? ") or line.startswith("! "):
        return line[2:]
    # Porcelain-v2 ordinary records use eight fixed metadata fields then path.
    parts = line.split(" ", 8)
    if len(parts) != 9:
        raise ValueError(f"unsupported porcelain-v2 status record: {line!r}")
    return parts[8]


def _classify_repository_status(lines: Sequence[str], candidate_paths: set[str],
                                *, root: Path = ROOT) -> list[dict[str, str]]:
    data_root = root / V3_DATA.relative_to(ROOT)
    protected = base.read_json(data_root / "protected_v1_manifest.json")["entries"]
    protected += base.read_json(data_root / "protected_v2_manifest.json")["entries"]
    protected_paths = {row["path"] for row in protected}
    baseline_paths = {row["path"] for row in
                      base.read_json(data_root / "data_baseline_manifest.json")["entries"]}
    rows = []
    for line in lines:
        path = _status_path(line)
        if path in candidate_paths or any(item.startswith(path.rstrip("/") + "/") for item in candidate_paths):
            classification = "candidate"
        elif path in protected_paths or path in baseline_paths or any(
                item.startswith(path.rstrip("/") + "/") for item in protected_paths | baseline_paths):
            classification = "protected_baseline"
        else:
            raise ValueError(f"unclassified repository status path: {path}")
        rows.append({"line": line, "path_projection": path, "classification": classification})
    return rows


def candidate_manifest_payload(tree_root: Path, repository_status: Sequence[str],
                               directory_projection: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    tree_checkpoints = checkpoint_registry(root=tree_root)
    relatives = _candidate_relatives(include_m4=True, root=tree_root,
                                     checkpoints=tree_checkpoints)
    entries = _tree_entries(tree_root, relatives)
    directories = [dict(row) for row in directory_projection]
    if [row["path"] for row in directories] != _candidate_directory_relatives(relatives):
        raise ValueError("supplied live directory projection path set mismatch")
    # The sparse build has fewer siblings, so nlink intentionally differs.
    # Its type/mode/owner must still match the separately frozen live row.
    tree_directories = {row["path"]: row for row in _directory_entries(tree_root, relatives)}
    for row in directories:
        tree_row = tree_directories[row["path"]]
        if any(tree_row[key] != row[key] for key in ("path", "type", "mode", "uid")):
            raise ValueError(f"sparse-tree directory metadata drift: {row['path']}")
    classifications = _classify_repository_status(repository_status, set(relatives) | {M4_NEW[-1]},
                                                    root=tree_root)
    stage_sha = base.sha_file(tree_root / M4_NEW[3])
    closure_sha = base.sha_file(tree_root / M4_NEW[0])
    commitment = _read_root_json(tree_root, str((ACTIVE_CONFIG / "authorization_commitment.json").relative_to(ROOT)))
    return {"schema_version": "msae_v3_prescore_candidate_manifest_v3", "protocol_id": PROTOCOL,
            "generation": GENERATION,
            "candidate_root_realpath": str(ROOT.resolve(strict=True)),
            "candidate_files": entries,
            "candidate_directories": directories,
            "candidate_directory_tree_sha256": base.sha_bytes(base.canonical_bytes(directories)),
            "candidate_file_paths": relatives,
            "candidate_tree_sha256": base.sha_bytes(base.canonical_bytes(entries)),
            "dependency_closure_sha256": closure_sha, "stage_a_sha256": stage_sha,
            "repository_status": list(repository_status),
            "repository_status_classification": classifications,
            "required_absent_post_review_outputs": [str(PRESCORE_REVIEW.relative_to(ROOT)), ACTIVE_RUN_REL],
            "required_external_state": {
                "private_key": commitment["private_key_binding"],
                "nonce_directory": commitment["nonce_directory"],
                "gpu_lock_directory": base._directory_binding(base.GPU_LOCK_DIR),
                "required_empty_nonce_directory": True,
                "required_absent_build_roots": [str(M4_PRIMARY), str(M4_REBUILD)],
                "required_absent_short_socket_paths": [
                    str(_tmux_paths(stage_sha)[0]), str(_tmux_paths(stage_sha)[1])],
                "short_socket_family_projection": {
                    "tmp_parent_binding": _tmp_parent_projection_binding(),
                    "entries": _short_socket_family_projection()},
                "required_absent_prescore_evidence_rule": {
                    "schema_version": "msae_v3_manifest_digest_evidence_paths_v1",
                    "check_template": ("/tmp/msae_independent_measurement_v3_post_m2_gen9_"
                                       "{manifest_sha256}.prescore.check.json"),
                    "trace_template": ("/tmp/msae_independent_measurement_v3_post_m2_gen9_"
                                       "{manifest_sha256}.prescore.trace.log"),
                    "manifest_sha256_pattern": "[0-9a-f]{64}"}},
            "quarantined_entries": [base._quarantine_entry(rel) for rel in sorted(base.QUARANTINED)],
            "sealed_payload_content_reads": 0, "self_hash_excluded": True}


def _anticipated_status() -> list[str]:
    current = _git_status()
    transaction_relative = (M4_TRANSACTION.relative_to(ROOT).as_posix()
                            if M4_TRANSACTION.is_relative_to(ROOT) else None)
    output_paths = set(M4_NEW)
    current = [line for line in current
               if _status_path(line) not in output_paths
               and not (transaction_relative is not None
                        and (_status_path(line) == transaction_relative
                             or _status_path(line).startswith(transaction_relative + "/")))]
    tracked = [line for line in current if not line.startswith("? ")]
    untracked = {line[2:]: line for line in current if line.startswith("? ")}
    # ``data/`` is ignored by the repository.  Git will not report the three
    # data products after installation, so the pre-install projection must not
    # synthesize status rows that the post-install verifier can never observe.
    # The two provenance outputs are unignored and the manifest excludes only
    # itself to avoid a self-hash cycle.
    for relative in M4_NEW[3:-1]:
        untracked.setdefault(relative, f"? {relative}")
    return [*tracked, *(untracked[path] for path in sorted(untracked, key=lambda value: value.encode("utf-8")))]


def _historical_manifest_directory_projection(
    current: Sequence[Mapping[str, Any]], *, recovery: bool,
) -> list[dict[str, Any]]:
    """Remove only the validated transaction-subdir nlink from M4 evidence."""
    rows = [dict(row) for row in current]
    if recovery and _path_present(M4_TRANSACTION):
        parent = M4_TRANSACTION.parent.relative_to(ROOT).as_posix()
        matches = [row for row in rows if row.get("path") == parent]
        if len(matches) != 1 or matches[0].get("nlink", 0) < 3:
            raise ValueError("M4 recovery provenance-directory projection drift")
        matches[0]["nlink"] -= 1
    return rows


def _materialize_complete_m4(root: Path, checkpoints: list[dict[str, Any]],
                             anticipated_status: list[str],
                             directory_projection: Sequence[Mapping[str, Any]],
                             *, build_descriptor: Mapping[str, Any]) -> dict[str, Any]:
    _copy_complete_candidate_tree(root, build_descriptor=build_descriptor)
    tree_checkpoints = checkpoint_registry(root=root)
    if tree_checkpoints != checkpoints:
        raise ValueError("M4 checkpoint reconstruction differs from live frozen inputs")
    closure = closure_payload(tree_checkpoints, root=root)
    registry = endpoint_registry()
    environment = environment_payload(closure, root=root)
    for relative, value in zip(M4_NEW[:3], (closure, registry, environment)):
        base.write_once(root / relative, base.canonical_bytes(value), 0o644)
    stage = stage_a_payload(overlay_root=root)
    base.write_once(root / M4_NEW[3], base.canonical_bytes(stage), 0o644)
    status_payload = {"schema_version": "msae_v3_prescore_status_v2", "protocol_id": PROTOCOL,
                      "status": "ready_prescore_review" if stage["stage_ready"] else "blocked_prescore",
                      "stage_a_ready": stage["stage_ready"],
                      "stage_a_sha256": base.sha_file(root / M4_NEW[3]),
                      "stage_b": "not_run", "stage_c": "not_run",
                      "confirmation_partition": "replacement_required"}
    base.write_once(root / M4_NEW[4], base.canonical_bytes(status_payload), 0o644)
    manifest = candidate_manifest_payload(root, anticipated_status, directory_projection)
    manifest_raw = base.canonical_bytes(manifest)
    manifest_sha = base.sha_bytes(manifest_raw)
    if any(_path_present(path) for path in _prescore_evidence_paths(manifest_sha)):
        raise FileExistsError("digest-derived prescore evidence exists before M4")
    base.write_once(root / M4_NEW[5], manifest_raw, 0o644)
    return stage


def _install_transaction(
    root: Path, relatives: Sequence[str], payloads: Mapping[str, bytes],
    schema: str, *, post_m3_review_sha256: str | None = None,
    input_snapshot_sha256: str | None = None,
) -> None:
    """Install the six M4 products through the NFS link transaction."""
    ordered = list(relatives)
    if (ordered != list(M4_NEW) or len(ordered) != 6
            or len(set(ordered)) != 6 or set(payloads) != set(ordered)):
        raise ValueError("M4 transaction payload set/order mismatch")
    review_sha = post_m3_review_sha256 or ("0" * 64)
    snapshot_sha = input_snapshot_sha256 or ("0" * 64)
    base.validate_sha256(review_sha, "M4 post-M3 review SHA-256")
    base.validate_sha256(snapshot_sha, "M4 input snapshot SHA-256")
    authority = {
        "schema": schema,
        "post_m3_review_sha256": review_sha,
        "input_snapshot_sha256": snapshot_sha,
        "destinations": ordered,
        "payload_sha256": {
            relative: base.sha_bytes(payloads[relative]) for relative in ordered},
        "candidate_manifest_sha256": base.sha_bytes(payloads[ordered[-1]]),
    }
    authority_sha = base.sha_bytes(base.canonical_bytes(authority))
    rows = [
        _publication_row(
            index, root, f"{index:02d}.payload",
            (ROOT / relative).parent, (ROOT / relative).name,
            payloads[relative], 0o644, f"m4_{Path(relative).name}")
        for index, relative in enumerate(ordered)
    ]
    destinations = [ROOT / relative for relative in ordered]
    states = {relative: _path_present(path)
              for relative, path in zip(ordered, destinations)}
    _require_ordered_output_prefix(ordered, states)
    if not _path_present(root):
        if all(states.values()):
            for relative, destination in zip(ordered, destinations):
                if _regular_bytes(destination, mode=0o644) != payloads[relative]:
                    raise ValueError(f"M4 installed output drift: {relative}")
            return
        if any(states.values()):
            raise ValueError("M4 transaction missing with a strict output prefix")
        _ensure_secure_dir(root)
    else:
        root_st = root.lstat()
        if (not stat.S_ISDIR(root_st.st_mode) or stat.S_ISLNK(root_st.st_mode)
                or root_st.st_uid != os.getuid()
                or stat.S_IMODE(root_st.st_mode) != 0o700):
            raise ValueError("M4 transaction root identity drift")

    allowed_transaction_names = {
        "transaction.json", ".transaction.json.bootstrap",
        *(f"{index:02d}.payload" for index in range(6)),
        *(f".{Path(relative).name}.attempt-{attempt}"
          for relative in ordered for attempt in range(1, 4)),
        *(f".transaction.json.attempt-{attempt}" for attempt in range(1, 4)),
    }
    observed_transaction_names = {entry.name for entry in os.scandir(root)}
    if observed_transaction_names - allowed_transaction_names:
        raise ValueError(
            f"M4 transaction has unbound extras: "
            f"{observed_transaction_names - allowed_transaction_names}")

    descriptor_path = root / "transaction.json"
    bootstrap_path = root / ".transaction.json.bootstrap"
    if _path_present(descriptor_path) or _path_present(bootstrap_path):
        authority_path = descriptor_path if _path_present(descriptor_path) else bootstrap_path
        raw = _regular_bytes(authority_path, mode=0o600)
        descriptor = base.strict_json_loads(raw.decode("utf-8"))
        if raw != base.canonical_bytes(descriptor):
            raise ValueError("M4 transaction descriptor is noncanonical")
        _validate_link_transaction_descriptor(
            descriptor, kind="m4", authority_sha256=authority_sha,
            publications=rows, maximum_seconds=21600)
        if descriptor["sealed_random_payloads"] != {}:
            raise ValueError("M4 transaction sealed-payload set drift")
    else:
        descriptor = _link_transaction_payload(
            kind="m4", authority_sha256=authority_sha,
            publications=rows, maximum_seconds=21600)
    _validate_link_transaction_descriptor(
        descriptor, kind="m4", authority_sha256=authority_sha,
        publications=rows, maximum_seconds=21600)
    _bootstrap_link_transaction(root, descriptor)
    for row, relative in zip(rows, ordered):
        _link_publication(
            descriptor, row, payloads[relative], descriptor_path=descriptor_path)

    for relative, destination in zip(ordered, destinations):
        if _regular_bytes(destination, mode=0o644) != payloads[relative]:
            raise ValueError(f"M4 post-install output drift: {relative}")
    observed = {entry.name for entry in os.scandir(root)}
    if observed != {"transaction.json"}:
        raise ValueError(f"M4 transaction cleanup has extras: {observed}")
    descriptor_path.unlink()
    base._fsync_directory(root)
    root.rmdir()
    base._fsync_directory(root.parent)

def _compare_complete_m4_trees(left_root: Path, right_root: Path,
                               left_stage: Mapping[str, Any],
                               right_stage: Mapping[str, Any],
                               *, left_descriptor: Mapping[str, Any] | None = None,
                               right_descriptor: Mapping[str, Any] | None = None,
                               ) -> dict[str, bytes]:
    for root, expected in ((left_root, left_descriptor),
                           (right_root, right_descriptor)):
        descriptor_path = root / M4_BUILD_DESCRIPTOR_NAME
        if expected is not None:
            if (_regular_bytes(descriptor_path, mode=0o600) !=
                    base.canonical_bytes(dict(expected))):
                raise ValueError(f"M4 build descriptor drift: {root}")
    if (_full_tree_manifest(left_root) != _full_tree_manifest(right_root)
            or left_stage != right_stage):
        raise ValueError("independent complete M4 trees differ")
    payloads: dict[str, bytes] = {}
    for relative in M4_NEW:
        left = _regular_bytes(left_root / relative, mode=0o644)
        right = _regular_bytes(right_root / relative, mode=0o644)
        if left != right:
            raise ValueError(f"independent M4 bytes differ: {relative}")
        payloads[relative] = left
    return payloads


def _verify_live_m4_inputs(snapshot: Sequence[Mapping[str, Any]],
                           initial_status: Sequence[str],
                           directory_projection: Sequence[Mapping[str, Any]]) -> None:
    relatives = [str(row["path"]) for row in snapshot]
    if _tree_entries(ROOT, relatives) != list(snapshot):
        raise ValueError("live M4 inputs drifted after candidate-tree snapshot")
    if _git_status() != list(initial_status):
        raise ValueError("repository status drifted after candidate-tree snapshot")
    if _directory_entries(ROOT, _candidate_relatives(include_m4=True)) != list(directory_projection):
        raise ValueError("live candidate directory projection drifted during M4")
    base.verify_baseline_projection("M2")
    base.verify_protected_v1()
    base.verify_protected_v2()
    base.validate_source_exposure()


def _quarantine_metadata_rows() -> list[dict[str, Any]]:
    """Revalidate sealed identities without opening any sealed payload."""
    rows = [base._quarantine_entry(relative) for relative in sorted(base.QUARANTINED)]
    if any(row.get("nlink") != 1 for row in rows):
        # nlink==1 is also the exhaustive same-inode hard-link-alias proof.
        raise ValueError("quarantined payload has a same-inode alias")
    return rows


@contextlib.contextmanager
def quarantine_guard() -> Iterable[dict[str, Any]]:
    """Install the sealed-content tripwire and prove stable metadata around work."""
    before = _quarantine_metadata_rows()
    try:
        with base.quarantine_open_tripwire() as state:
            if state.get("before_lstat") != before:
                raise ValueError("quarantine tripwire initial metadata mismatch")
            try:
                yield state
            finally:
                if state.get("blocked_content_open_attempts"):
                    raise AssertionError(
                        "quarantine tripwire recorded a sealed content-open attempt")
    finally:
        after = _quarantine_metadata_rows()
        if after != before:
            raise ValueError(
                "quarantined payload metadata changed during guarded operation")


def _post_m3_forbidden_tmp_patterns() -> tuple[str, ...]:
    return (
        "msae_independent_measurement_v3_post_m2_gen9_*.prescore.check.json",
        "msae_independent_measurement_v3_post_m2_gen9_*.prescore.trace.log",
        "msae_independent_measurement_v3_post_m2_gen9_*.sock",
        "m9t_*", "m9b_*", "m9p_*", "m9x_*", "m9a_*", "m9c_*", "m9s_*",
        # Immutable gen2 uses the older undifferentiated v3 prefix.
        "msae_independent_measurement_v3_*.prescore.check.json",
        "msae_independent_measurement_v3_*.prescore.trace.log",
        "msae_independent_measurement_v3_*.sock",
    )


def _m4_recovery_present() -> bool:
    return any(_path_present(path) for path in (
        M4_TRANSACTION, M4_PRIMARY, M4_REBUILD,
        *(ROOT / relative for relative in M4_NEW),
    ))


def _require_ordered_output_prefix(
    relatives: Sequence[str], states: Mapping[str, bool],
) -> None:
    """Reject a crash state impossible for the registered ordered installer."""
    seen_absent = False
    for relative in relatives:
        present = states.get(relative) is True
        if seen_absent and present:
            raise ValueError("installed output set is not an ordered prefix")
        if not present:
            seen_absent = True


def _validate_m4_tree_for_cleanup(
    root: Path, *, expected_descriptor: Mapping[str, Any] | None = None,
) -> None:
    """Validate a dedicated crash-left sparse tree before recursive removal."""
    root_st = root.lstat()
    if (not stat.S_ISDIR(root_st.st_mode) or stat.S_ISLNK(root_st.st_mode)
            or stat.S_IMODE(root_st.st_mode) != 0o700
            or root_st.st_uid != os.getuid()):
        raise ValueError(f"invalid M4 recovery tree root: {root}")
    allowed_files = set(_m4_input_relatives()) | set(M4_NEW) | {
        M4_BUILD_DESCRIPTOR_NAME,
        f".{M4_BUILD_DESCRIPTOR_NAME}.partial",
    }
    allowed_directories = set(_candidate_directory_relatives(allowed_files))
    for path in sorted(root.rglob("*"), key=lambda item: item.relative_to(root).as_posix()):
        st = path.lstat()
        relative = path.relative_to(root).as_posix()
        if stat.S_ISLNK(st.st_mode) or st.st_uid != os.getuid():
            raise ValueError(f"unsafe M4 recovery-tree entry: {path}")
        if stat.S_ISDIR(st.st_mode):
            if relative not in allowed_directories:
                raise ValueError(f"unregistered M4 recovery-tree directory: {relative}")
        elif stat.S_ISREG(st.st_mode):
            if relative not in allowed_files or st.st_nlink != 1:
                raise ValueError(f"unregistered M4 recovery-tree file: {relative}")
        else:
            raise ValueError(f"non-file M4 recovery-tree object: {relative}")
    descriptor_path = root / M4_BUILD_DESCRIPTOR_NAME
    if expected_descriptor is not None:
        expected_raw = base.canonical_bytes(dict(expected_descriptor))
        descriptor_partial = descriptor_path.with_name(
            f".{descriptor_path.name}.partial")
        if _path_present(descriptor_path):
            if (_regular_bytes(descriptor_path, mode=0o600) != expected_raw
                    or _path_present(descriptor_partial)):
                raise ValueError(f"M4 recovery build descriptor drift: {root}")
        elif _path_present(descriptor_partial):
            observed = _regular_bytes(descriptor_partial, mode=0o600)
            if expected_raw[:len(observed)] != observed:
                raise ValueError(f"M4 recovery descriptor partial drift: {root}")
        elif any(os.scandir(root)):
            raise ValueError(f"M4 recovery tree lacks its build descriptor: {root}")


def _validate_m4_recovery_artifacts() -> None:
    """Validate crash-left M4 objects without trusting their content bytes."""
    for path in (M4_PRIMARY, M4_REBUILD, M4_TRANSACTION):
        if not _path_present(path):
            continue
        st = path.lstat()
        if (not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode)
                or stat.S_IMODE(st.st_mode) != 0o700 or st.st_uid != os.getuid()):
            raise ValueError(f"invalid M4 recovery directory: {path}")
    if _path_present(M4_TRANSACTION):
        allowed = {"transaction.json", ".transaction.json.bootstrap"} | {
            f"{index:02d}.payload" for index in range(len(M4_NEW))
        } | {
            f".{Path(relative).name}.attempt-{attempt}"
            for relative in M4_NEW for attempt in range(1, 4)
        } | {
            f".transaction.json.attempt-{attempt}" for attempt in range(1, 4)
        }
        observed = {entry.name for entry in os.scandir(M4_TRANSACTION)}
        if not observed <= allowed:
            raise ValueError(f"undeclared M4 recovery transaction entries: {observed - allowed}")
        descriptor_names = observed & {
            "transaction.json", ".transaction.json.bootstrap"}
        if not descriptor_names and observed:
            raise ValueError("M4 recovery transaction lacks descriptor authority")
        transaction_fd = os.open(
            M4_TRANSACTION, os.O_RDONLY | os.O_DIRECTORY |
            os.O_NOFOLLOW | os.O_CLOEXEC)
        try:
            for name in observed:
                path = M4_TRANSACTION / name
                st = path.lstat()
                if name.startswith(".") and ".attempt-" in name:
                    if (not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode)
                            or st.st_uid != os.getuid()
                            or stat.S_IMODE(st.st_mode) != 0o700
                            or any(os.scandir(path))):
                        raise ValueError("unsafe M4 recovery attempt marker")
                else:
                    destination: Path | None = None
                    if re.fullmatch(r"[0-5][0-9]?\.payload", name):
                        index = int(name.split(".", 1)[0])
                        if index < len(M4_NEW):
                            destination = ROOT / M4_NEW[index]
                    has_linked_destination = (
                        destination is not None and _path_present(destination))
                    expected_nlink = (2 if (
                        (len(descriptor_names) == 2 and name in descriptor_names)
                        or has_linked_destination) else 1)
                    expected_mode = 0o600 if name in descriptor_names else 0o644
                    source_raw, source_st = _file_at_bytes(
                        transaction_fd, name, mode=expected_mode,
                        nlink=expected_nlink)
                    if has_linked_destination and destination is not None:
                        destination_raw = _regular_bytes(destination, mode=0o644)
                        destination_st = destination.lstat()
                        if (source_raw != destination_raw
                                or (source_st.st_dev, source_st.st_ino)
                                   != (destination_st.st_dev,
                                       destination_st.st_ino)):
                            raise ValueError("M4 recovery exact-pair drift")
        finally:
            os.close(transaction_fd)
        if len(descriptor_names) == 2:
            bootstrap_st = (M4_TRANSACTION / ".transaction.json.bootstrap").lstat()
            final_st = (M4_TRANSACTION / "transaction.json").lstat()
            if ((bootstrap_st.st_dev, bootstrap_st.st_ino)
                    != (final_st.st_dev, final_st.st_ino)):
                raise ValueError("M4 descriptor bootstrap pair drift")
    output_states = {relative: _path_present(ROOT / relative) for relative in M4_NEW}
    _require_ordered_output_prefix(M4_NEW, output_states)
    for relative in M4_NEW:
        path = ROOT / relative
        if output_states[relative]:
            _regular_bytes(path, mode=0o644)


def _post_m3_state_binding(*, allow_m4_recovery: bool = False) -> dict[str, Any]:
    """Reconstruct the exact post-M3/pre-M4 review subject and absence set."""
    _validate_gen3_review_namespace("post_m3")
    # The create-once setup already verified public/private agreement.  This
    # independent post-M3 subject deliberately revalidates only the committed
    # private-key lstat identity; the private key's content remains unread.
    _verify_existing_authorization_state(verify_private_content=False)
    _validate_gen2_terminal_namespace(require_failure=True)
    _verify_live_cpu_no_model_trace()
    _verify_setup_manifest()
    config_names = {"protocol.json", "authorization_commitment.json",
                    "ed25519_public.pem", "cpu_no_model_public_entry_trace.json"}
    _exact_directory_entries(ACTIVE_CONFIG, config_names, mode=0o700)
    for name in sorted(config_names):
        _regular_bytes(ACTIVE_CONFIG / name, mode=0o644)
    if allow_m4_recovery:
        _validate_m4_recovery_artifacts()
    elif _m4_recovery_present():
        raise ValueError("post-M3 subject has crash-left M4 recovery artifacts")
    prov_children = {FAILED_GEN6_RECORD.name, FAILED_GEN5_RECORD.name,
                     FAILED_GEN4_RECORD.name,
                     FAILED_GEN3_RECORD.name, FAILED_GEN2_RECORD.name,
                     SETUP_MANIFEST.name} | {
        Path(relative).name for relative in M4_NEW[3:]
        if _path_present(ROOT / relative)
    }
    if _path_present(M4_TRANSACTION):
        prov_children.add(M4_TRANSACTION.name)
    data_children = {
        Path(relative).name for relative in M4_NEW[:3]
        if _path_present(ROOT / relative)
    }
    _exact_directory_entries(
        ACTIVE_PROV, prov_children if allow_m4_recovery else {
            FAILED_GEN6_RECORD.name, FAILED_GEN5_RECORD.name,
            FAILED_GEN4_RECORD.name,
            FAILED_GEN3_RECORD.name, FAILED_GEN2_RECORD.name,
            SETUP_MANIFEST.name}, mode=0o700)
    _exact_directory_entries(
        ACTIVE_M4_DATA, data_children if allow_m4_recovery else set(), mode=0o700)
    _exact_directory_entries(ACTIVE_STATE, {"nonces"}, mode=0o700)
    _exact_directory_entries(ACTIVE_NONCE_DIR, set(), mode=0o700)
    private_st = ACTIVE_PRIVATE_KEY.lstat()
    private_lstat = {
        "path": str(ACTIVE_PRIVATE_KEY), "device": private_st.st_dev,
        "inode": private_st.st_ino, "uid": private_st.st_uid,
        "gid": private_st.st_gid,
        "mode": stat.S_IMODE(private_st.st_mode), "size": private_st.st_size,
        "nlink": private_st.st_nlink, "mtime_ns": private_st.st_mtime_ns,
        "ctime_ns": private_st.st_ctime_ns, "content_read_for_this_binding": False,
    }
    if (not stat.S_ISREG(private_st.st_mode) or stat.S_ISLNK(private_st.st_mode)
            or private_lstat["mode"] != 0o600 or private_st.st_uid != os.getuid()
            or private_st.st_gid != os.getgid()
            or private_st.st_nlink != 1):
        raise ValueError("post-M3 private-key lstat drift")
    exact_absent = [
        *(ROOT / relative for relative in M4_NEW), M4_TRANSACTION,
        M4_PRIMARY, M4_REBUILD, PRESCORE_REVIEW, ACTIVE_RUN_ROOT,
        *(ROOT / relative for relative in predecessor_runtime.M4_NEW),
        predecessor_runtime.M4_TRANSACTION, predecessor_runtime.M4_PRIMARY,
        predecessor_runtime.M4_REBUILD, predecessor_runtime.PRESCORE_REVIEW,
        predecessor_runtime.ACTIVE_RUN_ROOT,
    ]
    recoverable_paths = {
        *(ROOT / relative for relative in M4_NEW),
        M4_TRANSACTION, M4_PRIMARY, M4_REBUILD,
    }
    for path in exact_absent:
        if _path_present(path) and not (allow_m4_recovery and path in recoverable_paths):
            raise ValueError(f"post-M3 downstream-absence binding failed: {path}")
    tmp = Path("/tmp")
    patterned = []
    for pattern in _post_m3_forbidden_tmp_patterns():
        matches = sorted(str(path) for path in tmp.glob(pattern))
        if matches:
            raise ValueError(f"post-M3 derived downstream output exists: {matches}")
        patterned.append({"pattern": str(tmp / pattern), "matches": []})
    if any(predecessor_runtime.ACTIVE_NONCE_DIR.iterdir()):
        raise ValueError("gen2 nonce output exists")
    absence = {
        "exact_paths": sorted(str(path) for path in exact_absent),
        "derived_path_patterns": patterned,
        "gen3_nonce_children": [], "gen2_nonce_children": [],
        "tmux_session_rule": "dedicated_session_exists_only_under_dedicated_socket",
        "post_m3_review_self_excluded": str(POST_M3_REVIEW.relative_to(ROOT)),
        "gen2_exception": str(GEN2_FAILURE_PATH.relative_to(ROOT)),
    }
    provenance_binding = base._directory_binding(ACTIVE_PROV)
    if allow_m4_recovery and _path_present(M4_TRANSACTION):
        # The historical post-M3 subject was reviewed before the transaction
        # subdirectory incremented the parent's link count.
        provenance_binding = {**provenance_binding,
                              "nlink": provenance_binding["nlink"] - 1}
    directory_bindings = {
        "config": base._directory_binding(ACTIVE_CONFIG),
        "provenance": provenance_binding,
        "m4_data": base._directory_binding(ACTIVE_M4_DATA),
        "state": base._directory_binding(ACTIVE_STATE),
        "nonce": base._directory_binding(ACTIVE_NONCE_DIR),
    }
    return {
        "schema_version": "msae_v3_gen9_post_m3_review_subject_v1",
        "config_entries": [_regular_entry(ACTIVE_CONFIG / name)
                           for name in sorted(config_names)],
        "private_key_lstat": private_lstat,
        "directory_bindings": directory_bindings,
        "failed_gen6_entry": _regular_entry(FAILED_GEN6_RECORD),
        "failed_gen5_entry": _regular_entry(FAILED_GEN5_RECORD),
        "failed_gen4_entry": _regular_entry(FAILED_GEN4_RECORD),
        "failed_gen3_entry": _regular_entry(FAILED_GEN3_RECORD),
        "failed_gen2_entry": _regular_entry(FAILED_GEN2_RECORD),
        "setup_manifest_entry": _regular_entry(SETUP_MANIFEST),
        "plan_entry": _regular_entry(PLAN_PATH),
        "plan_review_entry": _regular_entry(PLAN_REVIEW),
        "implementation_review_entry": _regular_entry(IMPLEMENTATION_REVIEW),
        "downstream_absence": absence,
        "downstream_absence_sha256": base.sha_bytes(base.canonical_bytes(absence)),
    }


def verify_post_m3_review(
    supplied_sha256: str, *, allow_m4_recovery: bool = False,
) -> dict[str, Any]:
    subject = _post_m3_state_binding(allow_m4_recovery=allow_m4_recovery)
    config_by_name = {Path(row["path"]).name: row for row in subject["config_entries"]}
    expected = {
        "GEN7_IMPLEMENTATION_REVIEW": base.sha_file(IMPLEMENTATION_REVIEW),
        "POST_M3_SUBJECT": base.sha_bytes(base.canonical_bytes(subject)),
        "GEN7_PROTOCOL": config_by_name["protocol.json"]["sha256"],
        "GEN7_AUTHORIZATION_COMMITMENT": config_by_name[
            "authorization_commitment.json"]["sha256"],
        "GEN7_PUBLIC_KEY": config_by_name["ed25519_public.pem"]["sha256"],
        "GEN7_CPU_TRACE": config_by_name[
            "cpu_no_model_public_entry_trace.json"]["sha256"],
        "GEN7_SETUP_MANIFEST": subject["setup_manifest_entry"]["sha256"],
        "GEN7_FAILED_GEN6": subject["failed_gen6_entry"]["sha256"],
        "GEN7_FAILED_GEN5": subject["failed_gen5_entry"]["sha256"],
        "GEN7_FAILED_GEN4": subject["failed_gen4_entry"]["sha256"],
        "GEN7_FAILED_GEN3": subject["failed_gen3_entry"]["sha256"],
        "GEN7_FAILED_GEN2": subject["failed_gen2_entry"]["sha256"],
        "M2_COMPLETION": M2_REVIEWED_COMPLETION_SHA256,
    }
    review = _canonical_review(
        POST_M3_REVIEW, supplied_sha256, scope="gen9_post_m3", expected_digests=expected)
    raw = _regular_bytes(POST_M3_REVIEW, mode=0o644)
    if raw.decode("utf-8").splitlines().count(
            "SEALED_PAYLOAD_CONTENT_READS: 0") != 1:
        raise ValueError("post-M3 review sealed-read control drift")
    return {"review": review, "subject": subject}


def _build_m4_impl(
    post_m3_review_sha256: str, *, allow_m4_recovery: bool = False,
) -> dict[str, Any]:
    base.verify_baseline_projection("M2")
    base.verify_protected_v1()
    base.verify_protected_v2()
    base.validate_source_exposure()
    _verify_live_cpu_no_model_trace()
    checkpoints = checkpoint_registry()
    input_relatives = _m4_input_relatives()
    input_snapshot = _tree_entries(ROOT, input_relatives)
    input_snapshot_sha256 = base.sha_bytes(base.canonical_bytes(input_snapshot))
    descriptors = {
        M4_PRIMARY: _m4_build_descriptor(
            role="primary", post_m3_review_sha256=post_m3_review_sha256,
            input_snapshot_sha256=input_snapshot_sha256,
            candidate_paths=input_relatives),
        M4_REBUILD: _m4_build_descriptor(
            role="rebuild", post_m3_review_sha256=post_m3_review_sha256,
            input_snapshot_sha256=input_snapshot_sha256,
            candidate_paths=input_relatives),
    }
    for scratch_root in (M4_PRIMARY, M4_REBUILD):
        if not _path_present(scratch_root):
            continue
        if not allow_m4_recovery:
            raise FileExistsError("M4 complete-tree root exists outside recovery")
        _validate_m4_tree_for_cleanup(
            scratch_root, expected_descriptor=descriptors[scratch_root])
        shutil.rmtree(scratch_root)
        base._fsync_directory(scratch_root.parent)
        if _path_present(scratch_root):
            raise RuntimeError(f"M4 recovery-tree cleanup failed: {scratch_root}")
    initial_status = _git_status()
    anticipated = _anticipated_status()
    raw_directory_projection = _directory_entries(
        ROOT, _candidate_relatives(include_m4=True))
    directory_projection = _historical_manifest_directory_projection(
        raw_directory_projection, recovery=allow_m4_recovery)
    payloads: dict[str, bytes] = {}
    snapshot: list[dict[str, Any]] = input_snapshot
    try:
        left_stage = _materialize_complete_m4(M4_PRIMARY, checkpoints, anticipated,
                                              directory_projection,
                                              build_descriptor=descriptors[M4_PRIMARY])
        right_stage = _materialize_complete_m4(M4_REBUILD, checkpoints, anticipated,
                                               directory_projection,
                                               build_descriptor=descriptors[M4_REBUILD])
        payloads = _compare_complete_m4_trees(M4_PRIMARY, M4_REBUILD,
                                              left_stage, right_stage,
                                              left_descriptor=descriptors[M4_PRIMARY],
                                              right_descriptor=descriptors[M4_REBUILD])
        snapshot = _tree_entries(M4_PRIMARY, input_relatives)
        _verify_live_m4_inputs(snapshot, initial_status, raw_directory_projection)
    finally:
        for scratch_root in (M4_PRIMARY, M4_REBUILD):
            if _path_present(scratch_root):
                _validate_m4_tree_for_cleanup(
                    scratch_root, expected_descriptor=descriptors[scratch_root])
                shutil.rmtree(scratch_root)
                base._fsync_directory(scratch_root.parent)
    if _path_present(M4_PRIMARY) or _path_present(M4_REBUILD):
        raise RuntimeError("M4 complete-tree cleanup failed")
    _verify_live_m4_inputs(snapshot, initial_status, raw_directory_projection)
    _verify_live_cpu_no_model_trace()
    # Reconstruct the complete external/downstream absence subject after both
    # long builds and their cleanup, immediately before the create-once install.
    verify_post_m3_review(
        post_m3_review_sha256, allow_m4_recovery=allow_m4_recovery)
    manifest_sha = base.sha_bytes(payloads[M4_NEW[5]])
    if any(_path_present(path) for path in _prescore_evidence_paths(manifest_sha)):
        raise FileExistsError("digest-derived prescore evidence appeared before M4 install")
    _install_transaction(
        M4_TRANSACTION, M4_NEW, payloads,
        "msae_v3_gen9_m4_install_transaction_v1",
        post_m3_review_sha256=post_m3_review_sha256,
        input_snapshot_sha256=input_snapshot_sha256)
    # Shared M0-M2 data remain exactly at the immutable M2 projection; gen3 M4
    # products live in their disjoint ACTIVE_M4_DATA root.
    base.verify_baseline_projection("M2")
    validate_stage_a()
    return left_stage


def build_m4(post_m3_review_sha256: str) -> dict[str, Any]:
    """Build/install M4 while making sealed-content access impossible."""
    with quarantine_guard():
        recovery = _m4_recovery_present()
        review = verify_post_m3_review(
            post_m3_review_sha256, allow_m4_recovery=recovery)
        result = _build_m4_impl(
            post_m3_review_sha256, allow_m4_recovery=recovery)
        return {**result, "post_m3_review_sha256": review["review"]["sha256"]}


def _expected_live_candidate_paths() -> set[str]:
    return set(_candidate_relatives(include_m4=True))


def _verify_manifest_entry(entry: Mapping[str, Any]) -> dict[str, Any]:
    path = ROOT / str(entry["path"])
    expected = _regular_entry(path, root=ROOT)
    if dict(entry) != expected:
        raise ValueError(f"candidate entry drift: {path}")
    return {**expected, "result": "match"}


def _verify_manifest_directory(entry: Mapping[str, Any]) -> dict[str, Any]:
    path = ROOT / str(entry["path"])
    st = path.lstat()
    if (entry.get("type") != "directory" or not stat.S_ISDIR(st.st_mode)
            or stat.S_ISLNK(st.st_mode) or stat.S_IMODE(st.st_mode) != entry.get("mode")
            or st.st_uid != entry.get("uid") or st.st_gid != entry.get("gid")
            or st.st_nlink != entry.get("nlink")):
        raise ValueError(f"candidate directory drift: {path}")
    return {"path": entry["path"], "verification_action": "lstat_directory",
            "result": "match", "type": "directory", "mode": stat.S_IMODE(st.st_mode),
            "uid": st.st_uid, "gid": st.st_gid, "nlink": st.st_nlink}


def _strict_review_verdict(review: str, manifest: Mapping[str, Any], manifest_sha: str) -> None:
    lines = review.splitlines()
    review_controls = [line for line in lines
                       if re.match(r"(?:VERDICT|REVIEW_SCOPE)\b", line.strip(),
                                   re.ASCII)]
    if review_controls != ["VERDICT: SHIP", "REVIEW_SCOPE: gen9_prescore"]:
        raise ValueError(
            f"review has non-unique, malformed, indented, or non-SHIP controls: "
            f"{review_controls}")
    check_path, trace_path = _prescore_evidence_paths(manifest_sha)
    expected = {
        "GEN6_IMPLEMENTATION_REVIEW_SHA256": base.sha_file(IMPLEMENTATION_REVIEW),
        "GEN6_POST_M3_REVIEW_SHA256": base.sha_file(POST_M3_REVIEW),
        "GEN6_PROTOCOL_SHA256": base.sha_file(ACTIVE_CONFIG / "protocol.json"),
        "GEN6_STAGE_A_SHA256": str(manifest["stage_a_sha256"]),
        "GEN6_STATUS_SHA256": base.sha_file(ACTIVE_PROV / "status.json"),
        "GEN6_CANDIDATE_MANIFEST_SHA256": manifest_sha,
        "GEN6_DEPENDENCY_CLOSURE_SHA256": str(manifest["dependency_closure_sha256"]),
        "GEN6_ENDPOINT_REGISTRY_SHA256": base.sha_file(
            ACTIVE_M4_DATA / "endpoint_registry.json"),
        "GEN6_ENVIRONMENT_ALLOWLIST_SHA256": base.sha_file(
            ACTIVE_M4_DATA / "environment_allowlist.json"),
        "GEN6_PRESCORE_CHECK_SHA256": base.sha_file(check_path),
        "GEN6_PRESCORE_TRACE_SHA256": base.sha_file(trace_path),
        "GEN6_PRESCORE_CHECKER_SHA256": base.sha_file(RUNTIME),
        "SEALED_PAYLOAD_CONTENT_READS": "0",
    }
    controls: dict[str, str] = {}
    for line in lines:
        stripped = line.strip()
        control_like = re.match(
            r"(?:[A-Z][A-Z0-9_]*_SHA256|SEALED_PAYLOAD_CONTENT_READS)\b",
            stripped, re.ASCII)
        if control_like is None:
            continue
        if line != stripped:
            raise ValueError("review has indented/padded digest controls")
        match = re.fullmatch(
            r"([A-Z][A-Z0-9_]*_SHA256|SEALED_PAYLOAD_CONTENT_READS): "
            r"([0-9a-f]{64}|[0-9]+)", line, re.ASCII)
        if match is None or match.group(1) in controls:
            raise ValueError("review has malformed/duplicate digest controls")
        controls[match.group(1)] = match.group(2)
    if controls != expected:
        raise ValueError(f"review digest control set mismatch: {controls!r}")
    expected_control_lines = [
        "VERDICT: SHIP", "REVIEW_SCOPE: gen9_prescore",
        *(f"{key}: {value}" for key, value in expected.items()),
    ]
    observed_control_lines = [line for line in lines if (
        re.fullmatch(r"(?:VERDICT|REVIEW_SCOPE): .+", line, re.ASCII)
        or re.fullmatch(
            r"(?:[A-Z][A-Z0-9_]*_SHA256|SEALED_PAYLOAD_CONTENT_READS): "
            r"(?:[0-9a-f]{64}|[0-9]+)", line, re.ASCII))]
    if observed_control_lines != expected_control_lines:
        raise ValueError("prescore review control order drift")


def _review_bytes() -> bytes:
    raw = _regular_bytes(PRESCORE_REVIEW, mode=0o644)
    text = raw.decode("utf-8", errors="strict")
    if "\r" in text or not text or text != text.rstrip() + "\n":
        raise ValueError("prescore review is not canonical newline-terminated UTF-8")
    return raw


def _prescore_evidence_paths(manifest_sha256: str) -> tuple[Path, Path]:
    base.validate_sha256(manifest_sha256, "candidate-manifest SHA-256")
    prefix = Path(
        f"/tmp/msae_independent_measurement_v3_post_m2_gen9_{manifest_sha256}")
    return Path(f"{prefix}.prescore.check.json"), Path(f"{prefix}.prescore.trace.log")


def _exact_directory_entries(
    path: Path, expected: set[str], *, mode: int | None = None,
) -> None:
    st = path.lstat()
    if (not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode)
            or st.st_uid != os.getuid()
            or (mode is not None and stat.S_IMODE(st.st_mode) != mode)):
        raise ValueError(f"invalid projected directory: {path}")
    observed = set()
    for item in os.scandir(path):
        item_st = item.stat(follow_symlinks=False)
        if stat.S_ISLNK(item_st.st_mode):
            raise ValueError(f"symlink forbidden in projected directory: {item.path}")
        observed.add(item.name)
    if observed != expected:
        raise ValueError(f"directory projection drift at {path}: {sorted(observed ^ expected)}")


def _protected_baseline_results() -> dict[str, Any]:
    baseline = base.verify_baseline_projection("M2")
    protected_v1 = base.verify_protected_v1()
    protected_v2 = base.verify_protected_v2()
    exposure = base.validate_source_exposure()
    value = {
        "baseline_projection": baseline,
        "protected_v1_content_rehash": protected_v1,
        "protected_v2_content_rehash": protected_v2,
        "source_exposure_sha256": base.sha_file(V3_DATA / "source_exposure.json"),
        "source_exposure_disposition": exposure["disposition"],
        "result": "match",
    }
    return {**value, "result_sha256": base.sha_bytes(base.canonical_bytes(value))}


def _quarantine_manifest_results(manifest: Mapping[str, Any]) -> list[dict[str, Any]]:
    current = _quarantine_metadata_rows()
    if manifest.get("quarantined_entries") != current:
        raise ValueError("candidate quarantined metadata projection drift")
    return [{**row, "result": "match"} for row in current]


def _prescore_check_payload(*, phase: str, manifest: Mapping[str, Any],
                            manifest_sha256: str,
                            candidate_results: Sequence[Mapping[str, Any]],
                            directory_results: Sequence[Mapping[str, Any]],
                            quarantine_results: Sequence[Mapping[str, Any]],
                            protected_results: Mapping[str, Any],
                            closure_sha256: str, stage_a_sha256: str) -> dict[str, Any]:
    status_path = ACTIVE_PROV / "status.json"
    status_raw = _regular_bytes(status_path, mode=0o644)
    status = base.strict_json_loads(status_raw.decode("utf-8"))
    if status_raw != base.canonical_bytes(status):
        raise ValueError("M4 status is not canonical")
    return {
        "schema_version": "msae_v3_prescore_check_v3", "protocol_id": PROTOCOL,
        "phase": phase, "checker_code_sha256": base.sha_file(RUNTIME),
        "manifest_sha256": manifest_sha256,
        "candidate_tree_sha256": manifest["candidate_tree_sha256"],
        "dependency_closure_sha256": closure_sha256,
        "stage_a_sha256": stage_a_sha256,
        "m4_status_sha256": base.sha_bytes(status_raw),
        "candidate_file_results": list(candidate_results),
        "candidate_directory_results": list(directory_results),
        "quarantined_metadata_results": list(quarantine_results),
        "protected_baseline_results": dict(protected_results),
        "repository_status_projection": manifest["repository_status"],
        "repository_status_classification": manifest["repository_status_classification"],
        "repository_status_sha256": base.sha_bytes(
            base.canonical_bytes(manifest["repository_status"])),
        "candidate_file_count": len(candidate_results),
        "candidate_directory_count": len(directory_results),
        "quarantined_entry_count": len(quarantine_results),
        "sealed_payload_content_reads": 0, "eligible": True,
    }


def _verify_candidate_manifest_impl(phase: str = "prescore") -> dict[str, Any]:
    _validate_gen3_review_namespace(
        "prescore" if phase == "prescore" else "post_review")
    _validate_gen2_terminal_namespace(require_failure=True)
    manifest_path = ACTIVE_PROV / "prescore_candidate_manifest.json"
    manifest_raw = _regular_bytes(manifest_path, mode=0o644)
    manifest = base.strict_json_loads(manifest_raw.decode("utf-8"))
    if manifest_raw != base.canonical_bytes(manifest):
        raise ValueError("candidate manifest is not canonical")
    if (manifest.get("schema_version") != "msae_v3_prescore_candidate_manifest_v3"
            or manifest.get("protocol_id") != PROTOCOL
            or manifest.get("generation") != GENERATION
            or manifest.get("candidate_root_realpath") != str(ROOT.resolve(strict=True))):
        raise ValueError("candidate manifest schema/root drift")
    # Reconstruct the entire self-excluding manifest from current live bytes and
    # the frozen status projection.  This prevents any unvalidated top-level
    # field (including absence lists or classifications) from being rewritten.
    expected_paths = _expected_live_candidate_paths()
    live_directories = _directory_entries(ROOT, expected_paths)
    expected_manifest = candidate_manifest_payload(
        ROOT, manifest.get("repository_status", []), live_directories)
    if manifest != expected_manifest:
        raise ValueError("candidate manifest does not exactly reconstruct")
    protected_results = _protected_baseline_results()
    quarantine_results = _quarantine_manifest_results(manifest)
    entries = manifest.get("candidate_files")
    if (not isinstance(entries, list) or {row.get("path") for row in entries} != expected_paths
            or len(entries) != len(expected_paths) or manifest.get("candidate_file_paths") != sorted(expected_paths)):
        raise ValueError("candidate manifest is not an independently closed path projection")
    candidate_results = [_verify_manifest_entry(row) for row in entries]
    directories = manifest.get("candidate_directories")
    expected_directories = _candidate_directory_relatives(expected_paths)
    if (not isinstance(directories, list)
            or [row.get("path") for row in directories] != expected_directories
            or manifest.get("candidate_directory_tree_sha256") !=
               base.sha_bytes(base.canonical_bytes(directories))):
        raise ValueError("candidate directory projection is not closed")
    directory_results = [_verify_manifest_directory(row) for row in directories]
    if base.sha_bytes(base.canonical_bytes(entries)) != manifest.get("candidate_tree_sha256"):
        raise ValueError("candidate tree digest drift")
    old_data_names = {name for phase in ("M0", "M1", "M2")
                      for name in base.V3_DATA_PHASE_FILES[phase]}
    if set(path.name for path in V3_DATA.iterdir()) != old_data_names:
        raise ValueError("v3 data root contains an undeclared entry")
    _exact_directory_entries(ACTIVE_M4_DATA, set(base.V3_DATA_PHASE_FILES["M4"]))
    _exact_directory_entries(V3_CONFIG,
                             {"protocol.json", "authorization_commitment.json", "ed25519_public.pem"})
    _exact_directory_entries(ACTIVE_CONFIG,
                             {"protocol.json", "authorization_commitment.json", "ed25519_public.pem",
                              "cpu_no_model_public_entry_trace.json"})
    _exact_directory_entries(V3_PROV,
                             {"m1_completion_manifest.json", "m2_completion_manifest.json",
                              "m3_preflight_attempt_1.json"})
    _exact_directory_entries(ACTIVE_PROV,
                             {"stage_a.json", "status.json", "prescore_candidate_manifest.json"})
    closure = verify_dependency_closure()
    stage = validate_stage_a()
    if (base.sha_file(ACTIVE_M4_DATA / "dependency_closure.json") != manifest["dependency_closure_sha256"]
            or base.sha_file(ACTIVE_PROV / "stage_a.json") != manifest["stage_a_sha256"]):
        raise ValueError("candidate closure/Stage-A digest mismatch")
    current = _git_status()
    allowed = {f"? {M4_NEW[-1]}"}
    if phase in {"post_review", "sign_recovery", "post_signature", "prelaunch"}:
        allowed.add(f"? {PRESCORE_REVIEW.relative_to(ROOT)}")
    if phase in {"post_signature", "prelaunch"}:
        allowed.add(f"? {ACTIVE_RUN_REL}/authorization.json")
    projected = [line for line in current if line not in allowed
                 and not (phase == "sign_recovery"
                          and (_status_path(line) == ACTIVE_RUN_REL
                               or _status_path(line).startswith(ACTIVE_RUN_REL + "/")))]
    if projected != manifest["repository_status"]:
        raise ValueError("repository status projection drift")
    classifications = _classify_repository_status(
        manifest["repository_status"], expected_paths | {M4_NEW[-1]})
    if classifications != manifest["repository_status_classification"]:
        raise ValueError("repository status classification drift")
    for root in manifest["required_external_state"]["required_absent_build_roots"]:
        if _path_present(Path(root)):
            raise ValueError(f"temporary build root exists: {root}")
    commitment = _verify_existing_authorization_state()
    external = manifest["required_external_state"]
    if (external.get("private_key") != commitment["private_key_binding"]
            or external.get("nonce_directory") != base._directory_binding(ACTIVE_NONCE_DIR)
            or external.get("gpu_lock_directory") != base._directory_binding(base.GPU_LOCK_DIR)):
        raise ValueError("candidate external-state binding drift")
    if any(ACTIVE_NONCE_DIR.iterdir()):
        raise ValueError("nonce directory is not empty")
    expected_socket_paths = [str(path) for path in _tmux_paths(manifest["stage_a_sha256"])]
    if external.get("required_absent_short_socket_paths") != expected_socket_paths:
        raise ValueError("candidate short-socket path set drift")
    if external.get("short_socket_family_projection") != {
            "tmp_parent_binding": _tmp_parent_projection_binding(),
            "entries": _short_socket_family_projection()}:
        raise ValueError("candidate short-socket family projection drift")
    if any(_path_present(Path(path)) for path in expected_socket_paths):
        raise ValueError("candidate short socket unexpectedly exists")
    if phase == "prescore":
        if _path_present(PRESCORE_REVIEW) or _path_present(ACTIVE_RUN_ROOT):
            raise ValueError("post-review output exists at prescore")
    elif phase == "post_review":
        if _path_present(ACTIVE_RUN_ROOT):
            raise ValueError("post-review projection mismatch")
        _strict_review_verdict(_review_bytes().decode("utf-8"), manifest,
                               base.sha_file(manifest_path))
        check_path, trace_path = _prescore_evidence_paths(base.sha_file(manifest_path))
        verify_prescore_trace(manifest_path, check_path, trace_path)
    elif phase == "sign_recovery":
        if not PRESCORE_REVIEW.is_file() or PRESCORE_REVIEW.is_symlink():
            raise ValueError("prescore review is absent during signing recovery")
        _strict_review_verdict(_review_bytes().decode("utf-8"), manifest,
                               base.sha_file(manifest_path))
        check_path, trace_path = _prescore_evidence_paths(base.sha_file(manifest_path))
        verify_prescore_trace(manifest_path, check_path, trace_path)
    elif phase in {"post_signature", "prelaunch"}:
        if not PRESCORE_REVIEW.is_file() or PRESCORE_REVIEW.is_symlink() or not ACTIVE_RUN_ROOT.is_dir():
            raise ValueError("post-signature projection mismatch")
        run_entries = []
        run_st = ACTIVE_RUN_ROOT.lstat()
        if stat.S_IMODE(run_st.st_mode) != 0o700 or stat.S_ISLNK(run_st.st_mode):
            raise ValueError("prelaunch run-root identity/mode drift")
        for path in ACTIVE_RUN_ROOT.rglob("*"):
            st = path.lstat()
            if stat.S_ISREG(st.st_mode) and not stat.S_ISLNK(st.st_mode):
                if stat.S_IMODE(st.st_mode) != 0o600 or st.st_uid != os.getuid() or st.st_nlink != 1:
                    raise ValueError(f"prelaunch run file identity/mode drift: {path}")
                run_entries.append(path.relative_to(ACTIVE_RUN_ROOT).as_posix())
            else:
                raise ValueError(f"unexpected prelaunch run-root object: {path}")
        if sorted(run_entries) != ["authorization.json"]:
            raise ValueError(f"unexpected prelaunch run outputs: {run_entries}")
        verify_authorization(ACTIVE_RUN_ROOT / "authorization.json", consume=False)
        check_path, trace_path = _prescore_evidence_paths(base.sha_file(manifest_path))
        verify_prescore_trace(manifest_path, check_path, trace_path)
    else:
        raise ValueError(f"unknown candidate phase: {phase}")
    return _prescore_check_payload(
        phase=phase, manifest=manifest, manifest_sha256=base.sha_bytes(manifest_raw),
        candidate_results=candidate_results, directory_results=directory_results,
        quarantine_results=quarantine_results, protected_results=protected_results,
        closure_sha256=base.sha_bytes(base.canonical_bytes(closure)),
        stage_a_sha256=base.sha_bytes(base.canonical_bytes(stage)))


def verify_candidate_manifest(phase: str = "prescore") -> dict[str, Any]:
    with quarantine_guard():
        return _verify_candidate_manifest_impl(phase)


def _prescore_traced_check_impl(manifest: Path, output: Path, trace: Path) -> None:
    if manifest.resolve(strict=True) != (ACTIVE_PROV / "prescore_candidate_manifest.json").resolve(strict=True):
        raise ValueError("unexpected candidate manifest")
    verify_candidate_manifest("prescore")
    expected_output, expected_trace = _prescore_evidence_paths(base.sha_file(manifest))
    if output != expected_output or trace != expected_trace:
        raise ValueError("prescore evidence paths are not manifest-derived")
    for path in (output, trace):
        if path.exists() or path.is_symlink():
            raise FileExistsError(f"prescore evidence path already exists: {path}")
    fds: list[int] = []
    try:
        for path in (output, trace):
            fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600)
            os.fchmod(fd, 0o600)
            os.set_inheritable(fd, True)
            fds.append(fd)
        check_fd, trace_fd = fds
        command = ["/usr/bin/strace", "-f", "-qq", "-yy", "-s", "4096",
                   "-e", "trace=open,openat,openat2,creat", "-o", f"/proc/self/fd/{trace_fd}",
                   str(ROOT / ".venv-atlas/bin/python"), "-S", "-B", "-I",
                   str(continuation.CONTROLLER_PATH.resolve()), "prescore-check",
                   "--output-fd", str(check_fd)]
        result = subprocess.run(command, pass_fds=(check_fd, trace_fd), close_fds=True,
                                env=FROZEN_BASE_PROCESS_ENVIRONMENT)
        if result.returncode != 0:
            raise RuntimeError(f"traced prescore check failed: {result.returncode}")
        for fd, path in zip(fds, (output, trace)):
            os.fsync(fd)
            fd_st, path_st = os.fstat(fd), path.lstat()
            if (fd_st.st_dev, fd_st.st_ino) != (path_st.st_dev, path_st.st_ino):
                raise ValueError("prescore output path/FD substitution")
    finally:
        for fd in fds:
            with contextlib.suppress(OSError):
                os.close(fd)


def prescore_traced_check(manifest: Path, output: Path, trace: Path) -> None:
    with quarantine_guard():
        _prescore_traced_check_impl(manifest, output, trace)


def _trace_open_candidates(line: str) -> set[str]:
    if re.search(r"\b(?:open|openat|openat2|creat)\(", line) is None:
        return set()
    candidates = {match for match in re.findall(r"<(/[^>]*)>", line)}
    quoted = re.findall(r'"(?:[^"\\]|\\.)*"', line)
    decoded = []
    for raw in quoted:
        try:
            value = ast.literal_eval(raw)
        except (SyntaxError, ValueError):
            continue
        if isinstance(value, str):
            decoded.append(value)
            if value.startswith("/"):
                candidates.add(value)
    directory = re.search(r"(?:AT_FDCWD|\d+)<(/[^>]*)>\s*,", line)
    if directory and decoded:
        candidates.add(str(Path(directory.group(1)) / decoded[0]))
    return {os.path.realpath(path.removesuffix(" (deleted)")) for path in candidates}


def verify_trace_no_forbidden(trace_text: str, forbidden_paths: Iterable[Path]) -> None:
    forbidden = {os.path.realpath(path) for path in forbidden_paths}
    for line in trace_text.splitlines():
        touched = _trace_open_candidates(line) & forbidden
        if touched:
            raise ValueError(f"trace observed forbidden content open: {sorted(touched)}")


def _verify_prescore_trace_impl(manifest: Path, check: Path, trace: Path) -> dict[str, Any]:
    if manifest.resolve(strict=True) != (ACTIVE_PROV / "prescore_candidate_manifest.json").resolve(strict=True):
        raise ValueError("unexpected prescore manifest path")
    manifest_raw = _regular_bytes(manifest, mode=0o644)
    manifest_payload = base.strict_json_loads(manifest_raw.decode("utf-8"))
    if manifest_raw != base.canonical_bytes(manifest_payload):
        raise ValueError("prescore manifest is not canonical")
    expected_manifest = base.sha_bytes(manifest_raw)
    expected_check, expected_trace = _prescore_evidence_paths(expected_manifest)
    if check != expected_check or trace != expected_trace:
        raise ValueError("prescore evidence path mismatch")
    check_raw = _regular_bytes(check, mode=0o600)
    trace_raw = _regular_bytes(trace, mode=0o600)
    payload = base.strict_json_loads(check_raw.decode("utf-8"))
    if check_raw != base.canonical_bytes(payload):
        raise ValueError("prescore check output is not canonical")
    closure_raw = _regular_bytes(ACTIVE_M4_DATA / "dependency_closure.json", mode=0o644)
    stage_raw = _regular_bytes(ACTIVE_PROV / "stage_a.json", mode=0o644)
    closure_payload_value = base.strict_json_loads(closure_raw.decode("utf-8"))
    stage_payload_value = base.strict_json_loads(stage_raw.decode("utf-8"))
    if (closure_raw != base.canonical_bytes(closure_payload_value)
            or stage_raw != base.canonical_bytes(stage_payload_value)):
        raise ValueError("prescore closure/Stage-A evidence is noncanonical")
    expected_paths = _expected_live_candidate_paths()
    expected_manifest_payload = candidate_manifest_payload(
        ROOT, manifest_payload.get("repository_status", []),
        _directory_entries(ROOT, expected_paths))
    if manifest_payload != expected_manifest_payload:
        raise ValueError("traced candidate manifest does not exactly reconstruct")
    entries = manifest_payload.get("candidate_files")
    directories = manifest_payload.get("candidate_directories")
    if not isinstance(entries, list) or not isinstance(directories, list):
        raise ValueError("traced candidate manifest entry arrays malformed")
    candidate_results = [_verify_manifest_entry(row) for row in entries]
    directory_results = [_verify_manifest_directory(row) for row in directories]
    quarantine_results = _quarantine_manifest_results(manifest_payload)
    protected_results = _protected_baseline_results()
    expected_payload = _prescore_check_payload(
        phase="prescore", manifest=manifest_payload, manifest_sha256=expected_manifest,
        candidate_results=candidate_results, directory_results=directory_results,
        quarantine_results=quarantine_results, protected_results=protected_results,
        closure_sha256=base.sha_bytes(closure_raw), stage_a_sha256=base.sha_bytes(stage_raw))
    if payload != expected_payload:
        raise ValueError("prescore check output mismatch")
    if len(trace_raw) < 1024 or not trace_raw.endswith(b"\n"):
        raise ValueError("prescore trace is empty, truncated, or implausibly small")
    trace_text = trace_raw.decode("utf-8", errors="strict")
    successful = [line for line in trace_text.splitlines()
                  if re.search(r"\b(?:open|openat|openat2|creat)\(", line)
                  and re.search(r"\)\s+=\s+[0-9]+(?:<[^>]+>)?", line)]
    if len(successful) < 10:
        raise ValueError("prescore trace lacks expected successful open activity")
    opened = set().union(*(_trace_open_candidates(line) for line in successful))
    expected_opened = {str(path.resolve(strict=True)) for path in
                       (continuation.CONTROLLER_PATH, RUNTIME,
                        ACTIVE_PROV / "prescore_candidate_manifest.json",
                        ACTIVE_PROV / "stage_a.json", ACTIVE_M4_DATA / "dependency_closure.json")}
    if not expected_opened.issubset(opened):
        raise ValueError(f"prescore trace lacks required opens: {sorted(expected_opened - opened)}")
    verify_trace_no_forbidden(trace_text,
                              (ROOT / rel for rel in base.QUARANTINED))
    result = {"manifest_sha256": expected_manifest, "check_sha256": base.sha_file(check),
              "trace_sha256": base.sha_file(trace), "sealed_payload_content_reads": 0,
              "eligible": True}
    print(json.dumps(result, sort_keys=True, separators=(",", ":")))
    return result


def verify_prescore_trace(manifest: Path, check: Path, trace: Path) -> dict[str, Any]:
    with quarantine_guard():
        return _verify_prescore_trace_impl(manifest, check, trace)


def _authorization_unsigned(envelope_path: Path) -> tuple[dict[str, Any], bytes, bytes, bytes]:
    raw = _regular_bytes(envelope_path, mode=0o600)
    envelope = base.strict_json_loads(raw.decode("utf-8"))
    if raw != base.canonical_bytes(envelope):
        raise ValueError("authorization envelope is not canonical JSON")
    if set(envelope).issuperset({"signature_b64"}) is False:
        raise ValueError("authorization signature missing")
    signature = base64.b64decode(envelope.pop("signature_b64"), validate=True)
    signed = base.canonical_bytes(envelope)
    return envelope, signed, signature, raw


def verify_authorization(envelope_path: Path, *, consume: bool,
                         run_root: Path | None = None) -> dict[str, Any]:
    from cryptography.hazmat.primitives import serialization
    envelope, signed, signature, envelope_file_bytes = _authorization_unsigned(envelope_path)
    commitment_path = ACTIVE_CONFIG / "authorization_commitment.json"
    commitment = _verify_existing_authorization_state()
    manifest_path = ACTIVE_PROV / "prescore_candidate_manifest.json"
    expected = {"prescore_candidate_manifest_sha256": base.sha_file(manifest_path),
                "operator_instruction_sha256": base.sha_bytes(OPERATOR_INSTRUCTION.encode("utf-8")),
                "operator_instruction": OPERATOR_INSTRUCTION,
                "review_sha256": base.sha_bytes(_review_bytes()),
                "review_verdict": "SHIP", "scope": "calibration_replay_only"}
    if any(envelope.get(key) != value for key, value in expected.items()):
        raise ValueError("authorization does not bind exact review/manifest/operator/scope")
    public_bytes = _regular_bytes(ACTIVE_CONFIG / "ed25519_public.pem", mode=0o644)
    if base.sha_bytes(public_bytes) != commitment.get("public_key_sha256"):
        raise ValueError("authorization public-key drift")
    serialization.load_pem_public_key(public_bytes).verify(signature, signed)
    bindings = {
        "schema_version": commitment["envelope_schema"], "protocol_id": PROTOCOL,
        "commitment_sha256": base.sha_file(commitment_path),
        "stage_a_sha256": base.sha_file(ACTIVE_PROV / "stage_a.json"),
        "protocol_config_sha256": base.sha_file(ACTIVE_CONFIG / "protocol.json"),
        "dependency_closure_sha256": base.sha_file(ACTIVE_M4_DATA / "dependency_closure.json"),
    }
    if any(envelope.get(key) != value for key, value in bindings.items()):
        raise ValueError("authorization cryptographic lineage mismatch")
    now = int(time.time())
    issued, expires = envelope.get("issued_unix"), envelope.get("expires_unix")
    if (type(issued) is not int or type(expires) is not int or not issued <= now <= expires
            or expires <= issued or expires - issued > commitment["maximum_lifetime_seconds"]):
        raise ValueError("authorization validity interval mismatch")
    nonce = envelope.get("nonce")
    if not isinstance(nonce, str) or re.fullmatch(r"[0-9a-f]{64}", nonce, re.ASCII) is None:
        raise ValueError("authorization nonce malformed")
    envelope_digest = base.sha_bytes(envelope_file_bytes)
    record_name = f"{envelope_digest}.consumed"
    directory_fd = os.open(ACTIVE_NONCE_DIR,
                           os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
    record_stat: os.stat_result | None = None
    record_path = ACTIVE_NONCE_DIR / record_name
    try:
        directory_before = os.fstat(directory_fd)
        expected_directory = commitment["nonce_directory"]
        path_before = ACTIVE_NONCE_DIR.lstat()
        fields = ("st_dev", "st_ino", "st_uid", "st_nlink")
        if (not stat.S_ISDIR(directory_before.st_mode)
                or stat.S_ISLNK(path_before.st_mode)
                or stat.S_IMODE(directory_before.st_mode) != expected_directory["mode"]
                or any(getattr(directory_before, field) != expected_directory[key]
                       for field, key in zip(fields, ("device", "inode", "uid", "nlink")))
                or (directory_before.st_dev, directory_before.st_ino) !=
                   (path_before.st_dev, path_before.st_ino)):
            raise ValueError("held nonce-directory FD does not match commitment/path")
        if consume:
            fd = os.open(record_name,
                         os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC,
                         0o600, dir_fd=directory_fd)
            try:
                os.fchmod(fd, 0o600)
                payload = base.canonical_bytes({"schema_version": "msae_v3_nonce_consumed_v2",
                                                "authorization_file_sha256": envelope_digest,
                                                "stage_a_sha256": envelope["stage_a_sha256"]})
                try:
                    _write_all(fd, payload)
                    os.fsync(fd)
                    os.lseek(fd, 0, os.SEEK_SET)
                    if os.read(fd, len(payload) + 1) != payload:
                        raise OSError("nonce consumed record did not reread exactly")
                except BaseException:
                    # A partial record must not irreversibly consume the nonce.
                    with contextlib.suppress(OSError):
                        os.unlink(record_name, dir_fd=directory_fd)
                        os.fsync(directory_fd)
                    raise
                record_stat = os.fstat(fd)
            finally:
                os.close(fd)
            os.fsync(directory_fd)
        else:
            try:
                probe = os.open(record_name, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC,
                                dir_fd=directory_fd)
            except FileNotFoundError:
                probe = -1
            if probe >= 0:
                os.close(probe)
                raise ValueError("authorization nonce has already been consumed")
        directory_after = os.fstat(directory_fd)
        path_after = ACTIVE_NONCE_DIR.lstat()
        if ((directory_before.st_dev, directory_before.st_ino, directory_before.st_mode,
             directory_before.st_uid, directory_before.st_nlink) !=
            (directory_after.st_dev, directory_after.st_ino, directory_after.st_mode,
             directory_after.st_uid, directory_after.st_nlink)
                or (directory_after.st_dev, directory_after.st_ino) !=
                   (path_after.st_dev, path_after.st_ino) or stat.S_ISLNK(path_after.st_mode)):
            raise ValueError("nonce directory changed during authorization verification")
    finally:
        os.close(directory_fd)
    if consume:
        assert record_stat is not None
        path_st = record_path.lstat()
        if ((record_stat.st_dev, record_stat.st_ino) != (path_st.st_dev, path_st.st_ino)
                or not stat.S_ISREG(record_stat.st_mode) or stat.S_ISLNK(path_st.st_mode)
                or stat.S_IMODE(record_stat.st_mode) != 0o600 or record_stat.st_uid != os.getuid()
                or record_stat.st_nlink != 1):
            raise ValueError("nonce record identity/mode/ownership drift")
        if run_root is not None:
            base.install_json(run_root / "nonce_consumed.json", {
                "schema_version": "msae_v3_nonce_attestation_v2", "record_path": str(record_path),
                "record_device": record_stat.st_dev, "record_inode": record_stat.st_ino,
                "record_mode": stat.S_IMODE(record_stat.st_mode),
                "record_sha256": base.sha_file(record_path),
                "authorization_file_sha256": envelope_digest})
    return {**envelope, "signature_b64": base64.b64encode(signature).decode("ascii"),
            "envelope_sha256": envelope_digest}


def _authorization_payload(
    commitment: Mapping[str, Any], *, nonce: str, issued: int,
) -> tuple[dict[str, Any], bytes, bytes]:
    """Create and sign one complete in-memory calibration authorization."""
    from cryptography.hazmat.primitives import serialization
    private = serialization.load_pem_private_key(
        _regular_bytes(ACTIVE_PRIVATE_KEY, mode=0o600), password=None)
    envelope = {
        "schema_version": commitment["envelope_schema"], "protocol_id": PROTOCOL,
        "scope": "calibration_replay_only",
        "commitment_sha256": base.sha_file(ACTIVE_CONFIG / "authorization_commitment.json"),
        "stage_a_sha256": base.sha_file(ACTIVE_PROV / "stage_a.json"),
        "protocol_config_sha256": base.sha_file(ACTIVE_CONFIG / "protocol.json"),
        "dependency_closure_sha256": base.sha_file(
            ACTIVE_M4_DATA / "dependency_closure.json"),
        "prescore_candidate_manifest_sha256": base.sha_file(
            ACTIVE_PROV / "prescore_candidate_manifest.json"),
        "operator_instruction": OPERATOR_INSTRUCTION,
        "operator_instruction_sha256": commitment["operator_instruction_sha256"],
        "review_sha256": base.sha_bytes(_review_bytes()), "review_verdict": "SHIP",
        "nonce": nonce, "issued_unix": issued,
        "expires_unix": issued + int(commitment["maximum_lifetime_seconds"]),
    }
    unsigned = base.canonical_bytes(envelope)
    signature = private.sign(unsigned)
    output = {**envelope, "signature_b64": base64.b64encode(signature).decode("ascii")}
    return output, unsigned, base.canonical_bytes(output)


def _sign_descriptor(
    commitment: Mapping[str, Any], output: Mapping[str, Any],
    unsigned: bytes, authorization_raw: bytes,
) -> dict[str, Any]:
    return {
        "schema_version": "msae_v3_gen9_sign_transaction_v1",
        "protocol_id": PROTOCOL,
        "generation": GENERATION,
        "implementation_review_sha256": base.sha_file(IMPLEMENTATION_REVIEW),
        "post_m3_review_sha256": base.sha_file(POST_M3_REVIEW),
        "prescore_review_sha256": base.sha_file(PRESCORE_REVIEW),
        "authorization_b64": base64.b64encode(authorization_raw).decode("ascii"),
        "authorization_sha256": base.sha_bytes(authorization_raw),
        "unsigned_sha256": base.sha_bytes(unsigned),
        "nonce": output["nonce"],
        "not_before": output["issued_unix"],
        "not_after": output["expires_unix"],
        "private_key_lstat": commitment["private_key_binding"],
        "public_key_sha256": commitment["public_key_sha256"],
    }


def _validate_link_sign_authorization(
    descriptor: Mapping[str, Any], commitment: Mapping[str, Any],
) -> tuple[dict[str, Any], bytes]:
    from cryptography.hazmat.primitives import serialization
    sealed = descriptor.get("sealed_random_payloads")
    if not isinstance(sealed, dict) or set(sealed) != {"authorization_b64"}:
        raise ValueError("sign link transaction sealed payload drift")
    try:
        raw = base64.b64decode(str(sealed["authorization_b64"]), validate=True)
    except (ValueError, binascii.Error) as error:
        raise ValueError("sign authorization base64 drift") from error
    value = base.strict_json_loads(raw.decode("utf-8"))
    if raw != base.canonical_bytes(value):
        raise ValueError("sign authorization is noncanonical")
    if set(value) != {
        "schema_version", "protocol_id", "scope", "commitment_sha256",
        "stage_a_sha256", "protocol_config_sha256", "dependency_closure_sha256",
        "prescore_candidate_manifest_sha256", "operator_instruction",
        "operator_instruction_sha256", "review_sha256", "review_verdict",
        "nonce", "issued_unix", "expires_unix", "signature_b64",
    }:
        raise ValueError("sign authorization schema drift")
    signature_b64 = value["signature_b64"]
    unsigned_value = dict(value); unsigned_value.pop("signature_b64")
    unsigned = base.canonical_bytes(unsigned_value)
    public_raw = _regular_bytes(ACTIVE_CONFIG / "ed25519_public.pem", mode=0o644)
    public_key = serialization.load_pem_public_key(public_raw)
    public_key.verify(base64.b64decode(signature_b64, validate=True), unsigned)
    expected = {
        "schema_version": commitment["envelope_schema"], "protocol_id": PROTOCOL,
        "scope": "calibration_replay_only",
        "commitment_sha256": base.sha_file(ACTIVE_CONFIG / "authorization_commitment.json"),
        "stage_a_sha256": base.sha_file(ACTIVE_PROV / "stage_a.json"),
        "protocol_config_sha256": base.sha_file(ACTIVE_CONFIG / "protocol.json"),
        "dependency_closure_sha256": base.sha_file(
            ACTIVE_M4_DATA / "dependency_closure.json"),
        "prescore_candidate_manifest_sha256": base.sha_file(
            ACTIVE_PROV / "prescore_candidate_manifest.json"),
        "operator_instruction": OPERATOR_INSTRUCTION,
        "operator_instruction_sha256": commitment["operator_instruction_sha256"],
        "review_sha256": base.sha_bytes(_review_bytes()), "review_verdict": "SHIP",
        "nonce": value["nonce"], "issued_unix": value["issued_unix"],
        "expires_unix": value["expires_unix"],
    }
    if (unsigned_value != expected
            or re.fullmatch(r"[0-9a-f]{64}", str(value["nonce"]), re.ASCII) is None
            or not isinstance(value["issued_unix"], int)
            or value["expires_unix"] - value["issued_unix"] !=
               commitment["maximum_lifetime_seconds"]):
        raise ValueError("sign authorization semantic drift")
    publications = descriptor.get("publications")
    expected_row = _publication_row(
        0, SIGN_TRANSACTION, "authorization.payload", ACTIVE_RUN_ROOT,
        "authorization.json", raw, 0o600, "signed_calibration_authorization")
    if publications != [expected_row]:
        raise ValueError("sign publication row drift")
    authority = {
        "prescore_review_sha256": base.sha_file(PRESCORE_REVIEW),
        "manifest_sha256": base.sha_file(ACTIVE_PROV / "prescore_candidate_manifest.json"),
        "stage_a_sha256": base.sha_file(ACTIVE_PROV / "stage_a.json"),
        "protocol_config_sha256": base.sha_file(ACTIVE_CONFIG / "protocol.json"),
        "commitment_sha256": base.sha_file(ACTIVE_CONFIG / "authorization_commitment.json"),
        "dependency_closure_sha256": base.sha_file(
            ACTIVE_M4_DATA / "dependency_closure.json"),
    }
    authority_sha = base.sha_bytes(base.canonical_bytes(authority))
    if descriptor.get("authority_sha256") != authority_sha:
        raise ValueError("sign transaction external authority drift")
    _validate_link_transaction_descriptor(
        descriptor, kind="sign", authority_sha256=authority_sha,
        publications=[expected_row], maximum_seconds=300)
    return value, raw


def _sign_authorization_impl() -> dict[str, Any]:
    recovery = _path_present(ACTIVE_RUN_ROOT)
    verify_candidate_manifest("sign_recovery" if recovery else "post_review")
    commitment = _verify_existing_authorization_state(verify_private_content=True)
    if any(ACTIVE_NONCE_DIR.iterdir()):
        raise ValueError("nonce state must be empty before signing")
    authorization_path = ACTIVE_RUN_ROOT / "authorization.json"
    descriptor_path = SIGN_TRANSACTION / "transaction.json"
    bootstrap_path = SIGN_TRANSACTION / ".transaction.json.bootstrap"

    if _path_present(authorization_path) and not _path_present(SIGN_TRANSACTION):
        output = verify_authorization(authorization_path, consume=False)
        output.pop("envelope_sha256", None)
        verify_candidate_manifest("post_signature")
        return output
    if not _path_present(ACTIVE_RUN_ROOT):
        _ensure_secure_dir(ACTIVE_RUN_ROOT)
    else:
        st = ACTIVE_RUN_ROOT.lstat()
        if (not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode)
                or st.st_uid != os.getuid() or stat.S_IMODE(st.st_mode) != 0o700):
            raise ValueError("sign recovery run-root identity drift")
    if not _path_present(SIGN_TRANSACTION):
        if _path_present(authorization_path):
            raise ValueError("authorization exists without completed sign transaction")
        _ensure_secure_dir(SIGN_TRANSACTION)
    else:
        st = SIGN_TRANSACTION.lstat()
        if (not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode)
                or st.st_uid != os.getuid() or stat.S_IMODE(st.st_mode) != 0o700):
            raise ValueError("sign transaction root identity drift")
    allowed_run = {SIGN_TRANSACTION.name} | (
        {authorization_path.name} if _path_present(authorization_path) else set())
    _exact_directory_entries(ACTIVE_RUN_ROOT, allowed_run, mode=0o700)

    if _path_present(descriptor_path) or _path_present(bootstrap_path):
        authority_path = descriptor_path if _path_present(descriptor_path) else bootstrap_path
        descriptor_raw = _regular_bytes(authority_path, mode=0o600)
        descriptor = base.strict_json_loads(descriptor_raw.decode("utf-8"))
        if descriptor_raw != base.canonical_bytes(descriptor):
            raise ValueError("sign link transaction descriptor is noncanonical")
        output, authorization_raw = _validate_link_sign_authorization(
            descriptor, commitment)
    else:
        if any(os.scandir(SIGN_TRANSACTION)):
            raise ValueError("unbound sign transaction state")
        nonce = os.urandom(32).hex()
        issued = int(time.time())
        output, _unsigned, authorization_raw = _authorization_payload(
            commitment, nonce=nonce, issued=issued)
        row = _publication_row(
            0, SIGN_TRANSACTION, "authorization.payload", ACTIVE_RUN_ROOT,
            "authorization.json", authorization_raw, 0o600,
            "signed_calibration_authorization")
        authority = {
            "prescore_review_sha256": base.sha_file(PRESCORE_REVIEW),
            "manifest_sha256": base.sha_file(
                ACTIVE_PROV / "prescore_candidate_manifest.json"),
            "stage_a_sha256": base.sha_file(ACTIVE_PROV / "stage_a.json"),
            "protocol_config_sha256": base.sha_file(ACTIVE_CONFIG / "protocol.json"),
            "commitment_sha256": base.sha_file(
                ACTIVE_CONFIG / "authorization_commitment.json"),
            "dependency_closure_sha256": base.sha_file(
                ACTIVE_M4_DATA / "dependency_closure.json"),
        }
        descriptor = _link_transaction_payload(
            kind="sign",
            authority_sha256=base.sha_bytes(base.canonical_bytes(authority)),
            publications=[row], maximum_seconds=300,
            sealed_random_payloads={"authorization_b64": base64.b64encode(
                authorization_raw).decode("ascii")})
    _bootstrap_link_transaction(SIGN_TRANSACTION, descriptor)
    output, authorization_raw = _validate_link_sign_authorization(
        descriptor, commitment)
    row = descriptor["publications"][0]
    _link_publication(
        descriptor, row, authorization_raw, descriptor_path=descriptor_path)
    if _regular_bytes(authorization_path, mode=0o600) != authorization_raw:
        raise ValueError("signed authorization publication drift")
    observed = {entry.name for entry in os.scandir(SIGN_TRANSACTION)}
    if observed != {"transaction.json"}:
        raise ValueError(f"sign transaction cleanup has extras: {observed}")
    descriptor_path.unlink(); base._fsync_directory(SIGN_TRANSACTION)
    SIGN_TRANSACTION.rmdir(); base._fsync_directory(ACTIVE_RUN_ROOT)
    verify_authorization(authorization_path, consume=False)
    verify_candidate_manifest("post_signature")
    return output

def sign_authorization() -> dict[str, Any]:
    with quarantine_guard():
        return _sign_authorization_impl()


def _send_json(sock: socket.socket, value: Any) -> None:
    raw = base.canonical_bytes(value)
    sock.sendall(struct.pack(">Q", len(raw)) + raw)


def _recv_json(sock: socket.socket) -> Any:
    header = b""
    while len(header) < 8:
        chunk = sock.recv(8 - len(header))
        if not chunk:
            raise EOFError("handoff closed before header")
        header += chunk
    length = struct.unpack(">Q", header)[0]
    if length > (1 << 20):
        raise ValueError("oversized handoff frame")
    raw = b""
    while len(raw) < length:
        chunk = sock.recv(length - len(raw))
        if not chunk:
            raise EOFError("handoff closed before body")
        raw += chunk
    return base.strict_json_loads(raw.decode("utf-8"))


def validate_runner_readiness(readiness: Mapping[str, Any], worker: Mapping[str, Any],
                              gpu_uuid: str, authorization: Mapping[str, Any]) -> dict[str, Any]:
    attestation_raw = _regular_bytes(ACTIVE_RUN_ROOT / "nonce_consumed.json", mode=0o644)
    attestation = base.strict_json_loads(attestation_raw.decode("utf-8"))
    if attestation_raw != base.canonical_bytes(attestation):
        raise ValueError("nonce attestation is noncanonical")
    expected = {
        "schema_version": "msae_v3_runner_ready_v1", "protocol_id": PROTOCOL,
        "worker_pid": worker["worker_pid"], "worker_pgid": worker["worker_pgid"],
        "broker_pid": worker["broker_pid"], "gpu_uuid": gpu_uuid,
        "stage_a_sha256": base.sha_file(ACTIVE_PROV / "stage_a.json"),
        "protocol_config_sha256": base.sha_file(ACTIVE_CONFIG / "protocol.json"),
        "dependency_closure_sha256": base.sha_file(ACTIVE_M4_DATA / "dependency_closure.json"),
        "authorization_envelope_sha256": authorization["envelope_sha256"],
        "nonce_attestation_sha256": base.sha_bytes(attestation_raw),
        "pre_model": True,
    }
    if dict(readiness) != expected:
        raise ValueError("runner readiness exact lineage mismatch")
    expected_record_path = ACTIVE_NONCE_DIR / f"{authorization['envelope_sha256']}.consumed"
    record_path = Path(str(attestation.get("record_path")))
    if record_path != expected_record_path:
        raise ValueError("nonce attestation does not name the exact derived consumed record")
    record_raw = _regular_bytes(record_path, mode=0o600)
    record_st = record_path.lstat()
    expected_record_raw = base.canonical_bytes({
        "schema_version": "msae_v3_nonce_consumed_v2",
        "authorization_file_sha256": authorization["envelope_sha256"],
        "stage_a_sha256": expected["stage_a_sha256"],
    })
    if (attestation.get("schema_version") != "msae_v3_nonce_attestation_v2"
            or attestation.get("authorization_file_sha256") != authorization["envelope_sha256"]
            or attestation.get("record_device") != record_st.st_dev
            or attestation.get("record_inode") != record_st.st_ino
            or attestation.get("record_mode") != 0o600
            or record_raw != expected_record_raw
            or attestation.get("record_sha256") != base.sha_bytes(expected_record_raw)):
        raise ValueError("nonce attestation/record identity mismatch")
    return attestation


def _receive_fd(sock: socket.socket) -> int:
    _, ancillary, _, _ = sock.recvmsg(1, socket.CMSG_LEN(array.array("i", [0]).itemsize))
    fds: list[int] = []
    for level, kind, raw in ancillary:
        if level == socket.SOL_SOCKET and kind == socket.SCM_RIGHTS:
            values = array.array("i")
            values.frombytes(raw[:len(raw) - len(raw) % values.itemsize])
            fds.extend(values)
    if len(fds) != 1:
        for fd in fds:
            os.close(fd)
        raise ValueError("expected exactly one GPU lease FD")
    return fds[0]


def _validate_gpu_lock_fd(lease_fd: int, gpu_uuid: str) -> dict[str, int]:
    commitment = base.read_json(ACTIVE_CONFIG / "authorization_commitment.json")
    directory_fd = os.open(base.GPU_LOCK_DIR,
                           os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
    name = f"{base.sha_bytes(gpu_uuid.encode('ascii'))}.lock"
    try:
        directory_st = os.fstat(directory_fd)
        directory_path_st = base.GPU_LOCK_DIR.lstat()
        expected_dir = commitment["gpu_lock_directory"]
        if ((directory_st.st_dev, directory_st.st_ino) !=
                (directory_path_st.st_dev, directory_path_st.st_ino)
                or (directory_st.st_dev, directory_st.st_ino, directory_st.st_uid,
                    stat.S_IMODE(directory_st.st_mode), directory_st.st_nlink) !=
                   (expected_dir["device"], expected_dir["inode"], expected_dir["uid"],
                    expected_dir["mode"], expected_dir["nlink"])):
            raise ValueError("inherited GPU lock directory binding drift")
        path_fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=directory_fd)
        try:
            path_st = os.fstat(path_fd)
            lease_st = os.fstat(lease_fd)
            os.lseek(path_fd, 0, os.SEEK_SET)
            payload = os.read(path_fd, 4096)
        finally:
            os.close(path_fd)
        live_path_st = (base.GPU_LOCK_DIR / name).lstat()
        directory_after = os.fstat(directory_fd)
        directory_path_after = base.GPU_LOCK_DIR.lstat()
        expected_payload = base.canonical_bytes({"schema_version": "msae_gpu_uuid_lock_v1",
                                                 "gpu_uuid": gpu_uuid})
        if ((lease_st.st_dev, lease_st.st_ino) != (path_st.st_dev, path_st.st_ino)
                or (path_st.st_dev, path_st.st_ino) != (live_path_st.st_dev, live_path_st.st_ino)
                or not stat.S_ISREG(lease_st.st_mode) or stat.S_ISLNK(live_path_st.st_mode)
                or stat.S_IMODE(lease_st.st_mode) != 0o600 or lease_st.st_uid != os.getuid()
                or lease_st.st_nlink != 1 or payload != expected_payload):
            raise ValueError("inherited GPU lock FD/path/type/mode/owner/content drift")
        if ((directory_st.st_dev, directory_st.st_ino, directory_st.st_mode,
             directory_st.st_uid, directory_st.st_nlink) !=
            (directory_after.st_dev, directory_after.st_ino, directory_after.st_mode,
             directory_after.st_uid, directory_after.st_nlink)
                or (directory_after.st_dev, directory_after.st_ino) !=
                   (directory_path_after.st_dev, directory_path_after.st_ino)):
            raise ValueError("inherited GPU lock directory changed during validation")
        return {"device": lease_st.st_dev, "inode": lease_st.st_ino}
    finally:
        os.close(directory_fd)


def _technical_failure(reason: str, broker_pid: int, worker_pid: int | None) -> None:
    payload = {"schema_version": "msae_v3_technical_failure_v3", "protocol_id": PROTOCOL,
               "status": "not_run", "reason": reason, "broker_pid": broker_pid,
               "worker_pid": worker_pid, "stage_b_written": False}
    commit_terminal_failure(ACTIVE_RUN_ROOT, payload)


def enforce_live_gpu_lease(lease_fd: int, gpu_uuid: str, broker_pid: int,
                           worker_pid: int) -> None:
    """Turn any persistent lock path/directory drift into a terminal not-run."""
    try:
        _validate_gpu_lock_fd(lease_fd, gpu_uuid)
    except BaseException as error:
        with contextlib.suppress(Exception):
            _terminate_group(worker_pid)
        _technical_failure(f"gpu_lease_loss:{type(error).__name__}:{error}",
                           broker_pid, worker_pid)
        raise RuntimeError("GPU UUID lease identity was lost") from error


def _claim_terminal(run_root: Path, kind: str) -> bool:
    claim = run_root / "terminal.claim"
    try:
        base.write_once(claim, base.canonical_bytes({"schema_version": "msae_v3_terminal_claim_v1",
                                                     "kind": kind}), 0o600)
        base._fsync_directory(run_root)
        return True
    except FileExistsError:
        return False


def commit_terminal_failure(run_root: Path, payload: Mapping[str, Any]) -> bool:
    if (run_root / "terminal_success").exists():
        return False
    claim = run_root / "terminal.claim"
    if not claim.exists():
        if not _claim_terminal(run_root, "technical_failure"):
            raise RuntimeError("terminal claim race")
    else:
        claim_value = base.read_json(claim)
        if claim_value.get("kind") not in {"technical_failure", "valid_calibration_completion"}:
            raise ValueError("unknown terminal claim")
        if (run_root / "terminal_failure").is_dir():
            return True
        # The broker only calls this after the worker is dead.  An incomplete
        # success staging tree must never strand the run without a terminal
        # outcome after a write/fsync failure or kill.
    shutil.rmtree(run_root / ".terminal_success_staging", ignore_errors=True)
    staging = run_root / ".terminal_failure_staging"
    final = run_root / "terminal_failure"
    if staging.exists():
        shutil.rmtree(staging)
    staging.mkdir(mode=0o700)
    os.chmod(staging, 0o700)
    base.write_once(staging / "technical_failure.json", base.canonical_bytes(dict(payload)), 0o600)
    status = {"schema_version": "msae_v3_runtime_status_v2",
              "status": "technical_failure_not_run", "stage_b_ready": False,
              "technical_failure_sha256": base.sha_file(staging / "technical_failure.json")}
    base.write_once(staging / "status.json", base.canonical_bytes(status), 0o600)
    base._fsync_directory(staging)
    os.rename(staging, final)
    base._fsync_directory(run_root)
    return True


def commit_terminal_success(run_root: Path, files: Mapping[str, bytes]) -> Path:
    expected = {"stage_b.json", "status.json", "runtime_native_pre_import.json",
                "runtime_native_post_torch.json", "runtime_native_post_model.json",
                "runtime_native_final.json"}
    if set(files) != expected:
        raise ValueError("terminal-success file set mismatch")
    staging = run_root / ".terminal_success_staging"
    final = run_root / "terminal_success"
    if final.exists() or (run_root / "terminal_failure").exists():
        raise FileExistsError("terminal outcome already exists")
    if staging.exists():
        shutil.rmtree(staging)
    staging.mkdir(mode=0o700)
    os.chmod(staging, 0o700)
    try:
        for name in sorted(expected):
            base.write_once(staging / name, files[name], 0o600)
        base._fsync_directory(staging)
        if not _claim_terminal(run_root, "valid_calibration_completion"):
            claim = base.read_json(run_root / "terminal.claim")
            if claim.get("kind") != "valid_calibration_completion":
                raise FileExistsError("terminal failure already claimed")
        os.rename(staging, final)
        try:
            base._fsync_directory(run_root)
        except BaseException:
            os.rename(final, staging)
            with contextlib.suppress(Exception):
                base._fsync_directory(run_root)
            raise
    except BaseException:
        shutil.rmtree(staging, ignore_errors=True)
        raise
    return final


def _group_live_pids(pgid: int) -> list[int]:
    result = []
    for path in Path("/proc").iterdir():
        if not path.name.isdecimal():
            continue
        try:
            raw = (path / "stat").read_text(encoding="ascii")
            right = raw.rfind(")")
            fields = raw[right + 2:].split()
            # After comm: state=field 3, ppid=4, pgrp=5.
            if len(fields) > 2 and int(fields[2]) == pgid and fields[0] != "Z":
                result.append(int(path.name))
        except (FileNotFoundError, ProcessLookupError, PermissionError, ValueError):
            continue
    return sorted(result)


def _terminate_group(pgid: int, *, grace: float = 5.0) -> None:
    if pgid <= 1:
        return
    with contextlib.suppress(ProcessLookupError):
        os.killpg(pgid, signal.SIGTERM)
    deadline = time.monotonic() + grace
    while time.monotonic() < deadline:
        if not _group_live_pids(pgid):
            return
        time.sleep(0.05)
    with contextlib.suppress(ProcessLookupError):
        os.killpg(pgid, signal.SIGKILL)
    deadline = time.monotonic() + 2
    while time.monotonic() < deadline:
        if not _group_live_pids(pgid):
            return
        time.sleep(0.05)
    raise RuntimeError(f"worker process group survived KILL: {pgid}")


def install_parent_death_watchdog(expected_parent: int) -> None:
    """Arm Linux parent-death SIGKILL and close the fork/arm race."""
    import ctypes
    libc = ctypes.CDLL(None, use_errno=True)
    if libc.prctl(1, signal.SIGKILL, 0, 0, 0) != 0 or os.getppid() != expected_parent:
        raise RuntimeError("worker parent-death watchdog setup failed")


def confirm_pre_model_gate(final_ack_fd: int, confirmed_fd: int) -> None:
    """Cross the durable handoff gate; callers may import models only afterward."""
    try:
        if os.read(final_ack_fd, 1) != b"F":
            raise RuntimeError("durable launcher handoff acknowledgement missing")
    finally:
        os.close(final_ack_fd)
    try:
        os.write(confirmed_fd, b"A")
    finally:
        os.close(confirmed_fd)


def worker_environment(gpu_uuid: str, lease_fd: int, readiness_fd: int,
                       final_ack_fd: int, confirmed_fd: int) -> dict[str, str]:
    """Return the exact closed worker environment; inherited keys never survive."""
    if re.fullmatch(r"GPU-[0-9A-Fa-f-]{16,}", gpu_uuid, re.ASCII) is None:
        raise ValueError("malformed worker GPU UUID")
    if any(fd < 0 for fd in (lease_fd, readiness_fd, final_ack_fd, confirmed_fd)):
        raise ValueError("worker descriptor number is negative")
    return {**FROZEN_BASE_PROCESS_ENVIRONMENT, **FROZEN_WORKER_ENVIRONMENT,
            "CUDA_VISIBLE_DEVICES": gpu_uuid, "MSAE_LEASE_FD": str(lease_fd),
            "MSAE_GPU_UUID": gpu_uuid, "MSAE_READINESS_FD": str(readiness_fd),
            "MSAE_FINAL_ACK_FD": str(final_ack_fd),
            "MSAE_CONFIRMED_FD": str(confirmed_fd)}


def _validate_launcher_intent(socket_path: str, gpu_uuid: str, gpu_index: int,
                              launch_capability: str, intent_sha256: str,
                              lease_fd: int | None = None) -> dict[str, Any]:
    """Authenticate launcher-only internal broker/supervisor entrypoints."""
    if (re.fullmatch(r"[0-9a-f]{64}", launch_capability, re.ASCII) is None
            or re.fullmatch(r"[0-9a-f]{64}", intent_sha256, re.ASCII) is None):
        raise ValueError("malformed launcher capability or intent digest")
    raw = _regular_bytes(LAUNCH_INTENT, mode=0o600)
    intent = base.strict_json_loads(raw.decode("utf-8"))
    if raw != base.canonical_bytes(intent) or base.sha_bytes(raw) != intent_sha256:
        raise ValueError("launcher intent canonical bytes/digest mismatch")
    lock_path = base.GPU_LOCK_DIR / f"{base.sha_bytes(gpu_uuid.encode('ascii'))}.lock"
    lock_st = lock_path.lstat()
    stage_sha256 = base.sha_file(ACTIVE_PROV / "stage_a.json")
    tmux_path, broker_path, pane_path = _tmux_paths(stage_sha256)
    expected = {
        "schema_version": "msae_v3_launcher_intent_v1", "protocol_id": PROTOCOL,
        "socket_path": str(broker_path), "tmux_socket_path": str(tmux_path),
        "pane_socket_path": str(pane_path),
        "gpu_uuid": gpu_uuid, "gpu_index": gpu_index,
        "lock_path": str(lock_path), "lock_device": lock_st.st_dev,
        "lock_inode": lock_st.st_ino,
        "stage_a_sha256": base.sha_file(ACTIVE_PROV / "stage_a.json"),
        "authorization_envelope_sha256": base.sha_file(
            ACTIVE_RUN_ROOT / "authorization.json"),
        "launch_capability_sha256": base.sha_bytes(launch_capability.encode("ascii")),
        "launcher_pid": intent.get("launcher_pid"),
        "launcher_start_ticks": intent.get("launcher_start_ticks"),
    }
    if intent != expected or socket_path != expected["socket_path"]:
        raise ValueError("launcher intent exact socket/GPU/lock lineage mismatch")
    launcher_pid = intent.get("launcher_pid")
    launcher_ticks = intent.get("launcher_start_ticks")
    if (type(launcher_pid) is not int or not isinstance(launcher_ticks, str)
            or not launcher_ticks.isdecimal()
            or not _pid_has_start_ticks(launcher_pid, launcher_ticks)):
        raise ValueError("launcher intent process is not live")
    if lease_fd is not None:
        lease_st = os.fstat(lease_fd)
        if (lease_st.st_dev, lease_st.st_ino) != (lock_st.st_dev, lock_st.st_ino):
            raise ValueError("launcher intent does not bind inherited lease FD")
    return intent


def broker(socket_path: str, gpu_uuid: str, gpu_index: int,
           launch_capability: str, intent_sha256: str) -> None:
    _validate_launcher_intent(socket_path, gpu_uuid, gpu_index,
                              launch_capability, intent_sha256)
    log_fd = os.open(ACTIVE_RUN_ROOT / "logs/broker.log",
                     os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    os.fchmod(log_fd, 0o600)
    os.dup2(log_fd, 1); os.dup2(log_fd, 2)
    if log_fd > 2:
        os.close(log_fd)
    broker_pid = os.getpid()
    sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    deadline = time.monotonic() + 15
    while True:
        try:
            sock.connect(socket_path)
            break
        except (FileNotFoundError, ConnectionRefusedError):
            if time.monotonic() >= deadline:
                raise
            time.sleep(0.05)
    _send_json(sock, {"schema_version": "msae_v3_broker_hello_v2", "pid": broker_pid,
                      "start_ticks": base._start_ticks(broker_pid), "sid": os.getsid(0),
                      "pgid": os.getpgrp(), "supervisor_pid": os.getppid(),
                      "supervisor_start_ticks": base._start_ticks(os.getppid())})
    lease_fd = _receive_fd(sock)
    os.set_inheritable(lease_fd, True)
    fcntl.flock(lease_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    _validate_gpu_lock_fd(lease_fd, gpu_uuid)
    _validate_launcher_intent(socket_path, gpu_uuid, gpu_index,
                              launch_capability, intent_sha256, lease_fd)
    gate_r, gate_w = os.pipe()
    ready_r, ready_w = os.pipe()
    final_ack_r, final_ack_w = os.pipe()
    confirmed_r, confirmed_w = os.pipe()
    worker_pid = os.fork()
    if worker_pid == 0:
        os.close(gate_w); os.close(ready_r); os.close(final_ack_w); os.close(confirmed_r)
        try:
            os.setpgid(0, 0)
            install_parent_death_watchdog(broker_pid)
            if os.read(gate_r, 1) != b"G":
                raise RuntimeError("launcher gate missing")
            os.close(gate_r)
            worker_log = os.open(ACTIVE_RUN_ROOT / "logs/worker.log",
                                 os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
            os.fchmod(worker_log, 0o600)
            os.dup2(worker_log, 1); os.dup2(worker_log, 2)
            if worker_log > 2:
                os.close(worker_log)
            environment = worker_environment(
                gpu_uuid, lease_fd, ready_w, final_ack_r, confirmed_w)
            for fd in (ready_w, final_ack_r, confirmed_w):
                os.set_inheritable(fd, True)
            argv = [str(ROOT / ".venv-atlas/bin/python"), "-S", "-B", "-I", str(RUNNER.resolve()),
                    "--run-root", ACTIVE_RUN_REL, "--gpu-uuid", gpu_uuid,
                    "--broker-pid", str(broker_pid), "--readiness-fd", str(ready_w),
                    "--final-ack-fd", str(final_ack_r), "--confirmed-fd", str(confirmed_w)]
            os.execve(argv[0], argv, environment)
        except BaseException as error:
            _technical_failure(f"worker_setup:{type(error).__name__}:{error}", broker_pid, os.getpid())
            os._exit(125)
    worker_started = time.monotonic()
    os.close(gate_r); os.close(ready_w); os.close(final_ack_r); os.close(confirmed_w)
    os.setpgid(worker_pid, worker_pid)
    worker = {"schema_version": "msae_v3_worker_handoff_v2", "broker_pid": broker_pid,
              "broker_start_ticks": base._start_ticks(broker_pid), "worker_pid": worker_pid,
              "worker_start_ticks": base._start_ticks(worker_pid), "worker_pgid": worker_pid,
              "gpu_uuid": gpu_uuid, "gpu_index": gpu_index,
              "launcher_intent_sha256": intent_sha256}
    _send_json(sock, worker)
    sock.settimeout(15)
    if sock.recv(1) != b"G":
        _terminate_group(worker_pid)
        _technical_failure("launcher_handoff_ack_missing", broker_pid, worker_pid)
        raise RuntimeError("launcher acknowledgement missing")
    os.write(gate_w, b"G"); os.close(gate_w)
    ready_deadline = time.monotonic() + 120
    readiness = b""
    os.set_blocking(ready_r, False)
    while time.monotonic() < ready_deadline:
        try:
            readiness += os.read(ready_r, 4096)
        except BlockingIOError:
            pass
        if readiness.endswith(b"\n"):
            break
        pid, status = os.waitpid(worker_pid, os.WNOHANG)
        if pid == worker_pid:
            _technical_failure(f"worker_exit_before_readiness:{status}", broker_pid, worker_pid)
            raise RuntimeError("worker exited before readiness")
        time.sleep(0.05)
    os.close(ready_r)
    if not readiness.endswith(b"\n"):
        _terminate_group(worker_pid)
        _technical_failure("runner_readiness_timeout", broker_pid, worker_pid)
        raise RuntimeError("runner readiness timeout")
    ready = base.strict_json_loads(readiness.decode("utf-8"))
    if ready.get("schema_version") != "msae_v3_runner_ready_v1" or ready.get("worker_pid") != worker_pid:
        _terminate_group(worker_pid)
        raise ValueError("invalid runner readiness")
    _send_json(sock, ready)
    sock.settimeout(30)
    if sock.recv(1) != b"F":
        _terminate_group(worker_pid)
        _technical_failure("launcher_final_model_gate_missing", broker_pid, worker_pid)
        raise RuntimeError("launcher final model gate missing")
    os.write(final_ack_w, b"F"); os.close(final_ack_w)
    os.set_blocking(confirmed_r, False)
    confirmed = b""
    confirmation_deadline = min(worker_started + 6 * 60 * 60, time.monotonic() + 30)
    while time.monotonic() < confirmation_deadline:
        try:
            confirmed += os.read(confirmed_r, 1)
        except BlockingIOError:
            pass
        if confirmed == b"A":
            break
        pid, status = os.waitpid(worker_pid, os.WNOHANG)
        if pid == worker_pid:
            _technical_failure(f"worker_exit_before_model_gate_confirmation:{status}",
                               broker_pid, worker_pid)
            raise RuntimeError("worker exited before confirming model gate")
        time.sleep(0.05)
    os.close(confirmed_r)
    if confirmed != b"A":
        _terminate_group(worker_pid)
        _technical_failure("runner_model_gate_confirmation_timeout", broker_pid, worker_pid)
        raise RuntimeError("runner model-gate confirmation timeout")
    _send_json(sock, {"schema_version": "msae_v3_model_gate_open_v1",
                      "worker_pid": worker_pid, "pre_model": True})
    sock.close()
    while True:
        enforce_live_gpu_lease(lease_fd, gpu_uuid, broker_pid, worker_pid)
        pid, status = os.waitpid(worker_pid, os.WNOHANG)
        if pid == worker_pid:
            enforce_live_gpu_lease(lease_fd, gpu_uuid, broker_pid, worker_pid)
            if not (os.WIFEXITED(status) and os.WEXITSTATUS(status) == 0):
                _technical_failure(f"worker_exit_status:{status}", broker_pid, worker_pid)
            break
        if time.monotonic() - worker_started >= 6 * 60 * 60:
            _terminate_group(worker_pid, grace=60)
            with contextlib.suppress(ChildProcessError):
                os.waitpid(worker_pid, 0)
            _technical_failure("six_hour_timeout", broker_pid, worker_pid)
            raise SystemExit(124)
        time.sleep(1)
    os.close(lease_fd)


def _supervise_broker_process(argv: Sequence[str], environment: Mapping[str, str],
                              *, tmux_path: Path | None = None,
                              tmux_identity: Mapping[str, int] | None = None,
                              monitor_identity: tuple[int, str] | None = None) -> int:
    process = subprocess.Popen(list(argv), env=dict(environment))
    process_start_ticks = base._start_ticks(process.pid)
    received_signal: list[int] = []

    def forward_signal(signum: int, _frame: Any) -> None:
        # The supervisor is the tmux pane process.  It must not disappear and
        # strand a broker/worker when tmux or the launcher terminates it during
        # a failed handoff.  Forward first, then let the ordinary post-wait
        # extinction/terminal path below run in this still-live supervisor.
        received_signal.append(signum)
        with contextlib.suppress(ProcessLookupError):
            process.send_signal(signal.SIGTERM)

    previous_handlers: dict[int, Any] = {}
    for signum in (signal.SIGTERM, signal.SIGHUP):
        previous_handlers[signum] = signal.getsignal(signum)
        signal.signal(signum, forward_signal)
    try:
        while process.poll() is None:
            if (monitor_identity is not None
                    and not _pid_has_start_ticks(
                        monitor_identity[0], monitor_identity[1])):
                received_signal.append(signal.SIGCHLD)
                with contextlib.suppress(ProcessLookupError):
                    process.terminate()
            if received_signal:
                try:
                    returncode = process.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    process.kill()
                    returncode = process.wait(timeout=5)
                break
            time.sleep(0.05)
        else:
            returncode = int(process.returncode)
    finally:
        # Keep the serialized handlers installed through the entire cleanup;
        # killing the current tmux session may deliver a second HUP.
        pass
    lock_record_path = ACTIVE_RUN_ROOT / "lock_acquired.json"
    if lock_record_path.exists() and not lock_record_path.is_symlink():
        try:
            record_raw = _regular_bytes(lock_record_path, mode=0o644)
            record = base.strict_json_loads(record_raw.decode("utf-8"))
            if record_raw != base.canonical_bytes(record):
                raise ValueError("supervisor lock record is noncanonical")
            worker_pid = int(record["worker_pid"])
            worker_ticks = int(record["worker_start_ticks"])
            worker_pgid = int(record["worker_pgid"])
            if worker_pgid != worker_pid:
                raise ValueError("supervisor lock record has noncanonical worker PGID")
            # The leader may already be dead while grandchildren in its process
            # group survive.  Group membership, not leader liveness, controls
            # whether extinction is still required.
            if _pid_has_start_ticks(worker_pid, worker_ticks) or _group_live_pids(worker_pgid):
                _terminate_group(worker_pgid)
        except BaseException as error:
            _technical_failure(f"supervisor_worker_extinction:{type(error).__name__}:{error}",
                               process.pid, None)
            raise
    if not (ACTIVE_RUN_ROOT / "terminal_success").is_dir() and not (
            ACTIVE_RUN_ROOT / "terminal_failure").is_dir():
        suffix = (f"supervisor_signal:{received_signal[-1]}" if received_signal
                  else f"broker_exit:{returncode}")
        _technical_failure(suffix, process.pid, None)
    containment_required = bool(received_signal or returncode != 0 or (
        monitor_identity is not None
        and not _pid_has_start_ticks(monitor_identity[0], monitor_identity[1])))
    if containment_required and tmux_path is not None and tmux_identity is not None:
        identities: list[tuple[int, int | str]] = [
            (process.pid, process_start_ticks)
        ] if _pid_has_start_ticks(process.pid, process_start_ticks) else []
        if monitor_identity is not None:
            identities.append(monitor_identity)
        _verify_failed_handoff_extinction(
            tmux_path, "msae-independent-v3-gen9-calibration", identities,
            tmux_identity)
    for signum, handler in previous_handlers.items():
        signal.signal(signum, handler)
    return returncode


def supervise_broker(socket_path: str, gpu_uuid: str, gpu_index: int,
                     launch_capability: str, intent_sha256: str) -> None:
    intent = _validate_launcher_intent(socket_path, gpu_uuid, gpu_index,
                                       launch_capability, intent_sha256)
    record_path = ACTIVE_RUN_ROOT / "tmux_monitor.json"
    record_raw = _regular_bytes(record_path, mode=0o600)
    record = base.strict_json_loads(record_raw.decode("utf-8"))
    if record_raw != base.canonical_bytes(record):
        raise ValueError("pane monitor record canonical bytes drift")
    _validate_monitor_record(record)
    tmux_path, broker_path, pane_path = _tmux_paths(
        base.sha_file(ACTIVE_PROV / "stage_a.json"))
    broker_argv = [str(ROOT / ".venv-atlas/bin/python"), "-S", "-B", "-I",
                   str(continuation.CONTROLLER_PATH), "broker-gen9",
                   "--socket", socket_path, "--gpu-uuid", gpu_uuid,
                   "--gpu-index", str(gpu_index), "--launch-capability",
                   launch_capability, "--intent-sha256", intent_sha256]
    config = {
        "schema_version": "msae_v3_gen9_foreground_tmux_config_v1",
        "variant": "production", "role": "pane_supervisor",
        "tmp_parent_binding": _tmp_parent_binding(),
        "tmux_socket_path": str(tmux_path),
        "broker_socket_path": str(broker_path),
        "pane_socket_path": str(pane_path),
        "scratch_root": str(ACTIVE_RUN_ROOT),
        "session": "msae-independent-v3-gen9-calibration",
        "monitor_record_path": str(record_path),
        "monitor_record_sha256": None, "control_fd": None,
        "broker_cleanup_fd": None, "broker_socket_binding": None,
        "pane_listener_fd": None,
        "monitor_log_path": str(ACTIVE_RUN_ROOT / "logs/monitor.log"),
        "server_log_path": str(ACTIVE_RUN_ROOT / "logs/tmux_server.log"),
        "monitor_log_fd": None, "server_log_fd": None,
        "monitor_log_binding": None, "server_log_binding": None,
        "broker_argv": broker_argv, "lease_fd": None,
        "gpu": {"uuid": gpu_uuid, "index": gpu_index},
        "lease_binding": dict(record["lease"]),
        "evidence_retention": "retain_run_logs",
        "expected_uid": os.getuid(), "expected_gid": os.getgid(),
        "umask": 0o077,
        "start_deadline_monotonic_ns": time.monotonic_ns() + 30_000_000_000,
        "terminal_deadline_unix": int(record["terminal_deadline_unix"]),
        "cleanup_budget": dict(PRODUCTION_CLEANUP_BUDGET),
        "fault_event_fd": None, "fault_event_binding": None,
    }
    foreground_tmux_start_v1(config, _disabled_fault_control())


def _supervise_broker_implementation(
        socket_path: str, gpu_uuid: str, gpu_index: int,
        launch_capability: str, intent_sha256: str, *,
        fault_control: Mapping[str, Any] | None = None,
        fault_event_fd: int | None = None,
        fault_event_binding: Mapping[str, Any] | None = None) -> None:
    checked_fault = _validate_fault_control(
        _disabled_fault_control() if fault_control is None else fault_control)
    fault_fired: set[str] = set()
    intent = _validate_launcher_intent(socket_path, gpu_uuid, gpu_index,
                                       launch_capability, intent_sha256)
    monitor_record_path = ACTIVE_RUN_ROOT / "tmux_monitor.json"
    record_raw = _regular_bytes(monitor_record_path, mode=0o600)
    record = base.strict_json_loads(record_raw.decode("utf-8"))
    if record_raw != base.canonical_bytes(record):
        raise ValueError("pane supervisor monitor record is noncanonical")
    _validate_monitor_record(record)
    stage_sha256 = base.sha_file(ACTIVE_PROV / "stage_a.json")
    tmux_path, broker_path, pane_path = _tmux_paths(stage_sha256)
    expected_lock = _exact_path_binding(
        Path(str(intent["lock_path"])), kind="regular", mode=0o600,
        include_sha256=True)
    expected_monitor_log = _exact_path_binding(
        ACTIVE_RUN_ROOT / "logs/monitor.log", kind="regular", mode=0o600)
    expected_server_log = _exact_path_binding(
        ACTIVE_RUN_ROOT / "logs/tmux_server.log", kind="regular", mode=0o600)
    if (record["stage_a_sha256"] != stage_sha256
            or record["authorization_envelope_sha256"] !=
               base.sha_file(ACTIVE_RUN_ROOT / "authorization.json")
            or record["launcher_intent_sha256"] != intent_sha256
            or record["launch_capability_sha256"] !=
               base.sha_bytes(launch_capability.encode("ascii"))
            or record["gpu"] != {"uuid": gpu_uuid, "index": gpu_index}
            or record["lease"] != {
                "path": expected_lock["path"], "device": expected_lock["device"],
                "inode": expected_lock["inode"], "uid": expected_lock["uid"],
                "gid": expected_lock["gid"], "mode": expected_lock["mode"],
                "nlink": expected_lock["nlink"],
                "payload_sha256": expected_lock["sha256"],
                "gpu_uuid": gpu_uuid}
            or record["launcher"] != {
                "pid": int(intent["launcher_pid"]),
                "start_ticks": intent["launcher_start_ticks"]}
            or record["code"] != {
                "controller_sha256": base.sha_file(continuation.CONTROLLER_PATH),
                "runtime_sha256": base.sha_file(RUNTIME),
                "dependency_closure_sha256": base.sha_file(
                    ACTIVE_M4_DATA / "dependency_closure.json")}
            or record["logs"] != {
                "monitor": expected_monitor_log, "server": expected_server_log}
            or record["tmux_socket_path"] != str(tmux_path)
            or record["broker_socket_path"] != str(broker_path)
            or record["pane_socket_path"] != str(pane_path)
            or socket_path != str(broker_path)
            or record["monitor"]["pgid"] != record["monitor"]["pid"]):
        raise ValueError("pane supervisor monitor/socket lineage drift")
    tmux_identity = _tmux_socket_identity(tmux_path)
    monitor_identity = (int(record["monitor"]["pid"]),
                        str(record["monitor"]["start_ticks"]))
    if not _pid_has_start_ticks(*monitor_identity):
        previous_hup = signal.getsignal(signal.SIGHUP)
        signal.signal(signal.SIGHUP, lambda _signum, _frame: None)
        try:
            _verify_failed_handoff_extinction(
                tmux_path, "msae-independent-v3-gen9-calibration",
                [monitor_identity], tmux_identity)
            _technical_failure("pane_supervisor_observed_monitor_death", os.getpid(), None)
        finally:
            signal.signal(signal.SIGHUP, previous_hup)
        raise RuntimeError("tmux monitor died before broker start")
    pane_lease_fd, _pane_arm_subject = _pane_acquire_production_lease(
        pane_path, record, record_raw, monitor_identity,
        fault_control=checked_fault, fault_event_fd=fault_event_fd,
        fault_event_binding=fault_event_binding, fired=fault_fired)
    argv = [str(ROOT / ".venv-atlas/bin/python"), "-S", "-B", "-I",
            str(continuation.CONTROLLER_PATH), "broker-gen9", "--socket", socket_path,
            "--gpu-uuid", gpu_uuid, "--gpu-index", str(gpu_index),
            "--launch-capability", launch_capability,
            "--intent-sha256", intent_sha256]
    try:
        returncode = _supervise_broker_process(
            argv, FROZEN_BASE_PROCESS_ENVIRONMENT, tmux_path=tmux_path,
            tmux_identity=tmux_identity,
            monitor_identity=monitor_identity)
    finally:
        cleanup_errors: list[str] = []
        owned_socket_rows = (() if _pid_has_start_ticks(*monitor_identity) else (
            (pane_path, "pane_listener_binding"),
            (broker_path, "broker_socket_binding")))
        for path, key in owned_socket_rows:
            try:
                if _path_present(path):
                    expected = {name: record["control"][key][name] for name in
                                ("device", "inode", "uid", "gid", "mode", "nlink")}
                    if _tmux_socket_identity(path) != expected:
                        raise RuntimeError("pane cleanup socket identity drift")
                    _unlink_bound_tmp_socket(path, expected)
            except BaseException as error:
                cleanup_errors.append(f"{path.name}:{type(error).__name__}:{error}")
        try:
            os.close(pane_lease_fd)
        except OSError as error:
            cleanup_errors.append(f"lease_close:{error}")
        if cleanup_errors:
            raise RuntimeError("pane cleanup incomplete: " + ";".join(cleanup_errors))
    if returncode != 0:
        raise SystemExit(returncode if 0 < returncode < 256 else 125)



def _read_fd_all(fd: int) -> bytes:
    position = os.lseek(fd, 0, os.SEEK_CUR)
    try:
        os.lseek(fd, 0, os.SEEK_SET)
        chunks: list[bytes] = []
        while True:
            chunk = os.read(fd, 65536)
            if not chunk: break
            chunks.append(chunk)
        return b"".join(chunks)
    finally:
        os.lseek(fd, position, os.SEEK_SET)


